/* 臨床心理 院試ノート：用語説明（独自作成。build.py で生成） */
window.SI_FIELDS = [{"id":"rinsho","name":"臨床心理学・心理療法","short":"臨床","d":"主要な心理療法の理論と技法。人間観・治療目標・治療関係の違いを押さえる。日本で生まれた心理療法も含む。"},{"id":"seishin","name":"精神分析・力動論","short":"精神分析","d":"フロイトから対象関係論・自己心理学・現代の精神分析まで。日本の精神分析（甘え・阿闍世）や治療構造論も含む。"},{"id":"jung","name":"分析心理学（ユング）","short":"ユング","d":"集合的無意識と元型、個性化、夢と象徴の理解。昔話・神話の理解や、箱庭など日本での展開も含む。"},{"id":"trauma","name":"トラウマ・被害者支援・危機介入","short":"トラウマ","d":"PTSDと複雑性PTSD、トラウマに焦点を当てた治療、被害者支援と二次被害、支援者自身のケア。"},{"id":"iryo","name":"精神医学・医療・老年","short":"医療","d":"診断分類と主な精神疾患、心身医学、小児医療・緩和ケア・認知症の人への支援、医療の中での連携。"},{"id":"assess","name":"心理アセスメント","short":"アセスメント","d":"投映法・質問紙法・知能検査・発達検査、テスト・バッテリー、見立てと所見の伝え方。"},{"id":"hattatsu","name":"発達・家族・教育","short":"発達","d":"愛着、生涯発達、子どもと家族の臨床、学校臨床と関連する法制度。"},{"id":"kiso","name":"基礎心理学","short":"基礎","d":"学習・記憶・感情・動機づけ・社会心理学など、臨床の土台になる基礎研究。"},{"id":"neuro","name":"知覚・神経・生理","short":"神経","d":"感覚・知覚の仕組み、注意、神経細胞と脳の働き、脳機能の計測法。公開されている過去問では毎回のように出題される基礎領域。"},{"id":"social","name":"社会・パーソナリティ・文化","short":"社会","d":"対人認知、態度と説得、集団、文化、パーソナリティ理論。公開されている過去問では語句・論述の両方で毎回出題される基礎領域。"},{"id":"kenkyu","name":"研究法・統計","short":"研究法","d":"信頼性と妥当性、研究デザイン、統計的推論、質的研究、研究倫理。研究計画書と口述試験の質疑にも直結する。"},{"id":"rinri","name":"倫理・制度・コミュニティ","short":"制度","d":"職業倫理と法制度、資格、コミュニティ心理学、予防とコンサルテーション、多職種連携。"}];
window.SI_TERMS = (window.SI_TERMS || []).concat([{"id":"rogers-cct","t":"来談者中心療法","en":"client-centered therapy","f":"rinsho","s":"ロジャーズが創始した心理療法。人の実現傾向を信頼し、治療者の自己一致・無条件の肯定的配慮・共感的理解を備えた関係の中で、クライエントが自ら成長し変化していくことを重視する。","a":"ロジャーズ（Rogers, C. R.）が1940年代に非指示的療法として提唱し、のちにパーソン・センタード・アプローチへと発展した心理療法。人は本来、成長し自己を実現しようとする実現傾向をもつという人間観に立つ。治療者が自己一致・無条件の肯定的配慮・共感的理解を備えた関係を提供すれば、クライエントは自己概念と経験のずれを自ら修正し、より柔軟な自己を生きられるようになると考える。技法よりも、治療者の態度と関係そのものを重視する点に特徴がある。","k":["ロジャーズ/Rogers","実現傾向","自己一致","無条件の肯定的配慮","共感的理解","自己概念"],"p":"「非指示的」から「来談者中心」へと呼び名が変わった経緯（技法から態度へ）にふれると厚みが出る。精神分析（解釈・転移）や行動療法（技法・学習）との対比で問われやすい。"},{"id":"rogers-cond","t":"治療的人格変化の必要十分条件","en":"necessary and sufficient conditions","f":"rinsho","s":"ロジャーズ（1957）が示した、建設的な人格変化が起こるための6条件。心理的接触、クライエントの不一致、治療者の一致、無条件の肯定的配慮、共感的理解、それらが伝わっていることからなる。","a":"ロジャーズが1957年に示した、建設的な人格変化が起こるための6つの条件。①二人の人が心理的な接触をもっている、②クライエントは不一致の状態にあり、傷つきやすく不安である、③治療者は関係の中で一致し統合されている、④治療者はクライエントに無条件の肯定的配慮を経験している、⑤治療者は共感的理解を経験し、それを伝えようとしている、⑥それらが最低限クライエントに伝わっている。③④⑤は中核3条件と呼ばれる。","k":["1957","心理的な接触/心理的接触","不一致","無条件の肯定的配慮","共感的理解","伝わ"],"p":"「3条件」だけを書く答案が多い。6条件全体と、とくに⑥「伝わっていること」の意味（治療者の内面だけでは足りない）まで書けると差がつく。"},{"id":"congruence","t":"自己一致（純粋性）","en":"congruence / genuineness","f":"rinsho","s":"ロジャーズの中核条件の一つで、純粋性ともいう。治療者が関係の中で体験していることと、意識し表明していることとが一致しており、役割や仮面の陰に隠れていない状態。","a":"ロジャーズの中核条件の一つで、純粋性とも呼ばれる。治療者が関係の中で体験していることと、意識していること、表明していることが一致している状態をいう。治療者が専門家という役割や仮面の陰に隠れず、自分の内に生じる感情に開かれていることを指し、思ったことを何でも口にすることとは異なる。治療者の自己一致は、クライエントが自分の体験に開かれていくためのモデルとなり、無条件の肯定的配慮や共感が本物として伝わるための土台にもなる。","k":["ロジャーズ","純粋性","体験","一致","仮面/役割"],"p":"「何でも正直に言う」ことと区別できるかが問われる。共感・受容が「技法」として演じられると不一致になる、という論点も使える。"},{"id":"behavior-therapy","t":"行動療法","en":"behavior therapy","f":"rinsho","s":"学習理論にもとづき、不適応行動を学習の結果ととらえ、条件づけの原理を用いて行動の変容をはかる心理療法の総称。系統的脱感作法やエクスポージャー、オペラント技法などがある。","a":"学習理論にもとづき、不適応な行動を、誤って学習された、あるいは適切な行動が未学習である結果ととらえ、学習の原理を用いて行動の変容をめざす心理療法の総称。レスポンデント条件づけにもとづく系統的脱感作法やエクスポージャー法、オペラント条件づけにもとづく強化、シェイピング、トークン・エコノミーなどがある。1950年代にウォルピやアイゼンクらにより体系化された。観察可能な行動と効果の測定を重視し、のちの認知行動療法の基盤となった。","k":["学習理論","系統的脱感作/エクスポージャー","オペラント","ウォルピ/Wolpe","認知行動療法"],"p":"「内面を扱わない」と単純化せず、問題を具体的に定義し、効果を測って検証する姿勢が臨床心理学の科学化に果たした役割にふれるとよい。"},{"id":"sd","t":"系統的脱感作法","en":"systematic desensitization","f":"rinsho","s":"ウォルピが逆制止の原理にもとづいて考案した技法。リラクセーションを身につけたうえで、不安階層表の弱い場面から順にイメージさせ、不安反応を段階的に消去していく。","a":"ウォルピ（Wolpe, J.）が逆制止の原理にもとづいて考案した行動療法の技法。まず筋弛緩法などでリラックス反応を身につけ、次に不安を引き起こす場面を弱いものから強いものへ並べた不安階層表を作る。リラックスした状態で、階層の低い場面から順にイメージし、不安が生じなくなったら次の段階へ進む。不安と両立しない反応を対にして提示することで、不安反応を段階的に弱めていく方法であり、恐怖症などに用いられる。","k":["ウォルピ/Wolpe","逆制止","不安階層表","筋弛緩/リラックス","恐怖症"],"p":"現在はリラクセーションを必須としないエクスポージャー法が主流であることも添えると、知識の更新ができていることを示せる。"},{"id":"cbt","t":"認知行動療法","en":"cognitive behavioral therapy","f":"rinsho","s":"出来事の受け止め方（認知）と行動に働きかけて、感情や問題の改善をはかる心理療法の総称。協働的経験主義のもと構造化された面接を行い、認知再構成やエクスポージャーなどを用いる。","a":"感情や行動は、出来事そのものよりも、その受け止め方（認知）に影響されるという考えに立ち、認知と行動の両面に働きかけて問題の改善をはかる心理療法の総称。ベックの認知療法、エリスの論理療法、行動療法の技法が統合されて発展した。治療者とクライエントが協力して仮説を検証していく協働的経験主義のもと、問題を具体的に定式化し、セルフモニタリング、認知再構成、行動活性化、エクスポージャーなどを用いる。構造化されており、ホームワークを重視する。","k":["認知","ベック/Beck","協働的経験主義","認知再構成","ホームワーク"],"p":"「第三世代」（マインドフルネス、ACT、DBT）との違い（認知の内容を変えるか、認知との関わり方を変えるか）を整理しておくと比較問題に対応しやすい。"},{"id":"auto-thought","t":"自動思考","en":"automatic thoughts","f":"rinsho","s":"ベックの認知療法の概念で、ある状況で意図せず瞬間的に浮かぶ考えやイメージ。気分や行動に直接影響し、背後にある中核信念（スキーマ）から生じるとされる。","a":"ベック（Beck, A. T.）の認知療法の中心的な概念で、ある状況で意図せずに瞬間的に浮かぶ考えやイメージをいう。本人には事実そのものとして体験されやすく、抑うつや不安などの感情を直接に左右する。自動思考の背後には、より持続的な信念である中核信念（スキーマ）があり、それが「全か無か思考」「破局視」などの認知の歪みを生むと考えられる。治療では思考記録表などを用いて自動思考に気づき、その根拠と反証を検討して、より柔軟な考え方を探る。","k":["ベック/Beck","瞬間","スキーマ/中核信念","認知の歪み","思考記録"],"p":"自動思考 → 媒介信念 → 中核信念という階層構造まで書けると正確。うつ病の「認知の3徴（自己・世界・将来）」もあわせて覚える。"},{"id":"rebt","t":"論理療法（REBT）","en":"rational emotive behavior therapy","f":"rinsho","s":"エリスが創始した心理療法。出来事（A）ではなく信念（B）が結果（C）を生むとするABC理論にもとづき、「ねばならない」という非合理な信念に論駁（D）を加えて柔軟な信念に置き換える。","a":"エリス（Ellis, A.）が1950年代に創始した心理療法。出来事（A）が直接に感情や行動の結果（C）を生むのではなく、その間にある信念（B）が結果を決めるとするABC理論を中核とする。とくに「〜ねばならない」という絶対的で非合理な信念（イラショナル・ビリーフ）が苦悩を生むと考え、それに論駁（D）を加えて、より合理的で柔軟な信念へと置き換え、効果（E）を得ることをめざす。ベックの認知療法と並ぶ、認知行動療法の源流の一つである。","k":["エリス/Ellis","ABC","イラショナル/非合理","論駁","ねばならない"],"p":"ベックの認知療法との違い（エリスはより直面的・説得的に論駁し、ベックは協働的に検証する）を一言添えると比較の視点が示せる。"},{"id":"mindfulness","t":"マインドフルネス","en":"mindfulness","f":"rinsho","s":"意図的に、今この瞬間の体験に、評価や判断を加えずに注意を向けること。カバットジンのMBSRや、うつ病の再発予防を目的とするMBCTとして心理療法に取り入れられた。","a":"意図的に、今この瞬間の体験に、評価や判断を加えずに注意を向けること、またそのような心のあり方をいう。仏教の瞑想に由来し、カバットジン（Kabat-Zinn, J.）が慢性疼痛などをもつ人を対象に、マインドフルネス・ストレス低減法（MBSR）として体系化した。さらに、うつ病の再発予防を目的とするマインドフルネス認知療法（MBCT）が開発された。思考の内容を変えるのではなく、思考や感情との関わり方を変える点で、従来の認知療法とは異なる。","k":["今この瞬間","判断/評価","カバットジン/Kabat-Zinn","MBSR/ストレス低減法","MBCT/マインドフルネス認知療法","再発予防"],"p":"「リラクセーション法」と混同しないこと。体験を変えようとせず観察する、という点が要点。"},{"id":"act","t":"アクセプタンス＆コミットメント・セラピー（ACT）","en":"acceptance and commitment therapy","f":"rinsho","s":"ヘイズらによる第三世代の認知行動療法。関係フレーム理論を背景に、体験の回避を減らし、アクセプタンスや脱フュージョンを通じて心理的柔軟性を高め、価値に沿った行動を促す。","a":"ヘイズ（Hayes, S. C.）らが開発した、いわゆる第三世代の認知行動療法。言語と認知に関する関係フレーム理論を背景に、苦痛な思考や感情を取り除こうとする「体験の回避」が、かえって苦しみを深め、生活を狭めると考える。アクセプタンス、脱フュージョン、今この瞬間との接触、文脈としての自己、価値、コミットされた行為の6つのプロセスを通じて心理的柔軟性を高め、本人が大切にする価値に沿った行動を広げていくことをめざす。","k":["ヘイズ/Hayes","関係フレーム理論","体験の回避","脱フュージョン","心理的柔軟性","価値"],"p":"症状の除去ではなく「価値に沿った生活」を目標にする点が、精神分析やロジャーズの人間観とどう響き合い、どう違うかを論じる材料になる。"},{"id":"dbt","t":"弁証法的行動療法（DBT）","en":"dialectical behavior therapy","f":"rinsho","s":"リネハンが境界性パーソナリティ障害の人のために開発した認知行動療法。受容と変化の弁証法を基本とし、個人療法とスキル・トレーニング（マインドフルネス、苦悩耐性、感情調節、対人関係）を組み合わせる。","a":"リネハン（Linehan, M. M.）が、自殺行動を繰り返す境界性パーソナリティ障害の人のために開発した認知行動療法。感情調節の困難は、生物学的な脆弱性と、感情を否定される環境との相互作用で生じるとする生物社会理論に立つ。受容と変化という対立するものを統合する弁証法を基本の姿勢とし、個人療法、スキル・トレーニング（マインドフルネス、苦悩耐性、感情調節、対人関係保持）、電話コーチング、治療者のコンサルテーション・チームを組み合わせる。","k":["リネハン/Linehan","境界性パーソナリティ","生物社会理論","受容","弁証法","スキル"],"p":"「受容と変化の弁証法」は、ロジャーズの受容と行動療法の変化をどう両立させるかという臨床の根本問題への一つの答えとして論じられる。"},{"id":"family-therapy","t":"家族療法（システムズ・アプローチ）","en":"family therapy","f":"rinsho","s":"個人の症状を家族システムの相互作用の中でとらえ、家族全体に働きかける心理療法。円環的因果律の視点に立ち、症状を示す人をIP（患者とみなされた人）と呼ぶ。","a":"個人の症状や問題を、その人の内面だけでなく、家族というシステムの相互作用の中でとらえ、家族全体に働きかける心理療法。一般システム理論やサイバネティクスを背景に、原因と結果が互いに影響し合って循環する円環的因果律で問題をみる。症状を示す人をIP（患者とみなされた人）と呼び、症状が家族の均衡（ホメオスタシス）を保つ役割を担っていることもあると考える。構造派（ミニューチン）、戦略派、ミラノ派、多世代派（ボーエン）など多くの学派がある。","k":["システム","円環的因果律","IP/患者とみなされた","ホメオスタシス","ミニューチン/構造派"],"p":"直線的因果律（誰が悪いか）との対比が書ければ合格点。不登校や摂食障害の事例問題で「家族全体を見る視点」として使える。"},{"id":"sfbt","t":"解決志向ブリーフセラピー","en":"solution-focused brief therapy","f":"rinsho","s":"ド・シェイザーとバーグらが開発した短期療法。問題の原因よりも、うまくいっている「例外」やクライエントの資源に注目し、ミラクル・クエスチョンなどで望む解決を共に構築する。","a":"ド・シェイザー（de Shazer, S.）とインスー・キム・バーグ（Berg, I. K.）らが開発した短期療法。問題の原因を探ることよりも、クライエントがすでにもっている資源や、問題が起きていない、あるいは少しうまくいっている「例外」に注目し、望む未来（解決）を共に描くことを重視する。奇跡が起きて問題が解決した翌朝を想像してもらうミラクル・クエスチョン、状態を数値で表してもらうスケーリング・クエスチョン、コーピング・クエスチョン、コンプリメントなどの技法を用いる。","k":["ド・シェイザー/de Shazer","例外","資源/リソース","ミラクル・クエスチョン","スケーリング"],"p":"「クライエントこそが自分の専門家である」という人間観が要。原因追究型（精神分析など）との対比で問われやすい。"},{"id":"narrative","t":"ナラティヴ・セラピー","en":"narrative therapy","f":"rinsho","s":"ホワイトとエプストンが提唱した、社会構成主義にもとづく心理療法。問題の外在化などを通して、問題に支配された物語を、本人が望む別の物語へと書き換えていく。","a":"ホワイト（White, M.）とエプストン（Epston, D.）が提唱した、社会構成主義にもとづく心理療法。人は自分の人生を物語として意味づけて生きており、問題に満ちた支配的な物語（ドミナント・ストーリー）に縛られて苦しんでいると考える。問題を人から切り離して語る「問題の外在化」や、その物語に合わない出来事（ユニークな結果）に光を当てることを通じて、本人が望む別の物語（オルタナティヴ・ストーリー）を共に紡ぎ直していく。専門家の知よりも本人の知を尊重する。","k":["ホワイト/White","社会構成主義","ドミナント・ストーリー/支配的な物語","外在化","オルタナティヴ/別の物語"],"p":"「問題が問題であって、人が問題なのではない」という考え方を一文で示すとよい。社会や文化の言説が個人の物語を規定するという政治的な視点も特徴。"},{"id":"play-therapy","t":"遊戯療法","en":"play therapy","f":"rinsho","s":"主に子どもを対象に、遊びを表現と交流の手段として行う心理療法。アクスラインは受容、許容的な雰囲気、感情の反射、必要な制限など8つの基本原理を示した。","a":"言語による表現が十分でない子どもを主な対象に、遊びを主な表現・交流の手段として行う心理療法。精神分析の流れではアンナ・フロイトやクラインが子どもの分析に遊びを取り入れた。アクスライン（Axline, V. M.）は来談者中心療法の考えにもとづき、温かい関係、ありのままの受容、許容的な雰囲気、感情の察知と反射、子どもの主導の尊重、必要な制限などからなる8つの基本原理を示した。遊びは感情の表出、体験の象徴的な再演と統合、関係の修復などの働きをもつ。","k":["子ども","遊び","アクスライン/Axline","8つの基本原理/8原則","制限","象徴"],"p":"「制限」がなぜ必要か（子どもと治療者の安全、現実との接点、治療関係の保護）を説明できると論述でも強い。"},{"id":"sandplay","t":"箱庭療法","en":"sandplay therapy","f":"rinsho","s":"砂箱の中にミニチュアを置いて作品をつくる心理療法。ローエンフェルトの世界技法をもとにカルフがユング心理学の立場から発展させ、河合隼雄が1965年に日本に紹介した。","a":"内側を青く塗った一定の大きさの砂箱の中に、ミニチュアの玩具を自由に置いて作品をつくる心理療法。ローエンフェルト（Lowenfeld, M.）の世界技法をもとに、カルフ（Kalff, D. M.）がユング心理学の観点から発展させ、1965年に河合隼雄が日本に紹介した。治療者に見守られた「自由にして保護された空間」の中で、言葉にならない内的な世界が象徴的に表現される。作品を一つずつ解釈することよりも、表現が生まれる関係と、作品の継時的な変化を重視する。","k":["砂箱/砂","ローエンフェルト/Lowenfeld","カルフ/Kalff","河合隼雄","自由にして保護された空間"],"p":"日本で広く受け入れられた理由（非言語的表現、日本の箱庭や盆景の文化との親和性）を論じさせる出題もありうる。"},{"id":"art-therapy","t":"芸術療法（表現療法）","en":"art therapy","f":"rinsho","s":"絵画、コラージュ、音楽などの創作・表現活動を媒介とする心理療法の総称。言葉にしにくい感情やイメージを非言語的に表現でき、表現そのものと作品を介した交流が治療的に働く。","a":"絵画、コラージュ、粘土、音楽、詩歌、ダンスなどの創作・表現活動を用いる心理療法の総称。言葉では表しにくい感情やイメージを非言語的に表現でき、表現すること自体のカタルシスや自己理解、さらに作品を介した治療者との交流が治療的に働くとされる。作品を無意識の表現として扱い言語化を重視する立場（ナウムバーグ）と、創作の過程そのものに治癒の力をみる立場（クレイマー）がある。日本では中井久夫の風景構成法など独自の展開もみられる。","k":["非言語","表現","ナウムバーグ/Naumburg","クレイマー/Kramer","作品"],"p":"「作品を診断に使う」ことと「表現の場を守る」ことの違いを意識して書く。侵襲性（表現が深い層を揺さぶること）への配慮にもふれられるとよい。"},{"id":"focusing","t":"フォーカシング","en":"focusing","f":"rinsho","s":"ジェンドリンが提唱した、身体で感じられるまだ言葉にならない意味の感覚（フェルトセンス）に注意を向け、それに合う言葉を探すことで体験過程を進める方法。","a":"ジェンドリン（Gendlin, E. T.）が提唱した、からだで感じられる、まだ言葉にならない意味の感覚（フェルトセンス）に注意を向け、それにぴったりくる言葉やイメージを探していく方法。ロジャーズのもとでの研究で、心理療法がうまくいくクライエントは、面接の中で自分の体験に触れながら話す傾向があることが見いだされたことに始まる。体験過程理論にもとづき、フェルトセンスと言葉が響き合うときに起こる「フェルトシフト」が変化をもたらすとされる。","k":["ジェンドリン/Gendlin","フェルトセンス","体験過程","ロジャーズ","フェルトシフト"],"p":"来談者中心療法の「態度」を、クライエント側の「体験の仕方」の研究へと展開したもの、と位置づけると流れが説明できる。"},{"id":"mi","t":"動機づけ面接","en":"motivational interviewing","f":"rinsho","s":"ミラーとロルニックが開発した協働的な面接法。変化への両価性を探り、開かれた質問・是認・聞き返し・要約を用いて、クライエント自身のチェンジトークを引き出し動機を高める。","a":"ミラー（Miller, W. R.）とロルニック（Rollnick, S.）が開発した、変化に対する両価性（変わりたいが、変わりたくない）を解きほぐし、本人の内発的な動機を引き出す協働的な面接法。もとは飲酒問題の領域で発展した。開かれた質問、是認、聞き返し、要約（OARS）を基本のスキルとし、クライエントが自ら語る変化への言葉（チェンジトーク）を引き出して強める。説得や直面化は抵抗を強めるため避け、協働、受容、思いやり、喚起の精神を重視する。","k":["ミラー/Miller","両価性","チェンジトーク","聞き返し","協働"],"p":"来談者中心療法の態度を、目標に向けて方向づける（指向的）点が特徴。「来談者中心だが方向性をもつ」と説明すると違いが伝わる。"},{"id":"working-alliance","t":"作業同盟（治療同盟）","en":"working alliance","f":"rinsho","s":"治療者とクライエントが協力して治療に取り組む関係。ボーディンは目標についての合意、課題についての合意、情緒的な絆の3要素で定義した。学派を超えて治療効果と関連する。","a":"治療者とクライエントが協力して治療に取り組む関係をいう。精神分析ではグリーンソン（Greenson, R.）が、転移とは区別される現実的な協力関係として論じた。ボーディン（Bordin, E. S.）は学派を超える概念として、目標についての合意、課題についての合意、情緒的な絆の3つの要素で定義した。同盟の質は、学派を問わず治療効果を予測することが多くの研究で示されている。同盟の亀裂と修復を扱うこと自体が治療的に重要であるとされる。","k":["協力","ボーディン/Bordin","目標","課題","絆","治療効果"],"p":"共通要因論とセットで出しやすい。「亀裂と修復」（サフラン）まで書けると現代的。"},{"id":"common-factors","t":"共通要因","en":"common factors","f":"rinsho","s":"学派や技法の違いを超えて、多くの心理療法に共通して効果をもたらす要因。治療関係、クライエントの要因、期待などが挙げられ、ローゼンツヴァイクの「ドードー鳥の評決」が知られる。","a":"学派や技法の違いを超えて、多くの心理療法に共通して治療効果をもたらす要因をいう。ローゼンツヴァイク（Rosenzweig, S.）は、異なる心理療法の効果に大差がないことを、『不思議の国のアリス』になぞらえて「ドードー鳥の評決」と表現した。ランバート（Lambert, M. J.）は効果に寄与する要因として、治療外の要因、治療関係、期待（プラセボ）、技法を挙げた。共感や作業同盟などの関係要因の重要性を示す一方、特定の問題に対する技法の効果を否定するものではない。","k":["学派","ローゼンツヴァイク/Rosenzweig","ドードー鳥","ランバート/Lambert","治療関係/作業同盟"],"p":"ランバートの割合（40/30/15/15）は実証値ではなく推定であることに注意。「技法は無意味」という極論に流れないこと。"},{"id":"group-therapy","t":"集団心理療法","en":"group psychotherapy","f":"rinsho","s":"複数のクライエントと治療者が集団で行う心理療法。集団の力動やメンバー間の相互作用を活かし、ヤーロムは普遍性、愛他主義、凝集性などの治療的因子を挙げた。","a":"複数のクライエントと治療者が集団で行う心理療法で、集団そのものの力動やメンバー間の相互作用を治療に活かす点に特徴がある。ヤーロム（Yalom, I. D.）は治療的因子として、希望をもたらすこと、普遍性（悩んでいるのは自分だけではないという体験）、情報の伝達、愛他主義、初期家族関係の修正的な繰り返し、対人学習、凝集性、カタルシス、実存的因子などを挙げた。精神分析的集団療法、心理劇、SST、自助グループなど多様な形態がある。","k":["相互作用","ヤーロム/Yalom","治療的因子","普遍性","凝集性"],"p":"個人療法にはない集団ならではの因子（普遍性・愛他主義・対人学習）を中心に書くと焦点が定まる。"},{"id":"morita","t":"森田療法","en":"Morita therapy","f":"rinsho","s":"森田正馬が創始した日本独自の精神療法。神経質の人がヒポコンドリー性基調と精神交互作用によって症状にとらわれると考え、症状を「あるがまま」に受け入れて目的本位に行動することをめざす。","a":"精神科医の森田正馬が1919年ごろに創始した日本独自の精神療法で、主に神経症（森田は神経質と呼んだ）を対象とする。病気を恐れ、よりよく生きたいという欲望の強いヒポコンドリー性基調をもつ人が、症状に注意を向けるほど感覚が鋭くなり、注意がさらに固着する精神交互作用によって症状にとらわれると考える。症状を取り除こうとせず「あるがまま」に受け入れて目的本位に行動することをめざし、入院療法は絶対臥褥期から作業期を経て社会生活に向かう。","k":["森田正馬","神経質","ヒポコンドリー性基調","精神交互作用","あるがまま","絶対臥褥"],"p":"「症状を消そうとする努力が症状を強める」という逆説は、ACTの「体験の回避」と比較して論じることができる。"},{"id":"naikan","t":"内観療法","en":"Naikan therapy","f":"rinsho","s":"吉本伊信が確立した日本独自の心理療法。身近な人に対する自分について「していただいたこと」「して返したこと」「迷惑をかけたこと」の3点を具体的に想起し、自己と他者の見方を問い直す。","a":"吉本伊信が、浄土真宗の一派に伝わる修行法「身調べ」を一般向けに改めて確立した日本独自の心理療法。集中内観では、約1週間、屏風で仕切った空間にこもり、母親をはじめとする身近な人に対する自分を、年代を区切って「していただいたこと」「して返したこと」「迷惑をかけたこと」の3つのテーマで具体的に想起する。面接者は定期的に訪れて報告を聴く。自己中心的な見方が揺らぎ、他者から支えられてきた事実への気づきが生じるとされ、依存症などにも応用されている。","k":["吉本伊信","身調べ","していただいたこと","して返したこと","迷惑をかけたこと"],"p":"「迷惑をかけられたこと」は問わない構造の意味（被害者的な見方からの転換）を説明できるとよい。虐待体験のある人への適用には慎重さが必要という論点もある。"},{"id":"logotherapy","t":"ロゴセラピー","en":"logotherapy","f":"rinsho","s":"フランクルが創始した実存分析的な心理療法。人間の根源的な動機を「意味への意志」に求め、どのような状況でも態度を選ぶ自由があるとする。逆説志向などの技法がある。","a":"精神科医フランクル（Frankl, V. E.）が創始した実存分析的な心理療法。強制収容所での体験を記した『夜と霧』でも知られる。人間の根源的な動機を、快楽への意志や権力への意志ではなく「意味への意志」に求めた。人はどのような状況にあっても、その状況に対する態度を選ぶ自由をもち、人生から問われている意味に応えていく存在だと考える。予期不安の悪循環を断つ逆説志向や、過剰な自己観察を外へ向けかえる反省除去などの技法がある。","k":["フランクル/Frankl","夜と霧","意味への意志","態度","逆説志向"],"p":"「快楽への意志＝フロイト、権力への意志＝アドラー」との対比で書くと位置づけが明確になる。"},{"id":"rinsho-no-chi","t":"臨床の知","en":"clinical knowledge","f":"rinsho","s":"中村雄二郎が近代科学の知（普遍性・論理性・客観性）に対置した知のあり方。コスモロジー、シンボリズム、パフォーマンスを原理とし、個別の具体的な関わりの中で働く知をさす。","a":"哲学者の中村雄二郎が、近代科学の知と対比して提唱した知のあり方。近代科学は普遍性・論理性・客観性を原理とし、対象から距離をとって一般的な法則を求めるが、その結果、個々の具体的な事例や、関わる者自身の経験がこぼれ落ちる。これに対し臨床の知は、固有の場所や関係を重んじるコスモロジー、事物の多義性をとらえるシンボリズム、身体をそなえた相互的な行為としてのパフォーマンスを原理とする。一回性の出会いを扱う心理臨床の知を考えるうえで重要である。","k":["中村雄二郎","近代科学","普遍性","コスモロジー","シンボリズム","パフォーマンス"],"p":"「科学としての心理学と心理臨床」「事例研究の意義」などの思想系の論述で使える。エビデンスを否定する概念ではなく、補い合うものとして書く。"},{"id":"dohsa","t":"臨床動作法","en":"dohsa-hou","f":"rinsho","s":"成瀬悟策が開発した日本独自の心理療法。動作を意図・努力・身体運動からなる心理的過程ととらえ、課題動作を通した体験から自己のあり方の変化をめざす。","a":"成瀬悟策が、脳性まひのある人の動作の改善の試み（催眠研究に端を発する）から発展させた日本独自の心理療法。動作を、本人が意図し、そのための努力をして身体の運動が実現する心理的な過程ととらえる。援助者が課題となる動作（肩の上げ下げ、躯幹のひねりなど）を示し、本人が自分のからだに注意を向けて緊張を緩めたり動かしたりする体験を通して、自己のあり方や生活体験の変化をめざす。障害のある人だけでなく、ストレスやトラウマの支援、高齢者などにも用いられる。","k":["成瀬悟策","脳性まひ","意図","努力","動作"],"p":"「からだを通して心に働きかける」日本発の方法として、森田療法・内観療法と並べて整理しておく。"},{"id":"psychoeducation","t":"心理教育","en":"psychoeducation","f":"rinsho","s":"病気や問題についての正しい知識や対処法を、本人や家族が受け入れやすい形で伝え、主体的に対処できるよう支援する方法。統合失調症の家族心理教育から広がった。","a":"病気や障害、問題について正確な知識や情報を、本人や家族が受け入れやすい形で伝え、対処の方法を身につけて主体的に生活できるよう支援する方法。統合失調症の家族を対象とした研究から、家族の感情表出（EE）が高いと再発しやすいことが示され、家族心理教育が再発予防に有効とされたことが発展の契機となった。情報提供にとどまらず、困りごとへの対処技能の練習や、参加者どうしの支え合いを含む。うつ病、トラウマ、発達障害など幅広い領域で行われている。","k":["知識/情報","家族","感情表出/EE","再発","対処"],"p":"一方的な講義にならないこと（相手の受け止めを確かめながら伝える）が実践上の要点。トラウマ支援では「あなたの反応は異常な事態への正常な反応」と伝えることが重要。"},{"id":"unconscious","t":"無意識（局所論）","en":"the unconscious","f":"seishin","s":"意識化されない心の領域。フロイトは局所論で、心を意識・前意識・無意識に分け、無意識は抑圧された欲動や願望からなり、夢や症状などに偽装されて表れるとした。","a":"フロイトは『夢解釈』（1900年）などで、心を意識・前意識・無意識の3つの領域に分ける局所論を示した。前意識は注意を向ければ意識化できる内容であり、無意識は抑圧によって意識から締め出され、通常は意識化できない欲動や願望、記憶からなる。無意識の内容は、夢、言い間違いなどの失錯行為、神経症の症状として、偽装された形で表れる。のちにフロイトは、自我にも無意識的な部分があることから、エス・自我・超自我からなる構造論を提唱した。","k":["フロイト/Freud","意識","前意識","抑圧","夢","構造論"],"p":"ユングの無意識（集合的無意識、創造的・目的論的）との比較は頻出。局所論→構造論へと理論が移った理由まで書ける準備を。"},{"id":"structural","t":"構造論（エス・自我・超自我）","en":"structural model","f":"seishin","s":"フロイト（1923）の心の構造モデル。快感原則に従うエス、良心と理想を担う超自我、現実原則に従って両者と外界を調整する自我の三者から心の働きを説明する。","a":"フロイトが1923年の『自我とエス』で示した心の構造のモデル。エス（イド）は快感原則に従う本能的欲動の貯蔵庫であり、超自我は親の禁止や理想が内在化した、良心と自我理想の働きである。自我は現実原則に従い、エスの欲動、超自我の要請、外界の現実の三者を調整する。自我がこの調整に失敗して不安が生じると、防衛機制が働く。局所論では説明しにくかった、自我や超自我にも無意識的な部分があるという理解を可能にした。","k":["1923","エス/イド","超自我","自我","現実原則","防衛"],"p":"「自我は3人の主人に仕える」という比喩で三者の関係を説明すると答案が締まる。"},{"id":"defense","t":"防衛機制","en":"defense mechanisms","f":"seishin","s":"自我が、受け入れがたい欲動や感情に伴う不安から自らを守るために、多くは無意識的に用いる心理的な働き。抑圧、投影、反動形成、昇華などがあり、アンナ・フロイトが体系化した。","a":"自我が、受け入れがたい欲動や感情、それに伴う不安や罪悪感から自らを守るために、多くは無意識的に用いる心理的な働き。フロイトが論じ、娘のアンナ・フロイトが『自我と防衛機制』（1936年）で体系化した。抑圧、反動形成、投影、置き換え、合理化、知性化、隔離、打ち消し、退行、昇華などがある。防衛そのものは誰にでもある適応的な働きであり、それが柔軟さを欠いて固定化したり、未熟な防衛に偏ったりすると、症状や不適応につながる。","k":["自我","不安","アンナ・フロイト","抑圧","昇華","適応"],"p":"具体例を2〜3個添えると説得力が出る（例：反動形成＝憎い相手に過度に丁寧にふるまう）。防衛を「取り除くべきもの」と書かないこと。"},{"id":"repression","t":"抑圧","en":"repression","f":"seishin","s":"受け入れがたい欲動や記憶を意識から締め出し、無意識にとどめる防衛機制。フロイトは防衛の基本とみなし、抑圧されたものは夢や症状として回帰すると考えた。意識的な抑制とは区別される。","a":"受け入れがたい欲動や記憶、観念を意識から締め出し、無意識にとどめておく防衛機制で、フロイトはこれを防衛の基本とみなした。抑圧されたものは消えるわけではなく、意識に戻ろうとする力をもち続け、夢や失錯行為、神経症の症状として偽装された形で回帰する（抑圧されたものの回帰）。意識的に考えないようにする抑制とは区別される。精神分析では、自由連想や解釈を通じて抑圧されたものを意識化し、それをめぐる葛藤を扱うことが治療の中心となった。","k":["防衛機制","無意識","回帰","抑制","意識化"],"p":"「抑圧」と「抑制」、「抑圧」と「否認」（外界の知覚を認めない）の区別が問われやすい。"},{"id":"transference","t":"転移","en":"transference","f":"seishin","s":"クライエントが、過去の重要な人物との関係で抱いた感情や態度を、無意識のうちに治療者に向けて再現する現象。陽性転移と陰性転移があり、精神分析では理解と解釈の中心となる。","a":"クライエントが、過去の重要な人物（多くは親）との関係で抱いた感情や態度、関係のパターンを、無意識のうちに治療者に向けて再現する現象。好意や信頼などの陽性転移と、敵意や不信などの陰性転移がある。フロイトは当初これを治療の障害とみたが、のちに、過去の葛藤が「今ここ」で生きた形で現れるものとして、治療の中心的な手がかりと位置づけた。転移を理解し解釈することで、クライエントは自らの関係のあり方を体験的に理解していく。","k":["過去","重要な人物/親","治療者","陽性転移","陰性転移","解釈"],"p":"「障害→手がかり」という位置づけの変化と、転移は日常の人間関係にも生じる普遍的な現象である点を押さえる。逆転移とセットで論述に出やすい。"},{"id":"countertransference","t":"逆転移","en":"countertransference","f":"seishin","s":"治療者がクライエントに対して抱く感情や反応。当初は治療の障害とされたが、ハイマンらにより、クライエントを理解するための手がかりとしても位置づけられた。","a":"治療者がクライエントに対して抱く感情や反応をいう。フロイトは、治療者自身の未解決の葛藤による治療の障害とみなし、教育分析による克服を求めた。その後、ハイマン（Heimann, P.）らによって、逆転移はクライエントの無意識を理解するための重要な手がかりであるとする見方が広まった。ラッカーは、クライエントの自己に同一化する融和型と、クライエントの内的対象に同一化する補足型を区別した。逆転移を行動化せず、吟味して理解に用いることが求められる。","k":["治療者","障害","ハイマン/Heimann","手がかり","行動化"],"p":"「感じてはいけない感情」ではなく「感じたうえで吟味する材料」と書く。スーパービジョンや教育分析の意義と結びつけると深まる。"},{"id":"resistance","t":"抵抗","en":"resistance","f":"seishin","s":"治療の過程で、無意識の内容の意識化や変化に逆らって働くクライエントの心の動き。沈黙、遅刻、話題の回避などとして現れ、精神分析では理解し解釈すべきものとされる。","a":"治療の過程で、無意識的な内容の意識化や変化に逆らって働く、クライエントの心の動きをいう。沈黙、遅刻やキャンセル、話題をそらすこと、治療者への過度の同調などとして現れる。フロイトは当初これを克服すべき障害とみたが、抵抗には、つらい感情から自分を守ってきたその人なりのあり方が表れている。そのため、無理に取り除くのではなく、何から身を守ろうとしているのかを理解し、解釈して扱うことが治療の重要な部分となった。","k":["意識化","変化","沈黙/遅刻","守","解釈"],"p":"抵抗を「クライエントのやる気のなさ」と書くのは誤り。治療関係の中で意味をもつ現象として扱う姿勢を示す。"},{"id":"free-assoc","t":"自由連想法","en":"free association","f":"seishin","s":"頭に浮かんだことを取捨選択せずにすべて話すよう求める精神分析の基本的方法（基本規則）。治療者は平等に漂う注意をもって聴き、連想の流れや途切れから無意識を理解する。","a":"精神分析の基本的な方法で、クライエントに、頭に浮かんだことを、不快であったり、くだらない・関係ないと思えたりしても、取捨選択せずにすべて話すよう求める（基本規則）。フロイトは、催眠や前額法を経てこの方法にいたった。連想の流れや途切れ、言いよどみなどに現れる抵抗や転移を手がかりに、無意識の内容を理解していく。古典的には寝椅子を用い、治療者は視野の外に座り、平等に漂う注意をもって聴く。","k":["頭に浮かんだ","基本規則","催眠","抵抗","平等に漂う注意","寝椅子"],"p":"治療者側の「平等に漂う注意」と対になっていることを書くと一段上の答案になる。"},{"id":"dream-work","t":"夢の作業","en":"dream-work","f":"seishin","s":"夢の潜在思考が検閲を逃れて顕在夢へと変形される過程。フロイトは、圧縮、置き換え、視覚化（表象可能性への顧慮）、二次加工からなるとし、夢を願望充足とみなした。","a":"フロイトが『夢解釈』（1900年）で示した、夢の背後にある無意識的な願望（潜在内容）が、検閲をかいくぐって、実際に見た夢（顕在内容）へと変形される過程。複数の要素を一つにまとめる圧縮、重要な感情や意味を些細な要素に移す置き換え、思考を視覚的な像に変える表象可能性への顧慮（視覚化）、夢をまとまりのある筋書きに整える二次加工などからなる。フロイトは夢を「無意識への王道」と呼び、夢は願望充足であると考えた。","k":["潜在","顕在","圧縮","置き換え","二次加工","願望充足"],"p":"ユングの夢の見方（補償・目的論、拡充法）との比較で問われることが多い。"},{"id":"oedipus","t":"エディプス・コンプレックス","en":"Oedipus complex","f":"seishin","s":"男根期の子どもが異性の親に愛情を、同性の親に敵意を抱き、罰への恐れ（去勢不安）とのあいだで葛藤する三者関係の心理。同性の親との同一化により解消され、超自我が形成される。","a":"フロイトが心的発達の中心に位置づけた葛藤。男根期（およそ3〜5歳）に、子どもが異性の親に愛情を向け、同性の親を競争相手として敵意を抱く一方、同性の親から罰せられることを恐れる（男児では去勢不安）という三者関係の葛藤をいう。ギリシア悲劇『オイディプス王』にちなむ。子どもは同性の親に同一化することでこの葛藤を解消し、その過程で超自我が形成される。フロイトは、これを神経症の中核的な葛藤とした。","k":["男根期","異性の親","同性の親","去勢不安","三者関係","超自我"],"p":"日本の「阿闍世コンプレックス」（母子の二者関係、許しによる罪悪感）との対比は上智に限らず頻出。"},{"id":"repetition","t":"反復強迫","en":"repetition compulsion","f":"seishin","s":"過去の苦痛な体験や関係のパターンを、意図に反して繰り返してしまう傾向。フロイトは『快原理の彼岸』（1920）で、その背後に死の欲動を想定した。転移の中にも現れる。","a":"過去の苦痛な体験や関係のパターンを、本人の意図に反して繰り返してしまう傾向をいう。フロイトは、患者が過去を想起する代わりに行為として反復することに注目した。さらに『快原理の彼岸』（1920年）で、外傷的な夢の反復や、幼児の糸巻き遊び（いないいない／ばあ）を手がかりに、快原理では説明できない反復の背後に死の欲動を想定した。治療では、転移の中に現れる反復を理解し、想起と徹底操作へとつなげることが求められる。","k":["反復","快原理の彼岸/快感原則の彼岸","1920","死の欲動","転移","徹底操作"],"p":"トラウマの再演（再被害化）や、同じような相手を選び続ける恋愛関係など、臨床例と結びつけて説明できるように。"},{"id":"object-relations","t":"対象関係論","en":"object relations theory","f":"seishin","s":"心の発達と病理を、自己と他者（対象）との関係、とくに内在化された内的対象との関係から理解する精神分析の理論群。クライン、フェアベーン、ウィニコットらが発展させた。","a":"人の心の発達と病理を、欲動そのものよりも、自己と他者（対象）との関係、とりわけ内面に取り入れられた内的対象との関係から理解しようとする精神分析の理論の総称。クラインを起点に、フェアベーン、ウィニコット、バリントらのイギリス独立学派、ビオンなどによって発展した。乳児期の母子関係で形成される内的対象関係が、その後の対人関係や転移の中で繰り返されると考え、治療では治療者との関係に表れる内的対象関係を理解し扱う。","k":["対象","内的対象","クライン/Klein","ウィニコット/Winnicott","母子関係","転移"],"p":"フロイトの欲動論（快を求める）とフェアベーンの「リビドーは対象を求める」の対比を一文入れると理論の転換点が示せる。"},{"id":"klein-pos","t":"妄想分裂ポジションと抑うつポジション","en":"paranoid-schizoid / depressive position","f":"seishin","s":"クラインが示した乳児期の心の2つの様式。部分対象への分裂と迫害不安を特徴とする妄想分裂ポジションと、全体対象への気づきと抑うつ不安・償いを特徴とする抑うつポジション。","a":"クライン（Klein, M.）が示した、乳児期の心のあり方の2つの様式。生後3〜4か月ごろまでの妄想分裂ポジションでは、乳児は対象を「良い乳房」と「悪い乳房」という部分対象に分裂させ、悪い部分を外に投影して迫害される不安（迫害不安）を抱く。続く抑うつポジションでは、良い面と悪い面が同じ一人の母親（全体対象）に属すると気づき、自分の攻撃性が愛する対象を傷つけたという抑うつ不安と罪悪感が生じ、償いの気持ちが芽生える。","k":["クライン/Klein","分裂","部分対象","迫害不安","全体対象","償い"],"p":"「段階」ではなく「ポジション（生涯を通じて行き来する心の構え）」と呼んだ理由を説明できると評価が高い。"},{"id":"proj-id","t":"投影同一化（投影性同一視）","en":"projective identification","f":"seishin","s":"自己の受け入れがたい部分を分裂させて他者に投げ入れ、その他者をその部分と同一視し支配しようとする原始的な防衛機制。クラインが記述し、ビオンは伝達の機能も見いだした。","a":"クラインが1946年に記述した原始的な防衛機制で、自己の受け入れがたい部分を分裂させて対象の中に投げ入れ、対象をその部分と同一のものとして体験し、支配しようとする空想をいう。ビオンはこれを、乳児が耐えられない感情を母親に伝える正常なコミュニケーションの手段としても位置づけた。臨床では、クライエントが投げ入れた感情を治療者が実際に感じさせられることがあり、逆転移を通してクライエントを理解する手がかりとなる。","k":["クライン/Klein","分裂","投げ入れ","ビオン/Bion","コミュニケーション","逆転移"],"p":"単なる「投影」との違い（相手が実際にその感情を感じるよう影響を与える、相互作用的な現象）を書くことが要点。"},{"id":"transitional","t":"移行対象","en":"transitional object","f":"seishin","s":"ウィニコットの概念で、乳幼児が母親から分離していく過程で慰めとする毛布やぬいぐるみなど。内的世界と外的現実の中間領域に属し、のちの遊びや文化的体験の源とされる。","a":"ウィニコット（Winnicott, D. W.）が示した概念で、乳幼児が肌身離さず持ち歩く毛布やぬいぐるみなど、母親から心理的に分離していく過程で、母親の代わりとして慰めを与える対象をいう。それは乳児にとって、自分が作り出したものでも外から与えられたものでもあるような、内的世界と外的現実の中間にある「移行領域（可能性空間）」に属している。ウィニコットは、この中間領域が、のちの遊びや芸術、文化的な体験の源になると考えた。","k":["ウィニコット/Winnicott","毛布/ぬいぐるみ","分離","中間/移行領域","遊び"],"p":"「どちらのものか問わない」という逆説を保つことが大切だ、というウィニコットの指摘は遊戯療法や芸術療法の論述にも使える。"},{"id":"good-enough","t":"ほどよい母親と抱える環境","en":"good-enough mother / holding","f":"seishin","s":"ウィニコットの概念。完璧ではなく、乳児の欲求にほぼ適切に応え、少しずつ失敗することで現実への適応を助けるのが「ほどよい母親」であり、乳児を支え守る環境が「抱える環境」である。","a":"ウィニコットの概念。ほどよい母親とは、完璧な母親ではなく、乳児の欲求にほぼ適切に応えつつ、成長に応じて少しずつ失敗することで、乳児が現実に適応していくのを助ける母親をいう。抱える環境（ホールディング）とは、乳児が身体的にも心理的にも安心して存在し続けられるよう、母親が支え守る環境のことである。心理療法も、治療者が一貫した枠組みと態度でクライエントを抱える環境を提供することで、本当の自己が育つ場となると考えられる。","k":["ウィニコット/Winnicott","完璧","失敗","ホールディング/抱える","本当の自己"],"p":"「失敗」の積極的な意味（脱錯覚）を書けるかがポイント。治療者の「完璧でなさ」が治療的に働く局面の議論にもつながる。"},{"id":"container","t":"コンテイナー／コンテインド","en":"container / contained","f":"seishin","s":"ビオンの概念。乳児が投げ入れる耐えがたい感情（コンテインド）を母親が受け止め（コンテイナー）、もの想いによって意味あるものに変形して返す過程をいう。治療者の機能の説明にも用いられる。","a":"ビオン（Bion, W. R.）の概念。乳児は耐えがたい感情や感覚（ベータ要素）を投影同一化によって母親に投げ入れ、母親はそれを受け止め、もの想い（レヴァリー）を通して意味のあるもの（アルファ要素）に変形して返す。この変形の働きをアルファ機能と呼び、受け止める側をコンテイナー、受け止められるものをコンテインドと呼ぶ。この経験の積み重ねにより、乳児は自ら考え、感情を抱えておく力を内在化する。治療者の機能を説明する枠組みとしても用いられる。","k":["ビオン/Bion","ベータ要素","投影同一化","もの想い/レヴァリー","アルファ機能","考え"],"p":"ウィニコットの「抱える環境」との異同（身体的・環境的な支え／感情を消化し意味に変える心の働き）を比較できるようにしておく。"},{"id":"kohut","t":"自己心理学","en":"self psychology","f":"seishin","s":"コフートが創始した精神分析の理論。健全な自己愛の発達には、鏡映・理想化・双子の自己対象の応答が必要であるとし、治療では自己対象転移と共感を重視する。","a":"コフート（Kohut, H.）が、自己愛の病理の治療経験から創始した精神分析の理論。健康な自己愛の発達には、子どもの自己を映し返して認める存在、理想化できる存在、自分と似ていると感じられる存在といった自己対象の応答が必要だと考え、それが得られないと、自己がまとまりを欠いて傷つきやすくなるとした。治療では、鏡転移・理想化転移・双子（分身）転移として現れる自己対象転移を受け止め、共感を観察と理解の方法として重視する。","k":["コフート/Kohut","自己愛","自己対象","鏡転移","理想化","共感"],"p":"ロジャーズの共感との比較（コフートは共感を「代理の内省」という観察の方法とした）は思想系の論述でも使える。"},{"id":"ego-psych","t":"自我心理学","en":"ego psychology","f":"seishin","s":"フロイトの構造論をもとに、自我の機能と適応に焦点を当てた精神分析の流れ。アンナ・フロイトの防衛機制論やハルトマンの「葛藤外の自我領域」などに代表される。","a":"フロイトの構造論をもとに、自我の働きに焦点を当てて発展した精神分析の流れ。アンナ・フロイトの防衛機制の研究に続き、ハルトマン（Hartmann, H.）は、知覚、記憶、運動などのように葛藤とは独立に発達する「葛藤外の自我領域」と、環境への適応の働きを論じた。エリクソンの心理社会的発達理論も、この流れの中から生まれた。主にアメリカで主流となり、自我の強さや防衛の評価、支持的な心理療法の理論的な基盤となった。","k":["自我","アンナ・フロイト","ハルトマン/Hartmann","葛藤外","適応","エリクソン"],"p":"対象関係論（イギリス）との地域・関心の違いを押さえると、精神分析の「学派の地図」が描ける。"},{"id":"lacan","t":"鏡像段階","en":"mirror stage","f":"seishin","s":"ラカンの概念で、生後6〜18か月ごろの乳児が鏡に映った自分の像を自分と認め、統一された自己像（自我）を獲得する段階。自我は他者の像を通して想像的に形成されるとされる。","a":"ラカン（Lacan, J.）が提唱した概念で、生後6〜18か月ごろの乳児が、鏡に映った自分の像を見て、歓喜とともにそれを自分だと認める段階をいう。運動機能が未熟で、ばらばらな身体を生きている乳児は、鏡の中のまとまった像に自分を同一化することで、はじめて統一された自己のイメージ（自我）を得る。しかし、その自我は外にある像、すなわち他者を通して作られた想像的なものであるため、自我は根本的に疎外を含み、他者との鏡像的な競合関係を生むとされる。","k":["ラカン/Lacan","生後6","鏡","統一","想像的","疎外"],"p":"「自我は自分の中心ではなく、他者の像からできている」という逆説がポイント。自我心理学への批判という文脈も添えられるとよい。"},{"id":"mentalization","t":"メンタライゼーション","en":"mentalization","f":"seishin","s":"自他の行動を、その背後にある欲求・感情・信念などの心の状態と結びつけて理解する心の働き。フォナギーらが提唱し、安定した愛着関係の中で育つとされ、境界性パーソナリティ障害の治療（MBT）に応用された。","a":"フォナギー（Fonagy, P.）らが提唱した概念で、自分や他者の行動を、その背後にある欲求、感情、信念、意図などの心の状態と結びつけて理解する心の働きをいう。安定した愛着関係の中で、養育者が子どもの心の状態を読み取って映し返すことを通じて発達すると考えられる。愛着理論と精神分析を統合する視点から、境界性パーソナリティ障害の人では強い感情の中でこの働きが損なわれやすいとされ、それを高めるメンタライゼーションに基づく治療（MBT）が開発された。","k":["フォナギー/Fonagy","心の状態","愛着","境界性パーソナリティ","MBT"],"p":"「心の理論」（発達心理学）との異同を問われることがある。メンタライゼーションは感情的な関係の中での働きを重視する。"},{"id":"interpretation","t":"解釈と徹底操作","en":"interpretation / working through","f":"seishin","s":"クライエントの語りや転移に表れた無意識の意味を、治療者が言葉で伝える介入が解釈であり、同じ葛藤が繰り返し現れるたびにそれを扱い、洞察を深めていく過程が徹底操作である。","a":"解釈とは、クライエントの語りや行動、転移などに表れている無意識の意味を、治療者が理解して言葉で伝えることであり、精神分析的心理療法の中心的な介入である。表層から深層へ、防衛から欲動へ、タイミングを見て伝えることが原則とされる。一度の解釈で洞察が得られても、変化はすぐには定着しない。同じ葛藤が形を変えて繰り返し現れるたびにそれを扱い、抵抗を乗り越えて洞察を深めていく過程が必要であり、これを徹底操作という。","k":["無意識","転移","タイミング","洞察","繰り返","抵抗"],"p":"来談者中心療法の「反射（伝え返し）」との違い（意識されていない意味を言葉にする）を対比して書けるように。"},{"id":"treatment-structure","t":"治療構造","en":"therapeutic structure","f":"seishin","s":"小此木啓吾が体系化した、治療者とクライエントの交流を規定する条件の総体。時間・場所・料金などの外面的構造と、約束や規則などの内面的構造があり、枠への反応も理解の手がかりとなる。","a":"小此木啓吾が体系化した概念で、治療者とクライエントの交流を規定する条件の総体をいう。面接の時間、頻度、場所、料金、対面か寝椅子かといった外面的な治療構造と、秘密を守るという約束や自由連想の規則、治療目標の取り決めなどの内面的な治療構造がある。治療構造は治療を安定させ、クライエントを守る枠組みである。同時に、遅刻、時間延長の要求、料金をめぐる問題など、枠に対する反応の中に転移や葛藤が表れるため、それ自体が理解の手がかりとなる。","k":["小此木啓吾","時間","料金","外面的","内面的","枠"],"p":"事例問題（終了間際に重要な話をする、延長を求めるなど）で「枠をどう守り、どう理解に使うか」を書く際の理論的根拠になる。"},{"id":"amae","t":"甘え","en":"amae","f":"seishin","s":"土居健郎が論じた、相手の好意をあてにして依存し、受け入れられたいと願う感情。乳児の母親への一体感の希求に源をもち、日本人の心性を理解する鍵であると同時に普遍的な心理とされる。","a":"土居健郎が『「甘え」の構造』（1971年）で論じた、日本語に固有の言葉を手がかりとする精神分析的な概念。相手の好意をあてにし、それに依存して受け入れられたいと願う感情で、乳児が母親との一体感を求める気持ちに源をもつ。土居は、これがバリントの受身的対象愛に通じるものであり、日本人の心性や対人関係を理解する鍵であると同時に、人間に普遍的な心理であると考えた。すねる、ひがむ、ひねくれるなどは、甘えが満たされないときの心の動きとされる。","k":["土居健郎","「甘え」の構造/甘えの構造","依存","一体感","バリント/受身的対象愛","普遍"],"p":"「日本人特有」とだけ書くのは不十分。土居自身は普遍的な心理として論じた点を押さえる。治療関係の中の甘え（転移）として論じることもできる。"},{"id":"ajase","t":"阿闍世コンプレックス","en":"Ajase complex","f":"seishin","s":"古澤平作が提唱し小此木啓吾が発展させた日本の精神分析の概念。母への一体感と未生怨をめぐる母子の愛憎の葛藤と、許し合うことで生じる罪意識を特徴とし、エディプス・コンプレックスと対比される。","a":"古澤平作が仏典の阿闍世王の物語をもとに提唱し、小此木啓吾が発展させた日本の精神分析の概念。母への一体感の願望と、母が自分を生む前に抱いた身勝手な思いへの怨み（未生怨）をめぐる、母と子の間の愛と憎しみの葛藤をいう。父との競争と処罰への恐れを軸とするエディプス・コンプレックスに対し、母と子が互いの罪を許し合うことで生じる、「とろかされる」ような罪意識（懺悔心）を重視する点に特徴がある。","k":["古澤平作","小此木啓吾","未生怨","母","許","エディプス"],"p":"処罰型の罪悪感（エディプス）と、許されることで生じる罪悪感（阿闍世）の対比を一文で書けるようにしておく。"},{"id":"negative-capability","t":"ネガティブ・ケイパビリティ","en":"negative capability","f":"seishin","s":"性急に事実や理由を求めず、不確かさや疑いの中にとどまっていられる能力。詩人キーツの言葉で、ビオンが治療者に必要な態度として取り上げた。","a":"詩人キーツ（Keats, J.）が書簡の中で、性急に事実や理由を求めず、不確かさや謎、疑いの中にとどまっていられる能力として述べた言葉。精神分析家のビオンは、これを治療者に必要な態度として取り上げ、記憶や欲望、早まった理解にとらわれずに、クライエントとの関わりに開かれていることの重要性を説いた。答えの出ない事態や、わからなさに耐える力として、安易な助言や結論で不安を解消しようとしない心理臨床の姿勢を考える手がかりとなる。","k":["キーツ/Keats","不確かさ","ビオン/Bion","記憶","わからなさ/答えの出ない"],"p":"「人を理解するとは」「心理臨床家に求められる資質」といった思想系の論述で使える。"},{"id":"neutrality","t":"中立性と禁欲原則","en":"neutrality / abstinence","f":"seishin","s":"精神分析的心理療法の治療者の態度。中立性はクライエントの心のどの部分にも肩入れしないこと、禁欲原則は転移的な欲求を実際に満たさず理解に向けることをいう。","a":"精神分析的心理療法における治療者の基本的な態度。中立性とは、クライエントの心のどの部分（欲動、自我、超自我）にも、また人生上の選択にも肩入れせず、価値判断や助言を控えて等しい距離に立つことをいう。禁欲原則とは、クライエントの転移的な欲求を治療関係の中で実際には満たさず、言葉で理解することをめざす原則である。これらは冷淡さや無関心を意味するのではなく、クライエントが自分の心を自由に探索できる空間を守るための態度である。","k":["中立","肩入れ","禁欲","転移","満たさ","冷淡/無関心"],"p":"来談者中心療法の「無条件の肯定的配慮」と比較させる問題も考えられる。どちらも「判断を押しつけない」点では共通する。"},{"id":"collective-unc","t":"集合的無意識","en":"collective unconscious","f":"jung","s":"ユングが提唱した、個人的無意識のさらに深層にある人類に共通する無意識の層。元型からなり、神話や昔話、夢などに共通するイメージが現れることの根拠とされた。","a":"ユング（Jung, C. G.）が提唱した概念で、個人の体験にもとづく個人的無意識のさらに深層にある、人類に共通する普遍的な無意識の層をいう。個人的無意識が主にコンプレックスからなるのに対し、集合的無意識は元型からなる。世界各地の神話や昔話、宗教的な象徴、夢などに似たイメージが繰り返し現れることの根拠とされた。フロイトの無意識が抑圧された個人的な内容を中心とするのに対し、ユングは無意識を、創造的で目的をもつものとしてとらえた。","k":["ユング/Jung","個人的無意識","普遍/人類","元型","神話/昔話","フロイト"],"p":"フロイトとの比較（個人的・抑圧されたもの／普遍的・創造的なもの、因果論／目的論）は最頻出の論点。"},{"id":"archetype","t":"元型","en":"archetype","f":"jung","s":"集合的無意識の内容として想定される、人類に共通するイメージや行動を生み出す心の型。それ自体は知りえず、夢や神話に現れる元型的イメージを通して知られる。影、アニマ、自己などがある。","a":"ユングが集合的無意識の内容として想定した、人類に共通するイメージや行動を生み出す心の型。元型そのものは意識でとらえることができず、夢や神話、昔話、宗教などに現れる元型的イメージを通して知られる。代表的なものに、影、ペルソナ、アニマ・アニムス、グレートマザー、老賢者、トリックスター、自己（セルフ）などがある。元型的イメージは強い情動を伴い、人を魅了したり圧倒したりする力（ヌミノース性）をもつ。","k":["ユング/Jung","集合的無意識","元型的イメージ","夢","神話","影"],"p":"「元型」と「元型的イメージ」を区別して書けるかがポイント（型そのものは直接知りえない）。"},{"id":"shadow","t":"影","en":"shadow","f":"jung","s":"ユングの元型の一つで、意識的な自我の態度と相いれないために受け入れずに生きてこなかった心の側面。他者に投影されやすく、その統合が個性化の重要な課題とされる。","a":"ユングの元型の一つで、その人が意識的な自我の態度と相いれないために、受け入れずに生きてこなかった心の側面をいう。多くは否定的な性質として体験されるが、生きられてこなかった肯定的な可能性を含むこともある。影は他者に投影されやすく、理由もなく強い嫌悪を感じる相手に、自分の影を見ていることがある。影を自分の一部として認め、意識と関係をもたせていくこと（影の統合）は、個性化の過程の重要な段階とされる。","k":["元型","受け入れ","生きてこなかった/生きられてこなかった","投影","統合","個性化"],"p":"個人的な影と、人類に共通する悪としての普遍的な影の区別まで書けると深い。「悪いもの」とだけ書かないこと。"},{"id":"persona","t":"ペルソナ","en":"persona","f":"jung","s":"ユングの概念で、社会の中で役割を果たすために身につける外的な態度。古代劇の仮面に由来する。社会への適応に必要だが、過度に同一化すると内面が見失われる。","a":"古代劇で役者がつけた仮面に由来するユングの概念で、人が社会の中で役割を果たすために身につける外的な態度や顔をいう。教師らしさ、親らしさなど、ペルソナは社会に適応するうえで必要なものである。しかし、ペルソナと自分自身を同一視しすぎると、内面の感情や個性が見失われ、硬直した生き方となる。逆に、ペルソナが十分に育たないと社会への適応が難しくなる。ペルソナと内的な心との釣り合いをとることが課題となる。","k":["仮面","社会","役割","適応","同一視"],"p":"「偽りの自分＝悪」と書かず、必要な機能と過剰同一化の危険の両面を書く。"},{"id":"anima","t":"アニマとアニムス","en":"anima / animus","f":"jung","s":"ユングの元型で、男性の無意識にある女性像をアニマ、女性の無意識にある男性像をアニムスという。内界との関係をつかさどる魂のイメージとされ、投影として強い引きつけを生む。","a":"ユングの元型で、男性の無意識にある女性像をアニマ、女性の無意識にある男性像をアニムスと呼ぶ。外界との関係をつかさどるペルソナに対して、内界との関係をつかさどる「魂」のイメージとされ、夢や芸術、恋愛における強い引きつけ（投影）として現れる。意識の態度を補う働きをもち、これと関わることが個性化の過程で重要とされる。ただし、性別による二分法を前提とした概念であるため、現代ではジェンダー観の変化を踏まえた再検討もなされている。","k":["男性","女性","無意識","魂","投影","個性化"],"p":"現代的な批判（性別二元論）に一言ふれると、知識を相対化して扱えることを示せる。"},{"id":"self-jung","t":"自己（セルフ）","en":"the Self","f":"jung","s":"ユング心理学で、意識と無意識を含む心全体の中心であり、心の全体性を表す元型。意識の中心である自我とは区別され、マンダラなどとして象徴的に現れる。","a":"ユングの心理学における、意識と無意識を含めた心全体の中心であり、心の全体性を表す元型。自我が意識の中心であるのに対し、自己は自我を超えた、より大きな心の中心とされる。円や四角を基本とする対称的な図形であるマンダラや、神のイメージ、賢者などの象徴として、夢や表現に現れる。自我が自己との関係を深め、心の全体性を実現していく過程が個性化の過程であり、自己は心の統合を導く目標でもある。","k":["意識と無意識","全体","自我","マンダラ","個性化"],"p":"「自我（ego）」との区別が最重要。日常語の「自己」と混同しないよう、セルフと併記するとよい。"},{"id":"individuation","t":"個性化の過程","en":"individuation process","f":"jung","s":"ユングが心理的発達の目標とした、その人が本来の自分自身になっていく過程。影やアニマなど無意識の内容と向き合い、自我が自己との関係を深めて心の全体性を実現していく。","a":"ユングが心理的な発達の目標とした、その人が本来の自分自身になっていく過程をいい、自己実現の過程とも呼ばれる。自我が、ペルソナとの過度な同一視から離れ、影やアニマ・アニムスなどの無意識の内容と向き合い、関係を結びながら、心全体の中心である自己に近づいていく。ユングは、とくに人生の後半（「人生の正午」以降）にこの課題が重要になると考えた。社会から孤立して個人主義的になることではなく、集合的なものとの関係の中で自分らしさを生きることである。","k":["本来","自己実現","影","自己","人生の後半/人生の正午","個人主義"],"p":"中年期の危機と結びつけて論じられることが多い。エリクソンの生殖性や統合と比較するのも一案。"},{"id":"complex","t":"コンプレックス","en":"complex","f":"jung","s":"ユングが言語連想検査から見いだした、ある感情によって結びつけられた心的内容の複合体（感情によって色づけられたコンプレックス）。意識から相対的に自律して働き、言動に影響を及ぼす。","a":"ユングが言語連想検査の研究から見いだした概念で、ある感情によって結びつけられた心的内容の集まり（感情によって色づけられた複合体）をいう。特定の刺激語に対して、反応時間の遅れ、反応の欠如、同じ語の反復などの乱れが生じ、その背後に特定のコンプレックスが想定された。コンプレックスは意識から相対的に自律して働き、本人の意図に反して言動を支配することがある。日本語の日常語でいう「劣等感」は、劣等コンプレックスの一例にすぎない。","k":["ユング/Jung","言語連想","感情","反応時間","自律","劣等感"],"p":"実験的な研究（言語連想検査）から生まれた概念である点は、ユングが実証的な研究者でもあったことを示す材料になる。"},{"id":"trickster","t":"トリックスター","en":"trickster","f":"jung","s":"神話や昔話に登場する、いたずら者・ぺてん師の姿をとる元型的存在。既存の秩序や境界を破って混乱をもたらす一方、新しい秩序や変化を生み出す両義性をもつ。","a":"世界各地の神話や昔話に登場する、いたずら者やぺてん師の姿をとる元型的な存在。北米先住民の神話のコヨーテやワタリガラス、北欧神話のロキ、ギリシア神話のヘルメスなどが知られる。既存の秩序や境界を気ままに破り、混乱や破壊をもたらすが、その結果として新たな秩序や変化が生まれるという、破壊と創造の両義性をもつ。臨床では、停滞した状況を思いがけず動かす存在として、また子どもの問題行動が家族に変化をもたらす働きを理解する視点として論じられる。","k":["神話/昔話","いたずら","秩序","境界","破壊と創造/両義","変化"],"p":"「ずる賢い者」とだけ書かず、両義性と「変化をもたらす」機能を中心に書く。治療者自身がトリックスター的に働く場面の議論もある。"},{"id":"great-mother","t":"グレートマザー（太母）","en":"Great Mother","f":"jung","s":"ユングの元型の一つで、母なるものの普遍的イメージ。生み育て包み込む肯定的側面と、呑み込み自立を妨げる否定的側面の両面をもつ。","a":"ユングの元型の一つで、母なるものの普遍的なイメージ。生み、育て、包み込む肯定的な側面と、抱え込み、呑み込み、自立を妨げる否定的な側面の両面をもつ。大地や海、洞窟、女神、魔女や山姥などの像として、神話や昔話に現れる。河合隼雄は、すべてを平等に包み込む母性原理が強い日本の社会と心性の特徴を論じ、その長所とともに、個の確立の難しさや、不登校などの問題の背景にもふれた。","k":["元型","母","育て","呑み込","河合隼雄","母性原理"],"p":"実際の母親とイメージとしての母（元型）を区別して書く。母性原理と父性原理（切る・分ける）の対比も押さえておく。"},{"id":"wise-old-man","t":"老賢者","en":"wise old man","f":"jung","s":"ユングの元型の一つで、知恵や精神的な導きを象徴する老人のイメージ。夢や昔話で主人公に助言を与える存在として現れる。同一化すると誇大な状態に陥る危険がある。","a":"ユングの元型の一つで、知恵や洞察、精神的な導きを象徴する老人のイメージ。夢や神話、昔話の中で、主人公が困難に陥ったときに現れ、助言や道具を与えて道を示す存在として描かれる（魔法使い、仙人、隠者など）。意識だけでは解決できない状況で、無意識から現れる意味や方向性を表すとされる。一方で、その力に同一化すると、自分が特別な知恵をもつかのように思い込む誇大な状態（インフレーション）に陥る危険もある。","k":["元型","知恵","導き/助言","夢","同一化","インフレーション"],"p":"治療者が「老賢者」と同一化して万能的になる危険（クライエントからの理想化を引き受けすぎる）と結びつけると臨床的。"},{"id":"compensation","t":"補償","en":"compensation","f":"jung","s":"ユング心理学で、意識の態度が一面的になったとき、無意識が反対の傾向を示して心のバランスを回復させようとする働き。ユングは夢の主要な機能を補償とみた。","a":"ユングの心理学における無意識の基本的な働きで、意識の態度が一面的になったときに、無意識がそれと反対の傾向を示し、心全体のバランスを回復させようとすることをいう。たとえば、ふだん謙虚すぎる人が夢の中で尊大にふるまう場合、その夢は意識の一面性を補っていると考えられる。ユングは夢を、フロイトのように偽装された願望充足とみるのではなく、意識の状況に対する無意識からのメッセージ（補償）としてとらえた。","k":["無意識","一面","バランス","夢","願望充足","フロイト"],"p":"アドラーの「補償」（劣等感の補償）と同じ語だが意味が異なる点に注意。"},{"id":"synchronicity","t":"共時性","en":"synchronicity","f":"jung","s":"ユングの概念で、因果関係がないにもかかわらず、心の内的状態と外界の出来事が意味ある形で一致して生じる現象（意味のある偶然の一致）。","a":"ユングが提唱した概念で、因果的な関係がないにもかかわらず、心の内的な状態と外界の出来事が、意味のある形で一致して起こる現象をいう（意味のある偶然の一致）。ユングは物理学者パウリとの共著（1952年）で論じた。因果律だけでは説明できない、心と物質の間の非因果的な連関を想定するものである。心理療法の中でも、クライエントの内的な変化と外的な出来事が呼応して起こるように感じられることがあり、その意味を考えることが重視される。","k":["因果","意味のある偶然の一致/偶然","パウリ","内的","外界/外的"],"p":"科学的な実証の難しさにもふれつつ、「意味」を扱う心理臨床の態度として論じるとバランスがよい。"},{"id":"active-imagination","t":"能動的想像","en":"active imagination","f":"jung","s":"ユングが発展させた方法で、意識を保ったまま無意識から浮かぶイメージに注意を向け、それと対話し関わることで、無意識の内容を意識に統合していく。","a":"ユングが自らの無意識との対決の経験から発展させた方法で、意識をはっきり保ったまま、無意識から浮かんでくるイメージや人物に注意を向け、それと対話したり関わったりする技法である。イメージを意識的に操作して作り変えるのではなく、自律的に展開するのに任せつつ、自我が主体的に応答する点に特徴がある。絵や文章などの表現を伴うこともある。無意識の内容を意識に統合していく方法として、個性化の過程に役立つとされる。","k":["ユング/Jung","意識","イメージ","対話","自律","統合"],"p":"受け身の空想（白昼夢）との違い＝自我が主体的に関わる点を明確にする。"},{"id":"types","t":"心理学的タイプ（タイプ論）","en":"psychological types","f":"jung","s":"ユングの性格類型論（1921）。外向・内向の2つの一般的態度と、思考・感情・感覚・直観の4つの心理機能を組み合わせて8つのタイプを示した。主機能の対極は劣等機能となる。","a":"ユングが1921年の『タイプ論』で示した性格の類型論。関心やエネルギーが外界に向かう外向と、内界に向かう内向という2つの一般的態度と、思考・感情（合理機能）、感覚・直観（非合理機能）という4つの心理機能を組み合わせて、8つのタイプを考えた。最もよく発達した主機能に対し、その対極にある機能は未分化な劣等機能となり、無意識的に働くとされる。ユングにとってタイプ論は、人を分類するためよりも、自分の一面性に気づくための手がかりであった。","k":["1921","外向","内向","思考","直観","劣等機能"],"p":"特性論（ビッグファイブ）との違い（類型か連続量か）にふれると基礎心理学との橋渡しができる。"},{"id":"amplification","t":"拡充法","en":"amplification","f":"jung","s":"ユング派の夢やイメージの理解の方法で、夢のイメージを神話・昔話・宗教などの類似した素材と照らし合わせ、その元型的な意味を広げて理解すること。フロイトの還元的方法と対比される。","a":"ユング派の夢やイメージの理解の方法で、夢に現れたイメージを、神話、昔話、宗教、文化的な象徴などの類似する素材と照らし合わせ、その意味を豊かに広げていく方法をいう。フロイトの自由連想が、イメージから連想をたどって背後の個人的な内容へと還元していく傾向をもつのに対し、拡充法はイメージそのものにとどまり、その元型的・普遍的な意味の広がりを明らかにしようとする。実際には、本人の個人的な連想と組み合わせて用いられる。","k":["ユング","神話","象徴","類似","自由連想","元型"],"p":"「還元的（フロイト）／拡充的（ユング）」という対比で書くと比較問題にそのまま使える。"},{"id":"constellation","t":"布置","en":"constellation","f":"jung","s":"ユング心理学で、ばらばらに見える出来事やイメージが、ある時に意味ある全体として配置されること。河合隼雄は、因果ではなく布置を読むことを心理療法で重視した。","a":"ユング心理学で用いられる概念で、星々が星座を形づくるように、ばらばらに見える出来事や人物、イメージが、ある時に一つの意味あるまとまりとして配置されることをいう。元型やコンプレックスが活性化すると、内的な体験と外的な出来事が、それに沿った形で布置されるように感じられる。河合隼雄は、問題を原因と結果の連鎖で説明するのではなく、その人をめぐる全体の布置を読むことが、心理療法において重要であると強調した。","k":["星座","まとまり","元型/コンプレックス","河合隼雄","原因と結果/因果"],"p":"因果論的な理解（原因探し）と布置的な理解（全体の意味）の対比は、思想系の論述にも使える。"},{"id":"hollow-center","t":"中空構造","en":"hollow center structure","f":"jung","s":"河合隼雄が『古事記』の分析から示した日本人の心と社会の構造のモデル。中心に位置する神が無為であり、中心が空であることで対立する力が均衡を保つ構造をいう。","a":"河合隼雄が『古事記』の神話の分析から提唱した、日本人の心や社会の構造のモデル。『古事記』では、重要な三神の組のうち中心に位置する神（アメノミナカヌシ、ツクヨミ、ホスセリ）がほとんど何の働きもしないことに注目し、中心が空であることによって、対立する力が均衡を保つ構造であるとした。中心に絶対的な原理を置く西洋的な構造と対比される。対立を共存させる柔軟さがある一方で、責任の所在があいまいになりやすいという問題も指摘された。","k":["河合隼雄","古事記","中心","均衡","西洋/対比","責任"],"p":"日本文化論として「よい／悪い」で終わらせず、長所と短所の両面を示すのが河合の論じ方に沿う。"},{"id":"wounded-healer","t":"傷ついた治療者","en":"wounded healer","f":"jung","s":"治療者は自らの傷を自覚しているからこそ他者の癒やしに関われるという治療者像。ギリシア神話のケイローンに由来し、ユングやグッゲンビュール＝クレイグが論じた。","a":"ユングが、ギリシア神話で自ら癒えない傷を負いながら医術を教えたケンタウロスのケイローンになぞらえて述べた治療者像。治療者は、自らの傷つきや弱さを自覚しているからこそ、クライエントの苦しみに共感し、癒やしの過程に関わることができるという考え方である。グッゲンビュール＝クレイグは、治療者が自分の傷を忘れて「癒やす者」の側に一方的に立つと、治療関係の元型が分裂し、力の濫用が生じると警告した。教育分析の意義とも関わる。","k":["ケイローン","傷","共感","グッゲンビュール","力","教育分析"],"p":"「傷があるから治療者に向いている」という意味ではない。自覚と吟味（教育分析・スーパービジョン）が前提であることを明確にする。"},{"id":"ptsd","t":"心的外傷後ストレス障害（PTSD）","en":"posttraumatic stress disorder","f":"trauma","s":"生命の危険や重傷、性的暴力などの外傷的出来事の後、侵入症状、回避、認知と気分の陰性の変化、覚醒度と反応性の変化が1か月以上続き、生活に支障をきたす障害。","a":"実際にまたは危うく死ぬ、重傷を負う、性的暴力を受けるといった出来事を、直接体験したり目撃したりした後に生じる障害。DSM-5では、①侵入症状（フラッシュバック、悪夢など）、②持続的な回避、③認知と気分の陰性の変化（自責、否定的な信念、孤立感など）、④覚醒度と反応性の著しい変化（過覚醒、過剰な驚愕反応、睡眠の障害など）が1か月以上続き、生活に支障をきたすものとされる。持続エクスポージャー療法などのトラウマ焦点化治療の効果が示されている。","k":["死","侵入","回避","陰性","過覚醒/覚醒","1か月"],"p":"4つの症状群を正確に書けることが最低ライン。「出来事の後に誰もが発症するわけではない」点（多くは自然に回復する）も添えると適切。"},{"id":"asd-acute","t":"急性ストレス障害","en":"acute stress disorder","f":"trauma","s":"外傷的出来事の後、3日から1か月の間に、侵入、陰性気分、解離、回避、覚醒の症状が生じ、苦痛や支障をきたす状態。1か月を超えて続く場合はPTSDが検討される。","a":"外傷的な出来事の後、3日から1か月の間に、侵入症状、陰性気分、解離症状、回避症状、覚醒症状が生じ、苦痛や生活上の支障をきたすものをいう（DSM-5）。症状が1か月を超えて続く場合は、PTSDの診断が検討される。出来事の直後に強いストレス反応が生じることは多くの人にみられる自然な反応でもあり、多くは時間とともに回復する。そのため急性期には、症状を病理化しすぎず、安全と安心の確保、生活の支援、心理的応急処置などが重視される。","k":["3日","1か月","解離","PTSD","自然な反応","心理的応急処置"],"p":"期間（3日〜1か月）とPTSDとの関係を正確に。急性期の介入として何を「しない」か（体験を詳しく語らせない）にもふれるとよい。"},{"id":"cptsd","t":"複雑性PTSD","en":"complex PTSD","f":"trauma","s":"虐待や監禁など長期・反復的なトラウマの後に生じやすい障害。PTSDの中核症状に加えて、感情制御の困難、否定的な自己概念、対人関係の困難（自己組織化の障害）を伴う。ICD-11に収載された。","a":"虐待や家庭内暴力、監禁など、逃れることが難しい状況で、長期にわたって繰り返されたトラウマの後に生じやすい障害。ハーマン（Herman, J. L.）が1992年に提唱し、ICD-11で正式な診断名となった。PTSDの中核症状（再体験、回避、脅威の感覚）に加えて、感情制御の困難、否定的な自己概念（恥や無価値感）、対人関係の困難からなる「自己組織化の障害」を伴う。治療では、安全の確立、トラウマ記憶の処理、日常生活や人との結びつきの回復という段階的な支援が重視される。","k":["長期","ハーマン/Herman","ICD-11","感情制御","否定的な自己概念","対人関係"],"p":"DSM-5には独立した診断名としてはない点（ICD-11にある）を区別できると正確。境界性パーソナリティ障害との鑑別も論点になる。"},{"id":"dissociation","t":"解離","en":"dissociation","f":"trauma","s":"意識、記憶、同一性、知覚、身体感覚など、通常は統合されている心の働きがまとまりを失う状態。圧倒的な体験から心を守る働きとしても理解され、トラウマと関連が深い。","a":"意識、記憶、同一性、感情、知覚、身体の感覚、行動など、通常は統合されている心の働きが、まとまりを失ったり断絶したりする状態をいう。ジャネ（Janet, P.）が早くから論じた。圧倒的な体験から心を守る働きとしても理解され、トラウマとの関連が深い。解離症群には、解離性同一症、解離性健忘、離人感・現実感消失症などがある。臨床では、話の途中でぼんやりする、記憶が抜けるなどのサインに気づき、安全とグラウンディングを重視して関わることが大切である。","k":["統合","ジャネ/Janet","トラウマ","解離性同一症","離人","グラウンディング"],"p":"フロイトの「抑圧」（水平の分割）とジャネの「解離」（垂直の分割）の対比は理論問題で使える。"},{"id":"tic","t":"トラウマインフォームド・ケア","en":"trauma-informed care","f":"trauma","s":"トラウマの広範な影響についての知識を組織全体で共有し、あらゆる関わりに活かす支援の枠組み。「何があったのか」という視点に立ち、安全、信頼、選択、協働を重視して再トラウマ化を防ぐ。","a":"トラウマの影響についての知識を、支援に関わるすべての人や組織が共有し、あらゆる関わりに活かす支援の枠組み。米国のSAMHSAは、トラウマの広範な影響を理解し（Realize）、そのサインに気づき（Recognize）、知識を方針や実践に反映させて対応し（Respond）、再トラウマ化を防ぐ（Resist re-traumatization）ことを挙げている。「この人の何がおかしいのか」ではなく「この人に何があったのか」と問う視点に立ち、安全、信頼、選択、協働、エンパワメントを重視する。","k":["組織","SAMHSA","気づ","再トラウマ化","何があった","安全"],"p":"トラウマ治療（専門的な治療）とは別の「土台となる関わり方」である点を区別して書く。学校・施設・医療など場全体の取り組みとして論じられる。"},{"id":"pfa","t":"心理的応急処置（PFA）","en":"psychological first aid","f":"trauma","s":"災害や事件の直後の人々に行う人道的・支持的な初期支援。WHO版では「見る・聞く・つなぐ」を原則とし、安全の確保と基本的ニーズへの対応を重視し、体験を無理に語らせない。","a":"災害や事件などの危機的な出来事に遭遇した直後の人々に対して行う、人道的で支持的な初期の支援。WHO版では、準備をしたうえで「見る（Look）」「聞く（Listen）」「つなぐ（Link）」を活動の原則とし、安全の確保、基本的なニーズへの対応、話を無理に聞き出さずに寄り添うこと、必要な支援や情報につなぐことなどを重視する。専門家だけが行うものではなく、トラウマ体験を詳しく語らせるといった侵襲的な介入を行わないことが特徴である。","k":["災害","WHO","見る","聞く","つなぐ","無理に"],"p":"心理的デブリーフィングとの対比（語らせない・強制しない）で書くと、エビデンスの変遷まで示せる。"},{"id":"pe","t":"持続エクスポージャー療法（PE）","en":"prolonged exposure therapy","f":"trauma","s":"フォアらが開発したPTSDの認知行動療法。情動処理理論にもとづき、トラウマ記憶を繰り返し語る想像エクスポージャーと、避けている状況に向き合う現実エクスポージャーを行う。","a":"フォア（Foa, E. B.）らが開発した、PTSDに対する認知行動療法。恐怖の記憶の構造が修正されることで回復が起こるとする情動処理理論にもとづく。心理教育と呼吸法に続き、トラウマ記憶を繰り返し想起して語る想像エクスポージャーと、安全だが避けている状況や場所に段階的に向き合う現実エクスポージャーを行う。回避が症状を維持していると考え、記憶に向き合うことで不安が低下し、出来事についての意味づけが修正されていく。","k":["フォア/Foa","PTSD","情動処理理論","想像エクスポージャー","現実エクスポージャー","回避"],"p":"「トラウマを思い出させるのは危険」という誤解に対し、安全な治療構造のもとで段階的に行うことを示すとよい。"},{"id":"tfcbt","t":"トラウマフォーカスト認知行動療法（TF-CBT）","en":"trauma-focused CBT","f":"trauma","s":"コーエンらが開発した、トラウマを受けた子どもと養育者のための認知行動療法。心理教育、感情調整、認知対処、トラウマ・ナラティブの作成などの構成要素（PRACTICE）からなる。","a":"コーエン（Cohen, J. A.）らが開発した、トラウマを受けた子どもと養育者のための認知行動療法で、主に3〜18歳を対象とする。心理教育とペアレンティング、リラクセーション、感情の表現と調整、認知の対処、トラウマ・ナラティブの作成と処理、現実場面での段階的な曝露、親子の合同セッション、安全の強化という構成要素からなり、頭文字をとってPRACTICEと呼ばれる。養育者が治療に参加し、子どもを支える力を高める点に特徴がある。","k":["子ども","養育者","トラウマ・ナラティブ/ナラティブ","PRACTICE","段階"],"p":"子どもの支援では「養育者の参加」が鍵であること、非加害の養育者が子どもを信じ支えることの意味を書けると臨床的。"},{"id":"emdr","t":"EMDR（眼球運動による脱感作と再処理法）","en":"EMDR","f":"trauma","s":"シャピロが開発したトラウマの治療法。トラウマ記憶に注意を向けながら眼球運動などの両側性刺激を加え、記憶の再処理を促す。PTSDに対する効果が示されている。","a":"シャピロ（Shapiro, F.）が開発したトラウマの治療法。トラウマ記憶のイメージや否定的な認知、身体の感覚に注意を向けながら、治療者の指の動きを目で追うなどの左右交互の刺激（両側性刺激）を加えることで、記憶の処理を促す。8段階の手続きからなり、適応的情報処理モデルを理論的な背景とする。PTSDへの効果が示され、国際的な治療ガイドラインでも推奨されているが、眼球運動そのものが効果に必要かどうかについては議論がある。","k":["シャピロ/Shapiro","両側性刺激/左右交互","8段階","適応的情報処理","PTSD"],"p":"効果の実証と、作用機序の議論を分けて書くと、研究を批判的に読む力を示せる。"},{"id":"cpt","t":"認知処理療法（CPT）","en":"cognitive processing therapy","f":"trauma","s":"レジックらが開発したPTSDの認知療法。トラウマ後に生じた自責などの偏った考え（スタックポイント）を、ソクラテス式の問いかけなどで検討し修正する。","a":"レジック（Resick, P. A.）らが開発した、PTSDに対する認知療法。トラウマの後に生じた、出来事や自分、他者、世界についての偏った考え（スタックポイント）が回復を妨げると考える。「自分が悪かった」と出来事を元の信念に合わせて歪める同化や、「誰も信用できない」と信念を極端に変えすぎる過剰調節に気づき、ソクラテス式の問いかけや練習用紙を使って検討する。安全、信頼、力とコントロール、自尊心、親密さのテーマを扱う。","k":["レジック/Resick","スタックポイント","同化","過剰調節","ソクラテス"],"p":"「自責感」を扱う治療として、性暴力被害などの事例問題で根拠に使える。ピアジェの同化・調節との用語の対応にも気づけるとよい。"},{"id":"secondary-victim","t":"二次被害","en":"secondary victimization","f":"trauma","s":"犯罪や災害などの被害者が、その後に周囲の言動、報道、司法手続などによって受ける、さらなる精神的な傷つき。回復を妨げ、援助要請を抑制する要因となる。","a":"犯罪や性暴力、災害などの被害を受けた人が、その後に、周囲の人や社会、支援や司法の過程などから受ける、さらなる精神的な傷つきをいう。「なぜ逃げなかったのか」と責めるような言葉、好奇の目、心ない報道、繰り返し事情を聴かれる負担などがその例である。被害者はもともと自責感を抱きやすく、二次被害によって回復が妨げられ、援助を求めなくなることもある。支援者自身が二次被害を与えうることを自覚し、被害者の尊厳と自己決定を尊重する関わりが求められる。","k":["被害","周囲","責め","報道","自責","支援者"],"p":"「なぜ」で始まる質問が責めとして響きやすいことなど、具体的な言葉づかいまで書けると実践的。"},{"id":"vicarious","t":"代理受傷と共感疲労","en":"vicarious traumatization / compassion fatigue","f":"trauma","s":"トラウマを負った人の話を聴く支援者に生じる影響。支援者の世界観や安全感が変化する代理受傷（マッキャンとパールマン）と、共感の代償としての疲弊である共感疲労（フィグリー）がある。","a":"トラウマを負った人の話を繰り返し聴く支援者に生じる心理的な影響をいう。マッキャン（McCann, I. L.）とパールマン（Pearlman, L. A.）は、支援者自身の世界観や安全感、他者への信頼などの認知の枠組みが変化していくことを代理受傷と呼んだ。フィグリー（Figley, C. R.）は、共感的に関わることの代償として生じる、PTSDに類似した症状や疲弊を共感疲労（二次的外傷性ストレス）と呼んだ。スーパービジョン、セルフケア、組織的な支えが予防に重要である。","k":["支援者","代理受傷","パールマン/マッキャン","フィグリー/Figley","共感疲労","スーパービジョン"],"p":"個人の弱さではなく、職業上避けがたいリスクとして組織で対策する、という視点を示す。バーンアウトとの違いも整理しておく。"},{"id":"grief","t":"遷延性悲嘆症","en":"prolonged grief disorder","f":"trauma","s":"死別後、故人への強い思慕やとらわれが長く続き、深い苦痛と生活上の支障をきたす状態。ICD-11では死別後6か月以上、DSM-5-TRでは12か月以上の持続が目安とされる。","a":"大切な人との死別の後、故人への強い思慕やとらわれが長く続き、深い感情的な苦痛と生活上の支障をきたす状態をいう。ICD-11では死別後少なくとも6か月、DSM-5-TRでは12か月以上（子どもは6か月以上）持続することが目安とされる。悲嘆そのものは自然な反応であり、文化や宗教によっても表れ方は異なるため、病的な悲嘆と通常の悲嘆を慎重に区別する必要がある。突然の死や暴力的な死別の後に生じやすく、悲嘆に焦点を当てた心理療法の効果が示されている。","k":["死別","思慕","6か月","12か月","自然な反応","文化"],"p":"「悲しみを病気にする」ことへの批判的な視点もあわせて書くと、診断の扱いに慎重であることを示せる。"},{"id":"ptg","t":"心的外傷後成長（PTG）","en":"posttraumatic growth","f":"trauma","s":"テデスキとカルフーンが提唱した、外傷的出来事との苦闘の結果として生じるポジティブな心理的変容。他者との関係、新たな可能性、人間としての強さ、精神性、人生への感謝の5領域がある。","a":"テデスキ（Tedeschi, R. G.）とカルフーン（Calhoun, L. G.）が提唱した概念で、外傷的な出来事やそれに伴う苦しみとのもがきの結果として生じる、ポジティブな心理的変容の体験をいう。他者との関係、新たな可能性、人間としての強さ、精神性的（スピリチュアルな）変容、人生への感謝の5つの領域がある。成長は苦痛がなくなることを意味せず、苦痛と共存しうる。支援者が成長を求めたり美化したりすると、当事者を追い詰める危険があることにも注意が必要である。","k":["テデスキ/Tedeschi","もがき","他者との関係","人生への感謝/感謝","苦痛","美化"],"p":"レジリエンス（回復・適応の維持）との違い（PTGは以前を超える変化）を書き分ける。"},{"id":"resilience","t":"レジリエンス","en":"resilience","f":"trauma","s":"逆境や強いストレスにさらされても、適応を保ち回復していく力やその過程。個人の特性だけでなく、家族や地域とのつながりなど環境との相互作用によって育まれる。","a":"逆境や強いストレスにさらされても、適応を保ち、あるいは回復していく力やその過程をいう。もとは物理学で「弾性」を意味する言葉である。かつては特別な個人の資質と考えられがちだったが、マステン（Masten, A. S.）は、ごく普通の適応のシステムの働きによって生じる「ありふれた魔法」であると述べた。個人の特性（自己効力感、感情調節など）だけでなく、家族や学校、地域とのつながりといった環境の要因との相互作用によって育まれる。","k":["逆境","回復","マステン/Masten","ありふれた魔法","環境","つながり"],"p":"「レジリエンスが低い人が悪い」という自己責任論にならないよう、環境要因を強調する。"},{"id":"crisis","t":"危機介入","en":"crisis intervention","f":"trauma","s":"重大な出来事に直面し、従来の対処では乗り越えられずに心理的均衡が崩れた危機状態に対して、短期間・集中的に現在の問題に焦点を当てて援助し、元の機能水準の回復をめざす介入。","a":"危機とは、重要な問題に直面し、それまでの対処の方法では乗り越えられずに、心理的な均衡が崩れた状態をいう。リンデマン（Lindemann, E.）の火災による死別者の研究や、キャプラン（Caplan, G.）の危機理論を背景に発展した。危機状態は一般に数週間程度で何らかの均衡に向かうため、その時期に、短期間で集中的に、現在の問題に焦点を当てて援助し、危機以前の機能水準の回復をめざす。安全の確保、情緒的な支援、現実的な問題解決、社会資源の活用が中心となる。","k":["均衡","対処","リンデマン/Lindemann","キャプラン/Caplan","短期","社会資源"],"p":"危機は「危険」であると同時に「成長の機会」でもある、という両面性を書くと理論的な理解が示せる。"},{"id":"debriefing","t":"心理的デブリーフィング","en":"psychological debriefing","f":"trauma","s":"災害や事件の直後に体験者を集め、出来事の事実、考え、感情を順に語らせる集団的介入。単独の予防的介入としての効果は認められず、症状の悪化の可能性も指摘されている。","a":"災害や事件の直後に体験者を集め、出来事の事実、考え、感情などを順を追って語ってもらう集団的な介入。消防士などの職業的な救援者を対象とした緊急事態ストレス・デブリーフィング（CISD）として広まった。しかし、その後の研究では、一回限りの単独の介入としてはPTSDの予防効果が認められず、むしろ症状を悪化させる可能性も指摘された。そのため現在では、急性期に体験を詳しく語らせることは推奨されず、心理的応急処置などが勧められている。","k":["直後","語","CISD","予防効果","悪化","心理的応急処置"],"p":"「善意の介入が害になりうる」ことをエビデンスで確かめる重要性の例として、研究法の論述にも使える。"},{"id":"aces","t":"逆境的小児期体験（ACEs）","en":"adverse childhood experiences","f":"trauma","s":"18歳までに経験した虐待、ネグレクト、家庭内暴力の目撃、家族の精神疾患などの逆境体験。フェリッティらの研究で、その数が多いほど成人期の心身の疾患のリスクが高まることが示された。","a":"18歳までに経験した虐待、ネグレクト、家庭内暴力の目撃、家族の精神疾患や物質の乱用、両親の別離、家族の服役などの逆境的な体験をいう。フェリッティ（Felitti, V. J.）らによる1998年の大規模な研究で、こうした体験の数が多いほど、成人期のうつ病や自殺企図、依存症だけでなく、心疾患などの身体疾患のリスクも段階的に高まることが示された。予防や早期支援の重要性を示すとともに、トラウマインフォームド・ケアが広がる契機となった。","k":["18歳","虐待","フェリッティ/Felitti","数が多い","身体疾患","トラウマインフォームド"],"p":"ACE得点は集団のリスクを示すもので、個人の将来を決めるものではない（決定論にしない）という注意を添える。"},{"id":"window","t":"耐性の窓","en":"window of tolerance","f":"trauma","s":"シーゲルが提唱した、感情に圧倒されずに考えたり感じたりできる、ほどよい覚醒の範囲。上を超えると過覚醒、下を超えると低覚醒（麻痺・解離）となり、トラウマを受けた人では狭くなりやすい。","a":"シーゲル（Siegel, D. J.）が提唱した概念で、人が覚醒した状態を保ちながらも、感情や体験に圧倒されずに考えたり感じたりできる、ほどよい覚醒の範囲をいう。この範囲を上に超えると、不安やパニック、怒りなどの過覚醒の状態に、下に超えると、麻痺や解離、無気力などの低覚醒の状態に陥る。トラウマを受けた人では、この窓が狭くなりやすい。治療では、窓の中にとどまれるよう調整しながら体験を扱い、窓を広げていくことがめざされる。","k":["シーゲル/Siegel","覚醒","過覚醒","低覚醒","解離","広げ"],"p":"面接中のペース配分（話しすぎて圧倒されないように）の根拠として、事例問題で使える。"},{"id":"victim-law","t":"犯罪被害者等基本法","en":"Basic Act on Crime Victims","f":"trauma","s":"2004年に成立した、犯罪被害者等の権利と国・地方公共団体の責務を定めた法律。個人の尊厳にふさわしい処遇を基本理念とし、相談、経済的支援、二次被害の防止などの施策を求める。","a":"2004年に成立し、2005年に施行された法律で、犯罪被害者等が個人の尊厳にふさわしい処遇を保障される権利を有することを基本理念に掲げる。国や地方公共団体の責務を定め、相談と情報の提供、損害の回復と経済的な支援、保健医療・福祉サービスの提供、安全の確保、刑事手続への参加の機会の拡充、二次被害の防止などの施策を求めている。被害者の支援を国の責務として明確にし、民間の被害者支援団体や心理職を含む多様な機関の連携を促した。","k":["2004","尊厳","国","二次被害","刑事手続","連携"],"p":"心理職の役割を「個人の心理療法」に限らず、司法・行政・民間団体との連携の中に位置づけて書くとよい。"},{"id":"dsm-icd","t":"DSMとICD","en":"DSM / ICD","f":"iryo","s":"精神疾患の国際的な診断分類。DSMはアメリカ精神医学会の診断・統計マニュアル（最新はDSM-5-TR）、ICDはWHOの国際疾病分類（最新はICD-11）で、操作的診断基準によって信頼性を高めた。","a":"精神疾患の国際的な診断分類の体系。DSMはアメリカ精神医学会による『精神疾患の診断・統計マニュアル』で、2013年にDSM-5、2022年にその改訂版のDSM-5-TRが刊行された。ICDは世界保健機関（WHO）による疾病全般の国際分類で、2019年に採択されたICD-11が2022年に発効した。いずれも明確な基準にもとづく操作的診断によって診断の信頼性を高めたが、症状の数による診断は、背景にある個人の体験や文脈を見落としやすいという批判もある。","k":["アメリカ精神医学会","DSM-5","WHO/世界保健機関","ICD-11","操作的診断","信頼性"],"p":"「信頼性は高めたが妥当性は？」という問いを立てると、心理アセスメントとの関係を論じられる。"},{"id":"schizophrenia","t":"統合失調症","en":"schizophrenia","f":"iryo","s":"主に思春期から青年期に発症する精神疾患。幻覚や妄想などの陽性症状、感情の平板化や意欲低下などの陰性症状、認知機能障害がみられ、抗精神病薬と心理社会的支援で治療する。","a":"多くは思春期から青年期に発症する精神疾患で、生涯有病率はおよそ1％とされる。幻覚（とくに幻聴）や妄想、まとまりのない会話や行動などの陽性症状と、感情の平板化、意欲の低下、会話の貧困、社会的なひきこもりなどの陰性症状、さらに注意や記憶などの認知機能の障害がみられる。治療は抗精神病薬による薬物療法を基本に、心理教育、社会生活スキルトレーニング、家族支援、地域での生活支援などを組み合わせる。家族の感情表出（EE）が再発に影響する。","k":["1％/1%","幻覚/幻聴","妄想","陽性症状","陰性症状","抗精神病薬"],"p":"心理職の役割（心理教育、家族支援、リカバリーの支援）を具体的に書けるようにしておく。"},{"id":"depression","t":"うつ病","en":"major depressive disorder","f":"iryo","s":"抑うつ気分または興味・喜びの喪失を中心に、睡眠や食欲の変化、疲労感、無価値感、集中力の低下、希死念慮などが2週間以上続き、生活に支障をきたす精神疾患。","a":"抑うつ気分、または興味や喜びの喪失のいずれかを含み、食欲や体重の変化、睡眠の障害、精神運動の焦燥や制止、疲労感、無価値感や過剰な罪責感、思考力や集中力の低下、死についての反復的な思考などのうち5つ以上が、2週間以上ほぼ毎日続き、生活に支障をきたすものをいう（DSM-5）。治療には、休養、抗うつ薬、認知行動療法や対人関係療法などがある。自殺の危険の評価が欠かせず、回復期にも危険が高まることに注意が必要である。","k":["抑うつ気分","興味","2週間","5つ","自殺","認知行動療法"],"p":"事例問題では「休養の保障」「自殺リスクの確認」「医療との連携」の3点を外さないこと。"},{"id":"bipolar","t":"双極性障害","en":"bipolar disorder","f":"iryo","s":"気分の高揚や活動性の増加を示す躁病（軽躁病）エピソードと、抑うつエピソードを繰り返す精神疾患。躁病エピソードのあるⅠ型と、軽躁病エピソードと抑うつのあるⅡ型がある。","a":"気分が高揚し活動性が増して、睡眠欲求の減少、多弁、観念奔逸、誇大性、浪費などの無謀な行動がみられる躁病（または軽躁病）エピソードと、抑うつエピソードを繰り返す精神疾患。躁病エピソード（1週間以上）がみられる双極Ⅰ型と、軽躁病エピソード（4日以上）と抑うつエピソードがみられる双極Ⅱ型がある。うつ病と誤って診断されやすい。治療は気分安定薬などの薬物療法が中心で、心理教育によって再発のサインに気づき、生活リズムを整えることが重要である。","k":["躁病","軽躁","抑うつ","Ⅰ型/I型/1型","気分安定薬","生活リズム"],"p":"うつ病との鑑別（軽躁エピソードの既往の確認）が臨床上重要である点を書けるとよい。"},{"id":"bpd","t":"境界性パーソナリティ障害","en":"borderline personality disorder","f":"iryo","s":"対人関係、自己像、感情の著しい不安定さと衝動性を特徴とするパーソナリティ障害。見捨てられ不安、理想化とこき下ろし、自傷行為、慢性的な空虚感などがみられる。","a":"対人関係、自己像、感情の不安定さと、著しい衝動性を特徴とするパーソナリティ障害。見捨てられることへの強い不安、理想化とこき下ろしの間を揺れ動く不安定な対人関係、同一性の混乱、自傷行為や自殺企図の繰り返し、慢性的な空虚感、激しい怒りなどがみられる。カーンバーグは、分裂などの原始的防衛と同一性拡散を特徴とする境界パーソナリティ構造を論じた。弁証法的行動療法やメンタライゼーションに基づく治療などの効果が示されている。","k":["見捨てられ","理想化","自傷","空虚","カーンバーグ/Kernberg","弁証法的行動療法"],"p":"治療者側の逆転移（振り回される、救いたくなる）と、一貫した治療構造・チームでの対応の重要性まで書けると臨床的。"},{"id":"autism","t":"自閉スペクトラム症","en":"autism spectrum disorder","f":"iryo","s":"社会的コミュニケーションと対人的相互反応の持続的な困難と、限定された反復的な行動・興味・活動（感覚の過敏や鈍麻を含む）を特徴とする神経発達症。DSM-5でスペクトラムとして統合された。","a":"DSM-5で、自閉症、アスペルガー障害などを連続体（スペクトラム）として統合した神経発達症。①社会的コミュニケーションおよび対人的相互反応における持続的な困難と、②行動、興味、活動の限定された反復的な様式（こだわり、常同行動、感覚の過敏さや鈍さを含む）を特徴とし、症状は発達の早期から存在する。支援では、本人の特性を理解し、見通しをもてるよう環境を構造化すること、二次障害を防ぐこと、家族や学校との連携が重要となる。","k":["スペクトラム/連続体","社会的コミュニケーション","反復","感覚","構造化","二次障害"],"p":"「障害」を本人の欠陥としてだけでなく、環境との相互作用で生じる困難として捉える視点（社会モデル、ニューロダイバーシティ）にもふれられるとよい。"},{"id":"adhd","t":"注意欠如・多動症（ADHD）","en":"attention-deficit/hyperactivity disorder","f":"iryo","s":"不注意と、多動性・衝動性を特徴とする神経発達症。DSM-5では、症状の一部が12歳以前から存在し、2つ以上の場面でみられることが要件とされる。","a":"不注意（集中が続かない、忘れ物や紛失が多い、段取りが苦手など）と、多動性・衝動性（じっとしていられない、順番を待てない、思いつきで行動するなど）を特徴とする神経発達症。DSM-5では、いくつかの症状が12歳になる前から存在し、家庭と学校など2つ以上の場面でみられることが要件とされる。成人期まで続くことも多い。支援には、環境調整、ペアレント・トレーニング、本人の自己理解の支援、薬物療法などがあり、叱責の繰り返しによる自己評価の低下を防ぐことが大切である。","k":["不注意","多動性","衝動性","12歳","2つ以上","ペアレント・トレーニング"],"p":"二次障害（自己評価の低下、反抗、抑うつ）の予防の観点を必ず入れる。"},{"id":"anorexia","t":"神経性やせ症","en":"anorexia nervosa","f":"iryo","s":"食事を制限して有意な低体重にいたり、体重増加や肥満への強い恐怖、ボディイメージの障害を伴う摂食障害。思春期・青年期の女性に多く、身体的な危険を伴うため医療との連携が不可欠である。","a":"必要量に比べて食事を制限し、年齢や身長に比べて有意に低い体重にいたる摂食障害。体重が増えることや肥満への強い恐怖、体重や体型についての認識の歪み（ボディイメージの障害）、低体重の深刻さを認めないことを特徴とし、摂食制限型と過食・排出型がある。思春期から青年期の女性に多く、精神疾患の中でも死亡率が高い。身体管理を含む医療との連携が不可欠で、家族を治療の資源とする家族療法（モーズレイ・モデル）や認知行動療法が用いられる。","k":["低い体重","肥満","ボディイメージ","死亡率","医療","家族療法"],"p":"心理療法だけで抱えず、身体の危険（低体重・電解質異常）に応じて医療と連携することが最優先である点を書く。"},{"id":"ocd","t":"強迫症","en":"obsessive-compulsive disorder","f":"iryo","s":"不合理だとわかっていても繰り返し浮かぶ考え（強迫観念）と、それによる不安を打ち消すための行為（強迫行為）を特徴とする障害。曝露反応妨害法とSSRIの効果が示されている。","a":"自分では不合理だとわかっていても繰り返し浮かんでくる考えやイメージ（強迫観念）と、それによる不安を打ち消すために、行わずにはいられない行為（強迫行為）を特徴とする。不潔恐怖と洗浄、確認行為、加害恐怖などが代表的である。強迫行為は一時的に不安を下げるが、それによって強迫観念が維持される。治療では、不安を引き起こす刺激にあえて向き合い、強迫行為をしないで不安が自然に下がるのを体験する曝露反応妨害法と、SSRIによる薬物療法の効果が示されている。","k":["強迫観念","強迫行為","不安","確認","曝露反応妨害法","SSRI"],"p":"家族が確認や保証に巻き込まれる（巻き込み）ことが症状を維持する点も、家族支援の論点として使える。"},{"id":"psychosomatic","t":"心身症とアレキシサイミア","en":"psychosomatic disease / alexithymia","f":"iryo","s":"心身症は、身体疾患のうち発症や経過に心理社会的因子が密接に関与し、器質的・機能的障害が認められる病態。アレキシサイミアは、自分の感情に気づき言葉で表すことが難しい特徴をいう。","a":"日本心身医学会（1991年）は心身症を、身体疾患の中で、その発症や経過に心理社会的な因子が密接に関与し、器質的ないし機能的な障害が認められる病態と定義し、神経症やうつ病などに伴う身体症状は除くとした。胃・十二指腸潰瘍、気管支喘息、過敏性腸症候群などがある。シフネオス（Sifneos, P. E.）は心身症の患者に、自分の感情に気づいて言葉で表すことが難しいという特徴を見いだし、アレキシサイミア（失感情症）と名づけた。","k":["日本心身医学会","身体疾患","心理社会的","器質的","シフネオス/Sifneos","感情"],"p":"「心身症＝気のせい」ではなく身体疾患そのものである点を正確に。感情を言葉にしにくい人への面接の工夫（身体感覚から入る）も論点になる。"},{"id":"dementia","t":"認知症","en":"dementia","f":"iryo","s":"いったん発達した認知機能が脳の疾患などによって持続的に低下し、日常生活に支障をきたした状態。アルツハイマー型、血管性、レビー小体型、前頭側頭型などがあり、BPSDを伴うことが多い。","a":"いったん正常に発達した認知機能が、脳の病気などによって持続的に低下し、日常生活や社会生活に支障をきたした状態をいう。原因疾患として、アルツハイマー型（記憶障害から始まることが多い）、血管性（まだらな症状、段階的な悪化）、レビー小体型（幻視、パーキンソン症状、認知の変動）、前頭側頭型（人格の変化、脱抑制、常同行動）などがある。記憶障害などの中核症状に加え、不安、抑うつ、徘徊、妄想などの行動・心理症状（BPSD）が生じ、本人と家族の負担となる。","k":["認知機能","アルツハイマー","血管性","レビー小体","前頭側頭","BPSD/行動・心理症状"],"p":"BPSDを「問題行動」と呼ばず、本人なりの意味や不安の表れとして理解する視点（パーソン・センタード・ケア）を添える。"},{"id":"mci","t":"軽度認知障害（MCI）","en":"mild cognitive impairment","f":"iryo","s":"本人や家族から認知機能低下の訴えがあり、検査でも年齢に比べて低下が認められるが、日常生活はおおむね自立しており、認知症とは診断されない状態。一部が認知症へ移行する。","a":"本人や家族から認知機能の低下の訴えがあり、検査でも年齢に比べて記憶などの低下が認められるが、日常生活はおおむね自立しており、認知症とは診断されない状態をいう。認知症の前段階として注目され、一部は年を経て認知症に移行するが、正常な状態に戻る人や、変化しない人もいる。早期に気づくことで、運動や社会参加などの生活習慣の見直し、治療可能な原因の検索、本人の意思を尊重した将来の準備につなげることができる。","k":["認知機能","日常生活","自立","認知症","移行","戻る"],"p":"「必ず認知症になる」と書かないこと。告知や心理的な支援（不安への対応）も論点になる。"},{"id":"delirium","t":"せん妄","en":"delirium","f":"iryo","s":"身体疾患や薬物などを原因として急激に生じる、注意の障害を中心とした意識障害。症状が日内で変動し、夜間に悪化しやすい。高齢の入院患者や術後に多い。","a":"身体疾患や薬物、手術、脱水などを原因として急に生じる、注意の障害を中心とした意識障害。見当識障害、幻覚、興奮、睡眠と覚醒のリズムの乱れなどを伴い、症状が一日の中で変動し、夕方から夜間に悪化しやすい。活動が低下する低活動型は見逃されやすい。高齢者の入院や手術後に多く、認知症との鑑別や合併に注意が必要である。原因となる身体の状態の治療が基本であり、環境調整や家族の付き添いなどの非薬物的な対応が重要である。","k":["身体疾患","急","注意","意識障害","変動","低活動型"],"p":"認知症との違い（急性発症・変動・意識障害）を表で整理しておくと、比較問題にも対応できる。"},{"id":"pcc","t":"パーソン・センタード・ケア","en":"person-centred care","f":"iryo","s":"キットウッドが提唱した認知症ケアの考え方。認知症の人を一人の人として尊重し、その人の視点に立ってケアを行うことで、その人らしさ（パーソンフッド）を支える。","a":"キットウッド（Kitwood, T.）が提唱した認知症ケアの考え方で、認知症の人を、病気の症状の集まりとしてではなく一人の「人」として尊重し、その人の視点に立ってケアを行うことをいう。認知症の人の状態は、脳の障害だけでなく、性格、生活歴、健康状態、そして周囲との関わり（社会心理）の影響を受けると考える。周囲の不適切な関わりが本人の「その人らしさ（パーソンフッド）」を損なうことを指摘し、観察にもとづく評価法である認知症ケアマッピングも開発された。","k":["キットウッド/Kitwood","人","視点","生活歴","その人らしさ/パーソンフッド","認知症ケアマッピング"],"p":"ロジャーズのパーソン・センタードとの理念的なつながりにふれると、臨床心理学の知が他領域に広がった例として書ける。"},{"id":"reminiscence","t":"回想法","en":"reminiscence therapy","f":"iryo","s":"高齢者が過去の出来事や人生を振り返って語ることを、聴き手が受容的に聴くことで、心理的安定や自己の統合を支える方法。バトラーのライフレビューの考えにもとづく。","a":"高齢者が過去の出来事や人生を振り返って語ることを、聴き手が受容的・共感的に聴くことで、心理的な安定や自己の肯定をはかる方法。精神科医のバトラー（Butler, R. N.）は1963年に、高齢者の回想を、人生を振り返り統合しようとする自然で意味のある過程（ライフレビュー）として積極的に評価した。一般的な回想法は、懐かしい写真や道具などを手がかりに個人やグループで行われ、認知症の人の意欲やコミュニケーションの促進、介護者との関係づくりにも用いられる。","k":["高齢者","過去","バトラー/Butler","1963","ライフレビュー","認知症"],"p":"エリクソンの「統合 対 絶望」と結びつけると発達理論との接続が示せる。つらい記憶が想起される可能性への配慮も添える。"},{"id":"preparation","t":"プレパレーション","en":"preparation","f":"iryo","s":"検査や処置、手術などを受ける子どもに、発達段階に応じた方法で事前に説明し、心の準備を支える関わり。人形や絵本などを用い、子どもの主体性と対処を促す。","a":"病気の子どもが、検査や処置、手術、入院などによって受ける心理的な混乱を最小限にし、その子なりに乗り越えていけるよう、発達段階に応じた方法で事前に説明し、心の準備を支える関わり。人形や絵本、実際の医療器具などを用いて、何が起こるのか、どんな感覚がするのか、どうすればよいのかを伝える。処置中に気をそらす工夫（ディストラクション）や、処置後に遊びを通して体験を表現できるよう支えることも含む。子どもの権利と主体性を尊重する考えにもとづく。","k":["子ども","処置","発達段階","人形/絵本","ディストラクション","権利"],"p":"「だまして連れて行く」ことが不信と恐怖を強めること、うそをつかない説明の大切さを書く。"},{"id":"palliative","t":"緩和ケアとトータルペイン","en":"palliative care / total pain","f":"iryo","s":"生命を脅かす病に直面する患者と家族のQOLを、身体的・心理社会的・スピリチュアルな苦痛の早期の評価と対応によって改善するアプローチ。ソンダースは苦痛をトータルペインととらえた。","a":"緩和ケアとは、生命を脅かす病に関連する問題に直面している患者と家族のQOLを、痛みやその他の身体的、心理社会的、スピリチュアルな問題の早期の評価と対応によって改善するアプローチである（WHO、2002年）。ホスピス運動を始めたソンダース（Saunders, C.）は、終末期の患者の苦痛を、身体的、精神的、社会的、スピリチュアルな苦痛が相互に関連する全人的な苦痛（トータルペイン）としてとらえた。心理職は患者と家族の心理的な支援や、医療者の支援を担う。","k":["QOL","WHO","家族","ソンダース/Saunders","トータルペイン/全人的","スピリチュアル"],"p":"緩和ケアは「終末期だけ」ではなく診断時から行われる点（早期からの緩和ケア）を正確に書く。"},{"id":"kubler-ross","t":"死の受容過程","en":"stages of dying","f":"iryo","s":"キューブラー＝ロスが『死ぬ瞬間』で示した、死にゆく患者の心理過程。否認、怒り、取引、抑うつ、受容の5段階からなるが、必ずしも順序どおりに進むわけではない。","a":"キューブラー＝ロス（Kübler-Ross, E.）が、約200人の死にゆく患者への面接をもとに『死ぬ瞬間』（1969年）で示した心理的な過程。①否認と孤立、②怒り、③取引、④抑うつ、⑤受容の5段階からなり、この過程を通じて希望が保たれるとされた。ただし、すべての人がこの順序をたどるわけではなく、段階が行きつ戻りつしたり、重なったりすることも多い。段階を当てはめて患者を評価するのではなく、その人なりの過程に寄り添うための視点として用いるべきである。","k":["キューブラー","否認","怒り","取引","受容","順序"],"p":"段階論の限界（順序の固定化、受容を目標として押しつけない）にふれると評価が上がる。"},{"id":"ee","t":"感情表出（EE）","en":"expressed emotion","f":"iryo","s":"家族が患者に向ける感情の表出の質と量。批判的コメント、敵意、情緒的巻き込まれすぎが多い高EEの家族と暮らす統合失調症の患者は再発率が高いことが示された。","a":"家族が患者に対して表す感情の質と量をいい、ブラウン（Brown, G. W.）やレフ（Leff, J.）らの研究によって、統合失調症の再発との関連が明らかにされた。批判的なコメント、敵意、情緒的な巻き込まれすぎ（過度の心配や自己犠牲）が多い高EEの家族と暮らす患者は、低EEの家族と暮らす患者よりも再発率が高い。高EEは家族の病理ではなく、病気についての情報不足や介護の負担の大きさを反映したものと考えられ、家族心理教育によって家族を支えることが再発予防に有効とされる。","k":["家族","統合失調症","再発","批判","巻き込まれ","家族心理教育"],"p":"「家族が悪い」という家族病因論にしないことが最重要。家族も支援の対象であることを明確に。"},{"id":"liaison","t":"コンサルテーション・リエゾン","en":"consultation-liaison","f":"iryo","s":"総合病院で、身体疾患の患者の精神的問題について他科からの依頼に応じて助言・支援を行うのがコンサルテーション、病棟のチームに日常的に加わって連携し予防的に関わるのがリエゾンである。","a":"総合病院などで、身体疾患の治療を受けている患者の精神的な問題について、精神科医や心理職が他科からの依頼に応じて助言や支援を行うこと（コンサルテーション）、さらに日常的に病棟のチームに加わって連携し、問題の予防や早期発見をはかること（リエゾン）をいう。せん妄、抑うつ、不安、治療への不適応などが対象となる。患者だけでなく、家族や医療スタッフを支援することも重要な役割であり、多職種によるチーム医療の一員として働く力が求められる。","k":["総合病院","他科","依頼","連携","せん妄","チーム医療"],"p":"心理職が病院で「面接室の外」で働く姿を具体的に描けると、医療領域の事例問題に強くなる。"},{"id":"pediatric","t":"小児医療における心理支援","en":"psychological care in pediatrics","f":"iryo","s":"病気の子どもとその家族に対し、医療の場で行う心理的支援。発達段階に応じた病気の理解と表現の支援、プレパレーション、家族やきょうだいへの支援、医療チームとの連携などを含む。","a":"病気の子どもとその家族を対象に、医療の場で行う心理的な支援。入院や治療に伴う不安や苦痛、学業や友人関係からの切り離され、発達の停滞、きょうだいへの影響など、子どもと家族は多くの困難に直面する。心理職は、子どもの発達段階に応じた病気の理解と表現を支え、遊びやプレパレーションを通じて、子どもが主体的に治療に向き合えるよう援助する。慢性疾患では長期的な成長に寄り添い、親の心理的な負担への支援や医療チームとの連携も欠かせない。","k":["子ども","家族","きょうだい","発達段階","遊び","連携"],"p":"「きょうだい」への支援は見落とされやすい論点。復学支援や移行期医療（小児科から成人診療科へ）にもふれられると広がりが出る。"},{"id":"assessment","t":"心理アセスメント","en":"psychological assessment","f":"assess","s":"面接、行動観察、心理検査などを通じて、クライエントの問題や状態、資源、環境を多面的に評価し、支援の方針を立てる過程。仮説の生成と修正を繰り返す継続的な営みである。","a":"クライエントの問題や状態を理解し、支援の方針を立てるために、面接、行動観察、心理検査などを用いて情報を集め、総合的に評価する過程をいう。問題点や症状だけでなく、本人の強みや資源、生活環境、問題が生じ維持されている仕組みを含めて理解することが重要である。アセスメントは支援の最初に一度だけ行うものではなく、関わりの中で仮説を立てては修正していく継続的な過程であり、その結果は本人や関係者と共有され、支援に活かされる必要がある。","k":["面接","行動観察","心理検査","強み/資源","仮説","共有"],"p":"「診断（ラベルを貼る）」との違い、「見立て」という日本の臨床の言葉との関係を論じられるようにしておく。"},{"id":"rorschach","t":"ロールシャッハ・テスト","en":"Rorschach test","f":"assess","s":"ロールシャッハ（1921）が発表した投映法。左右対称のインクのしみの10枚の図版に対する反応を、領域、決定因、形態水準、内容などから分析し、パーソナリティを理解する。","a":"スイスの精神科医ロールシャッハ（Rorschach, H.）が1921年に『精神診断学』で発表した投映法の心理検査。左右対称のインクのしみからなる10枚の図版を見せて、それが何に見えるかを尋ね、その後、図版のどこに、どのような特徴から見えたのかを確認する。反応の領域、決定因（形、色彩、運動など）、形態水準、内容などを記号化して分析する。日本では片口法や包括システム（エクスナー）、近年はR-PASなどが用いられる。","k":["ロールシャッハ/Rorschach","1921","インク","10枚","決定因","包括システム/エクスナー"],"p":"「何を見たか（内容）」より「どう見たか（領域・決定因・形態水準）」を分析する検査である点が核心。"},{"id":"projective","t":"投映法","en":"projective techniques","f":"assess","s":"あいまいで多義的な刺激に対する自由な反応の中に、パーソナリティや無意識的な側面が投影されると考える心理検査の総称。ロールシャッハ・テスト、TAT、描画法などがある。","a":"あいまいで多義的な刺激や、自由度の高い課題を与え、それに対する反応の中に、その人のパーソナリティや無意識的な側面が映し出される（投映される）と考える心理検査の総称。ロールシャッハ・テスト、TAT、P-Fスタディ、SCT、描画法などがある。回答の意図が読み取られにくく、意識的な操作を受けにくい点、言葉にならない内面をとらえうる点が長所とされる。一方、実施と解釈に熟練を要し、信頼性や妥当性の検証が難しいという限界がある。","k":["あいまい/多義的","パーソナリティ","無意識","ロールシャッハ","熟練","信頼性"],"p":"質問紙法との比較は頻出。被検者の負担や侵襲性（深い層を揺さぶること）への配慮も書けると臨床的。"},{"id":"tat","t":"主題統覚検査（TAT）","en":"Thematic Apperception Test","f":"assess","s":"マレーとモーガンが考案した投映法。人物が描かれた多義的な絵を見て物語を作ってもらい、主人公の欲求と環境からの圧力などを分析して、対人関係や葛藤を理解する。","a":"マレー（Murray, H. A.）とモーガン（Morgan, C. D.）が1935年に発表した投映法。人物が登場する多義的な場面の絵を見せて、その場面に至るまでのいきさつ、今起きていること、登場人物の気持ち、この先どうなるかを含む物語を作ってもらう。マレーの欲求－圧力理論にもとづき、主人公の欲求と環境からの圧力などを分析し、対人関係のあり方や葛藤を理解する。子ども用に、動物を主人公とした図版のCATもある。","k":["マレー/Murray","1935","物語","欲求","圧力","CAT"],"p":"ロールシャッハ（知覚・認知の構造）とTAT（対人関係の内容・物語）の違いを押さえるとテスト・バッテリーの説明に使える。"},{"id":"lmt","t":"風景構成法","en":"Landscape Montage Technique","f":"assess","s":"中井久夫が考案した描画法。枠づけした画用紙に、川・山・田・道・家・木・人・花・動物・石の10項目を順に描いてもらい、付加と彩色をして一つの風景に構成させる。","a":"中井久夫が1969年に考案した描画法。治療者がサインペンで画用紙に枠を描いて手渡し（枠づけ）、川、山、田、道、家、木、人、花、動物、石の10項目を順に一つずつ告げて描いてもらい、最後に足りないと思うものを付け加えて彩色し、一つの風景として完成させる。もとは統合失調症の患者に箱庭療法を適用できるかを探る目的で考案された。構成の仕方や項目の描き方から心の状態をとらえるとともに、治療的な交流の手段ともなる。","k":["中井久夫","1969","枠","川","10項目","統合失調症"],"p":"「枠づけ」が表現を守る（保護と制約）意味をもつ点、検査であり治療でもある二重性を書けると深い。"},{"id":"baum","t":"バウムテスト","en":"Baum test","f":"assess","s":"コッホが体系化した描画法。「実のなる木」を1本描いてもらい、木の全体的印象、形態、用紙上の位置、描線の特徴などからパーソナリティや心の状態を理解する。","a":"スイスのコッホ（Koch, K.）が1949年に体系化した描画法で、「実のなる木を1本描いてください」などと教示し、鉛筆でA4判の画用紙に木を描いてもらう。描かれた木の全体的な印象、用紙上の位置や大きさ、幹や枝、樹冠、根などの形態、筆圧や描線の特徴などから、その人のパーソナリティや心の状態、発達の水準などを理解する。実施が簡便で、子どもから高齢者まで幅広く用いられる。単一の特徴だけで判断せず、全体の印象から理解することが重要とされる。","k":["コッホ/Koch","1949","実のなる木","幹","全体","簡便"],"p":"「指標を機械的に当てはめない」という注意は、描画法全般の論述で使える。"},{"id":"pf","t":"P-Fスタディ","en":"Picture-Frustration Study","f":"assess","s":"ローゼンツヴァイクが考案した投映法。欲求不満場面の絵に対する応答を、攻撃の方向（他責・自責・無責）と型（障害優位・自我防衛・要求固執）によって分類し、欲求不満への反応様式を明らかにする。","a":"ローゼンツヴァイク（Rosenzweig, S.）が考案した投映法で、日常的な欲求不満の場面が描かれた24の絵を見せ、話しかけられている人物の吹き出しにどう答えるかを記入してもらう。反応を、攻撃の方向（他責・自責・無責）と型（障害優位、自我防衛、要求固執）の組み合わせで分類し、欲求不満への反応の仕方を明らかにする。集団の一般的な反応との一致度を示すGCR（集団一致度）も求める。実施が容易で、児童用・青年用・成人用がある。","k":["ローゼンツヴァイク/Rosenzweig","欲求不満","24","他責","自責","GCR/集団一致度"],"p":"「攻撃（アグレッション）」を広い意味（自己主張を含む）で用いている点に注意。"},{"id":"sct","t":"文章完成法（SCT）","en":"Sentence Completion Test","f":"assess","s":"「子どもの頃、私は」などの書き出しに続けて自由に文章を完成させる投映法。家族、対人関係、自己像などパーソナリティの幅広い側面をとらえ、比較的意識に近い水準を反映する。","a":"「子どもの頃、私は」「私の父は」のような書き出しの短い刺激文に続けて、思いつくことを自由に書いて文章を完成させてもらう投映法。家族、対人関係、自己像、将来の希望など、パーソナリティの幅広い側面を把握できる。刺激が言語的で意味が明確なため、他の投映法に比べると投映の水準は意識に近く、本人の意図による操作も受けやすい。一方で、実施が簡便で集団でも行え、記述そのものが面接の手がかりとなるため、テスト・バッテリーに組み込まれることが多い。","k":["刺激文","書き","自己像","意識","簡便","テスト・バッテリー"],"p":"投映法の中で「意識に近い水準」を測るという位置づけを、ロールシャッハとの対比で書けるように。"},{"id":"mmpi","t":"MMPI（ミネソタ多面人格目録）","en":"Minnesota Multiphasic Personality Inventory","f":"assess","s":"ハサウェイとマッキンリーが作成した質問紙法の人格検査。経験的に選ばれた多数の項目からなり、10の臨床尺度と受検態度を検討する妥当性尺度をもつ。","a":"ハサウェイ（Hathaway, S. R.）とマッキンリー（McKinley, J. C.）が1943年に作成した、多数の項目からなる質問紙法の人格検査。精神医学的な診断群と健常群をよく判別する項目を経験的に選ぶ方法（経験的基準設定法）で作られた。心気症、抑うつ、ヒステリー、統合失調症などの10の臨床尺度に加え、受検態度の偏りを検討する妥当性尺度（疑問、虚構、頻度、修正）をもつ点に特徴がある。改訂版としてMMPI-2などがある。","k":["ハサウェイ","1943","質問紙","経験的","臨床尺度","妥当性尺度"],"p":"質問紙法の弱点（反応の歪み）を妥当性尺度で補おうとした工夫として説明すると、質問紙法一般の論述にも使える。"},{"id":"wechsler","t":"ウェクスラー式知能検査","en":"Wechsler intelligence scales","f":"assess","s":"ウェクスラーが開発した個別式知能検査（WAIS、WISC、WPPSI）。同年齢集団内の位置を示す偏差IQを用い、全検査IQと指標得点のばらつきから認知の特性を理解できる。","a":"ウェクスラー（Wechsler, D.）が開発した個別式の知能検査で、成人用のWAIS、児童用のWISC、幼児用のWPPSIがある。同年齢集団の中での相対的な位置を示す偏差IQを用いる点に特徴がある。WAIS-IVでは、全検査IQに加え、言語理解、知覚推理、ワーキングメモリー、処理速度の4つの指標得点が算出される。指標間や下位検査間のばらつき（個人内差）から認知の特性を理解でき、発達障害のある人などの支援計画に活かされる。","k":["ウェクスラー/Wechsler","WAIS","WISC","偏差IQ","指標","個人内差"],"p":"数値の高低だけでなく、検査中の取り組み方（行動観察）や生活上の困りごととつなげて解釈することが重要。"},{"id":"binet","t":"田中ビネー知能検査","en":"Tanaka-Binet Intelligence Scale","f":"assess","s":"ビネーとシモンの検査を源流とし、田中寛一が日本で標準化した個別式知能検査。2〜13歳では精神年齢から比率IQを、14歳以上では偏差IQを算出する。","a":"ビネー（Binet, A.）とシモンが1905年に開発した知能検査を源流とし、日本では田中寛一が標準化した個別式の知能検査で、現行版は田中ビネー知能検査Ⅴである。年齢ごとに配列された問題を用い、2歳から13歳までは精神年齢を求め、それを生活年齢で割って100をかけた比率IQを算出する。14歳以上では偏差IQを用い、領域別の評価も行う。全般的な知的水準を把握しやすく、幼児や知的障害のある人の評価に用いられることが多い。","k":["ビネー/Binet","1905","精神年齢","生活年齢","比率IQ","偏差IQ"],"p":"ウェクスラー式（個人内差・プロフィール）との使い分けを説明できるようにしておく。"},{"id":"battery","t":"テスト・バッテリー","en":"test battery","f":"assess","s":"クライエントを多面的に理解するために、目的に応じて複数の心理検査を組み合わせて実施すること。意識水準の異なる質問紙法と投映法などを組み合わせ、相互に補い合う情報を得る。","a":"クライエントを多面的に理解するため、目的に応じて複数の心理検査を組み合わせて実施することをいう。一つの検査でとらえられるのは心の一側面にすぎないため、知能検査と人格検査、意識的な水準をとらえる質問紙法とより深い水準をとらえる投映法などを組み合わせて、相互に補い合う情報を得る。一方で、検査が多すぎるとクライエントの負担が増すため、アセスメントの目的を明確にし、必要最小限の検査を選ぶことが求められる。","k":["複数","多面","質問紙法","投映法","負担","目的"],"p":"「意識水準の異なる検査を組み合わせる」という説明が定番。具体的な組み合わせ例を一つ挙げられると説得力が増す。"},{"id":"bps","t":"生物－心理－社会モデル","en":"biopsychosocial model","f":"assess","s":"エンゲル（1977）が、生物医学モデルを批判して提唱した枠組み。健康や病気を、生物学的・心理的・社会的要因の相互作用からとらえる。多職種協働の共通の基盤ともなる。","a":"精神科医エンゲル（Engel, G. L.）が1977年に、病気を身体の生物学的な異常だけで説明する生物医学モデルを批判して提唱した枠組み。健康や病気を、生物学的要因（遺伝、身体疾患、脳の機能など）、心理的要因（認知、感情、ストレス対処など）、社会的要因（家族、職場、経済状況、文化など）の相互作用からとらえる。心理職がアセスメントを行い、医師、看護師、ソーシャルワーカーなどの多職種と協働するための共通の枠組みとしても重要である。","k":["エンゲル/Engel","1977","生物医学モデル","相互作用","社会的","多職種"],"p":"事例問題の見立てを3つの観点で整理する「型」として使える。"},{"id":"formulation","t":"ケース・フォーミュレーション","en":"case formulation","f":"assess","s":"アセスメントの情報をもとに、問題がどのように生じ、なぜ維持されているかについての仮説を立て、介入の方針を導くこと。クライエントと共有され、経過に応じて修正される。","a":"アセスメントで得られた情報をもとに、クライエントの問題がどのように生じ、なぜ維持されているのかについての仮説を立て、それにもとづいて介入の方針を導く作業をいう。認知行動療法では、きっかけ、認知、感情、行動、身体反応の悪循環として問題を整理することが多く、精神分析的心理療法では、中核的な葛藤や対象関係のパターンとして理解する。フォーミュレーションはクライエントと共有され、介入の結果に応じて修正される仮説である。","k":["仮説","維持","介入","悪循環","共有","修正"],"p":"「なぜ今、この問題が、この形で起きているのか」に答えるもの、と一文で言えると論述の導入に便利。"},{"id":"k-shiki","t":"新版K式発達検査","en":"Kyoto Scale of Psychological Development","f":"assess","s":"京都で開発された個別式の発達検査。0歳から成人までを対象に、「姿勢・運動」「認知・適応」「言語・社会」の3領域の発達を、遊びのような関わりの中で評価し、発達指数を算出する。","a":"京都市児童院（現在の京都市児童福祉センター）で開発された個別式の発達検査で、現行版は新版K式発達検査2020である。0歳から成人までを対象とし、「姿勢・運動」「認知・適応」「言語・社会」の3領域について、検査者が子どもと遊びのように関わりながら、どの課題ができ、どこでつまずくかを観察する。発達年齢と発達指数（DQ）が算出されるが、数値だけでなく、課題への取り組み方などの質的な特徴をとらえることが重視される。","k":["京都","姿勢・運動","認知・適応","言語・社会","発達指数/DQ","質的"],"p":"乳幼児健診後の発達相談などの事例問題で、検査を「子どもの理解と保護者への助言」につなげる流れを書けるように。"},{"id":"screening","t":"認知症のスクリーニング検査","en":"HDS-R / MMSE","f":"assess","s":"認知症の疑いを簡便にとらえるための検査。改訂長谷川式簡易知能評価スケール（HDS-R、20点以下で疑い）やMMSE（23点以下が目安）があり、診断ではなくスクリーニングとして用いる。","a":"認知症の疑いをとらえるために用いられる簡便な検査。改訂長谷川式簡易知能評価スケール（HDS-R）は長谷川和夫が作成し、年齢、日時の見当識、場所、3つの言葉の記銘と遅延再生、計算、数字の逆唱、物品の記銘、言語の流暢性の9問からなり、30点満点中20点以下で認知症が疑われる。MMSEはフォルスタインらが作成し、図形の模写や文の書字などの動作性の課題を含み、30点満点で23点以下が目安とされる。いずれも診断ではなくスクリーニングである。","k":["長谷川和夫","見当識","20点","MMSE","23点","スクリーニング"],"p":"実施時の配慮（自尊心を傷つけない導入、検査の目的の説明）にもふれると臨床的。"},{"id":"feedback","t":"検査結果のフィードバック","en":"feedback of test results","f":"assess","s":"心理検査の結果を、本人や関係者が理解し生活や支援に活かせる言葉で伝えること。結果の限界や本人の強みにも触れる。フィンの治療的アセスメントでは結果を協働的に話し合う。","a":"心理検査の結果を、本人や関係者に伝えることをいう。専門用語や数値をそのまま伝えるのではなく、相手が理解でき、生活や支援に活かせる言葉で伝えることが大切である。結果の限界も伝え、レッテル貼りにならないよう、強みや資源にもふれる。フィン（Finn, S. E.）の治療的アセスメントでは、クライエント自身の問いを出発点として検査を行い、結果を協働的に話し合うことで、アセスメントそのものを治療的な体験にすることがめざされる。","k":["本人","理解","限界","強み","フィン/Finn","治療的アセスメント"],"p":"「誰に、何のために、どこまで伝えるか」（本人・保護者・学校・医師）を整理して書くと事例問題に強い。"},{"id":"interview-struct","t":"構造化面接と非構造化面接","en":"structured / unstructured interview","f":"assess","s":"構造化面接は質問の内容や順序があらかじめ決められた面接で信頼性が高く、非構造化面接は流れに沿って自由に進める面接で個別の体験を深く理解できる。両者の中間が半構造化面接である。","a":"構造化面接は、質問の内容や順序、評価の基準があらかじめ決められている面接で、DSMにもとづく診断のためのSCIDなどがある。面接者による違いが少なく信頼性が高いため、研究や診断に適する。非構造化面接は、質問を固定せず、相手の話の流れに沿って自由に進める面接で、その人に固有の体験や意味を深く理解できるが、面接者の技量に左右されやすい。両者の中間に、主な質問を決めつつ柔軟に掘り下げる半構造化面接があり、質的研究でよく用いられる。","k":["順序","SCID","信頼性","非構造化","半構造化","質的研究"],"p":"研究計画書でインタビュー調査を計画する場合、なぜ半構造化面接を選ぶのかを説明できるようにしておく。"},{"id":"attachment","t":"愛着（アタッチメント）","en":"attachment","f":"hattatsu","s":"ボウルビィが提唱した、子どもが不安なときに特定の養育者に近づき安心を得ようとする傾向と、それによって結ばれる情緒的な絆。愛着対象は安全基地と安全な避難所として機能する。","a":"ボウルビィ（Bowlby, J.）が提唱した概念で、子どもが不安や危険を感じたときに、特定の養育者に近づき、くっつくことで安心を得ようとする傾向と、それによって結ばれる情緒的な絆をいう。愛着の対象は、子どもにとって不安なときに逃げ込める「安全な避難所」であり、外の世界を探索するための「安全基地」となる。ボウルビィは、施設で育った子どもの研究や動物行動学をもとに、愛着を生存に必要な生物学的な行動システムと考えた。","k":["ボウルビィ/Bowlby","養育者","絆","安全基地","安全な避難所","動物行動学"],"p":"精神分析の「欲動（授乳による満足）」から説明する立場との違い（接触と安心そのものが一次的）を書けると理論史が示せる。"},{"id":"strange-situation","t":"ストレンジ・シチュエーション法","en":"Strange Situation Procedure","f":"hattatsu","s":"エインズワースが考案した、1歳前後の乳児の愛着の質を評価する実験観察法。養育者との分離と再会場面の行動から、回避型、安定型、アンビヴァレント型、無秩序・無方向型に分類する。","a":"エインズワース（Ainsworth, M. D. S.）が考案した、乳児（1歳前後）の愛着の質を評価する実験的な観察法。見知らぬ部屋で、養育者との分離と再会、見知らぬ人との出会いなどの場面を設定し、とくに再会の場面での乳児の行動を観察する。回避型（A型）、安定型（B型）、アンビヴァレント型（C型）に分類され、のちにメイン（Main, M.）らによって、一貫した方略をもたない無秩序・無方向型（D型）が加えられた。D型は虐待などとの関連が指摘されている。","k":["エインズワース/Ainsworth","分離","再会","回避","安定","無秩序"],"p":"「分離のときの泣き方」ではなく「再会のときのふるまい」で分類する点が要。成人愛着面接（AAI）との対応も押さえると強い。"},{"id":"iwm","t":"内的作業モデル","en":"internal working model","f":"hattatsu","s":"ボウルビィの概念で、養育者との相互作用を通じて形成される自己と他者についての心の表象。他者は応えてくれるか、自分は助けてもらう価値があるかという見通しを含み、後の対人関係に影響する。","a":"ボウルビィが提唱した概念で、子どもが養育者との繰り返しの相互作用を通じて形成する、自己と他者についての心の表象をいう。「困ったときに他者は応えてくれるか」「自分は助けてもらう価値のある存在か」という見通しを含み、その後の対人関係の予測や行動の指針として働く。比較的安定して持続し、成人期の対人関係や子育てにも影響するとされる。ただし、その後の関係の経験によって修正されうるものでもある。","k":["ボウルビィ","相互作用","自己","他者","表象","修正"],"p":"「修正されうる」ことを書くのが重要（心理療法の関係が新しい作業モデルの経験になる、という論点につながる）。"},{"id":"erikson","t":"心理社会的発達理論","en":"psychosocial development theory","f":"hattatsu","s":"エリクソンが示した、生涯を8つの段階に分け、各段階で社会との関わりの中で取り組む心理社会的危機を対の形で示した理論。基本的信頼対不信から統合対絶望までからなる。","a":"エリクソン（Erikson, E. H.）が示した、人間の生涯を8つの段階に分け、各段階で社会との関わりの中で取り組むべき心理社会的危機を対の形で示した理論。乳児期の「基本的信頼 対 不信」から始まり、青年期の「同一性 対 同一性拡散」、成人期の「生殖性（世代性） 対 停滞」、老年期の「統合 対 絶望」へと至る。危機は、肯定的な側面が否定的な側面を上回る形で乗り越えられることで、希望、忠誠、知恵などの人間的な強さが獲得されるとした。","k":["エリクソン/Erikson","8","心理社会的危機","基本的信頼","同一性","統合"],"p":"「否定的な側面もなくてはならない（比率の問題）」という点を書けると正確。フロイトの心理性的発達論との違い（社会との関わり、生涯発達）も押さえる。"},{"id":"identity","t":"アイデンティティ（自我同一性）","en":"ego identity","f":"hattatsu","s":"エリクソンが青年期の課題とした、自分は自分であるという斉一性と、過去から未来への連続性の感覚、およびそれが社会からも認められているという感覚。達成されないと同一性拡散に陥る。","a":"エリクソンが青年期の発達課題とした概念で、「自分は自分である」という斉一性と、過去から未来へと続いている連続性の感覚をもち、それが他者や社会からも認められているという感覚をいう。青年期には、社会的な責任や義務の遂行を猶予されたモラトリアムの中で、さまざまな役割を試しながら自分を模索する。これが達成されないと、自分が何者かわからない同一性拡散の状態に陥る。マーシャはこれを、危機と傾倒の有無から4つの同一性地位に分類した。","k":["エリクソン","斉一性","連続性","モラトリアム","同一性拡散","マーシャ/Marcia"],"p":"マーシャの4地位（達成・モラトリアム・早期完了・拡散）を、危機と傾倒の2軸で表にできるようにしておく。"},{"id":"piaget","t":"ピアジェの認知発達段階","en":"Piaget's stages","f":"hattatsu","s":"ピアジェが示した、同化と調節による認知発達の4段階。感覚運動期（0〜2歳）、前操作期（2〜7歳）、具体的操作期（7〜11歳）、形式的操作期（11歳以降）からなる。","a":"ピアジェ（Piaget, J.）は、子どもが外界と関わりながら、既存の認知の枠組み（シェマ）に取り込む同化と、シェマ自体を変える調節を通じて認知を発達させると考えた。発達は、感覚と運動を通じて世界を知る感覚運動期（0〜2歳）、表象や言語が発達するが自己中心性の強い前操作期（2〜7歳）、具体物について論理的に考えられる具体的操作期（7〜11歳）、抽象的・仮説的な思考が可能になる形式的操作期（11歳以降）の4段階を経る。","k":["ピアジェ/Piaget","同化","調節","感覚運動期","前操作期","形式的操作期"],"p":"ヴィゴツキー（社会的相互作用を重視）との比較が定番。子どもの年齢に応じた説明（プレパレーション）の根拠にも使える。"},{"id":"zpd","t":"発達の最近接領域","en":"zone of proximal development","f":"hattatsu","s":"ヴィゴツキーの概念で、子どもが一人で解決できる水準と、大人や仲間の援助があれば解決できる水準との間の領域。教育はこの領域に働きかけて発達を先導すべきだとした。","a":"ヴィゴツキー（Vygotsky, L. S.）が提唱した概念で、子どもが自分一人で解決できる水準と、大人や能力のある仲間の援助があれば解決できる水準との間の領域をいう。教育は、すでに完成した発達に合わせるのではなく、この領域に働きかけることで発達を先導すべきだとした。のちにブルーナーらは、援助者が必要に応じて支え、できるようになるにつれて徐々に支えを外していく関わりを「足場かけ」と呼んだ。社会的な相互作用が発達の源であるという考えにもとづく。","k":["ヴィゴツキー/Vygotsky","一人","援助","足場かけ","社会的","相互作用"],"p":"ピアジェ（個人が構成する）との対比で「社会から個人へ」という方向性を書ける。"},{"id":"tom","t":"心の理論","en":"theory of mind","f":"hattatsu","s":"他者にも自分とは異なる意図や信念などの心の状態があることを理解し、それにもとづいて行動を予測・説明する能力。誤信念課題によって調べられ、おおむね4歳ごろに通過する。","a":"他者にも自分とは異なる意図、信念、欲求などの心の状態があることを理解し、それにもとづいて他者の行動を予測したり説明したりする能力をいう。プレマック（Premack, D.）とウッドラフが、チンパンジーの研究の中で用いた言葉である。誤った信念（誤信念）を理解できるかを調べる課題（サリーとアンの課題など）を用いた研究から、定型発達の子どもでは、おおむね4歳ごろに通過できるようになることが示された。自閉スペクトラム症の理解をめぐっても研究が進められた。","k":["心の状態","プレマック/Premack","誤信念","サリー","4歳","自閉"],"p":"「自閉スペクトラム症＝心の理論の欠如」と単純化しない（言語や課題の性質の影響、近年の議論）こと。"},{"id":"mahler","t":"分離－個体化","en":"separation-individuation","f":"hattatsu","s":"マーラーが示した、乳幼児が母親との共生的な一体感から抜け出し、独立した個としての自己を確立していく過程。分化期、練習期、再接近期、個体化の確立の下位段階からなる。","a":"マーラー（Mahler, M. S.）が乳幼児の観察研究から示した、子どもが母親との心理的な一体感から抜け出し、独立した個としての自己を確立していく過程。共生期に続く分離－個体化期は、分化期、練習期、再接近期、個体化の確立と情緒的対象恒常性の始まりの4つの下位段階からなる。とくに再接近期には、離れたい気持ちと母親に頼りたい気持ちの間で揺れ動く危機（再接近期危機）が生じ、境界性パーソナリティの病理との関連が論じられた。","k":["マーラー/Mahler","一体感","共生","練習期","再接近期","対象恒常性"],"p":"青年期の「第二の分離－個体化」（ブロス）とセットで覚える。"},{"id":"temperament","t":"気質","en":"temperament","f":"hattatsu","s":"生まれつき備わり早期から現れる、刺激への反応の仕方や行動の個人差。トマスとチェスは9つの次元から子どもを類型化し、気質と環境との適合のよさが適応に影響するとした。","a":"生まれつき備わり、比較的早期から現れる、刺激への反応の仕方や行動の個人差をいう。トマス（Thomas, A.）とチェス（Chess, S.）はニューヨーク縦断研究で、活動水準、周期性、順応性などの9つの次元から、扱いやすい子、扱いにくい子、出だしの遅い子という類型を見いだした。そして、子どもの気質と、親や環境の要求や期待とが合っているか（適合のよさ）が、その後の適応に影響すると考えた。気質は、環境との相互作用の中で性格へと発達していく。","k":["生まれつき","トマス/Thomas","9つ","扱いにくい","適合のよさ","相互作用"],"p":"「親の育て方が悪い」でも「生まれつきで変わらない」でもない、相互作用の視点を書くことが要点。"},{"id":"lifespan","t":"生涯発達とSOC理論","en":"life-span development / SOC","f":"hattatsu","s":"発達を生涯にわたる獲得と喪失の過程ととらえる考え方。バルテスのSOC理論は、加齢に伴い、目標の選択、資源の最適化、喪失の補償を組み合わせて適応を保つとする。","a":"発達を、子どもが大人になるまでの成長に限らず、受精から死に至るまでの生涯にわたる獲得と喪失の過程ととらえる考え方。バルテス（Baltes, P. B.）は、加齢によって資源が限られていく中で、目標を絞り込む選択、残された資源を集中させる最適化、失われた機能を他の手段で補う補償を組み合わせることで、高齢者は適応を保つとした（補償を伴う選択的最適化：SOC理論）。カーステンセンの社会情動的選択性理論も、老年期の適応を説明する理論として知られる。","k":["生涯","喪失","バルテス/Baltes","選択","最適化","補償"],"p":"ピアニストのルービンシュタインの例（曲を絞り、練習を重ね、速さの対比を工夫する）がよく紹介される。"},{"id":"blos","t":"第二の分離－個体化","en":"second individuation","f":"hattatsu","s":"ブロスが、マーラーの分離－個体化の考えを青年期に当てはめたもの。青年が親への依存や内在化された親のイメージから心理的に離脱し、自分自身の価値観を形成していく過程をいう。","a":"ブロス（Blos, P.）が、マーラーの分離－個体化の考えを青年期に当てはめて論じたもの。青年は、児童期まで内在化していた親のイメージや、親への依存から心理的に離脱し、自分自身の価値観やアイデンティティを形成していく。その過程では、親への反抗や、理想化された仲間への傾倒、一時的な退行などがみられ、不安定さを伴う。この時期の揺れ動きは正常な発達の過程でもあり、親や周囲の大人には、離れていく子どもを見守りつつ支える関わりが求められる。","k":["ブロス/Blos","青年期","親","依存","反抗","退行"],"p":"思春期の事例（反抗、家庭内暴力、不登校）で、症状の「発達的な意味」を考える視点として使える。"},{"id":"abuse","t":"児童虐待","en":"child abuse","f":"hattatsu","s":"保護者がその監護する児童に対して行う、身体的虐待、性的虐待、ネグレクト、心理的虐待をいう（児童虐待防止法）。面前DVは心理的虐待に含まれ、発見者には通告の義務がある。","a":"保護者がその監護する児童に対して行う、身体的虐待、性的虐待、ネグレクト（養育の放棄・怠慢）、心理的虐待の4類型をいう（児童虐待防止法、2000年）。子どもの前で家族に暴力をふるう面前DVも、心理的虐待に含まれる。虐待を受けたと思われる児童を発見した者には、通告の義務がある。虐待は子どもの心身の発達に深刻な影響を与え、愛着の問題や複雑性トラウマにもつながる。支援では子どもの安全確保を最優先とし、多機関の連携による家族への支援が求められる。","k":["身体的虐待","性的虐待","ネグレクト","心理的虐待","面前DV","通告"],"p":"通告義務は守秘義務より優先される（守秘義務違反にならない）ことを、倫理の論述でも使えるようにしておく。"},{"id":"futoko","t":"不登校","en":"school non-attendance","f":"hattatsu","s":"文部科学省の定義では、何らかの心理的・情緒的・身体的・社会的要因により、登校しない、あるいはしたくてもできない状況にあるため、年間30日以上欠席した者のうち、病気や経済的理由によるものを除いたもの。","a":"文部科学省は、何らかの心理的、情緒的、身体的、あるいは社会的な要因・背景により、登校しない、あるいはしたくともできない状況にあるために、年間30日以上欠席した者のうち、病気や経済的な理由によるものを除いたものと定義している。背景は多様で、一つの原因に帰することは難しい。教育機会確保法（2016年）では、学校以外の場での多様な学びの重要性や、休養の必要性も認められた。学校への復帰だけを目標とせず、子どもの社会的な自立を支える視点が求められる。","k":["文部科学省","30日","心理的","多様","教育機会確保法","自立"],"p":"不登校を「問題行動」と見なさないという国の方針の変化（2016年以降）にふれると、知識の新しさを示せる。"},{"id":"bullying","t":"いじめ","en":"bullying","f":"hattatsu","s":"いじめ防止対策推進法では、一定の人的関係にある他の児童等が行う心理的または物理的な影響を与える行為（インターネットを含む）で、対象となった児童等が心身の苦痛を感じているものと定義される。","a":"いじめ防止対策推進法（2013年）では、児童等に対して、一定の人的関係にある他の児童等が行う心理的または物理的な影響を与える行為（インターネットを通じて行われるものを含む）であって、その対象となった児童等が心身の苦痛を感じているものと定義される。被害者の主観を重視する定義であり、学校には、いじめ防止のための組織の設置や、重大事態への対処が義務づけられた。スクールカウンセラーには、被害を受けた子どもの支援とともに、加害や傍観の背景の理解も求められる。","k":["いじめ防止対策推進法","2013","心身の苦痛","インターネット","重大事態","スクールカウンセラー"],"p":"「加害者を罰する」だけでなく、学級集団（観衆・傍観者）への働きかけの視点を入れると、コミュニティ心理学的な答案になる。"},{"id":"secondary-dd","t":"発達障害の二次障害","en":"secondary problems","f":"hattatsu","s":"発達障害のある人が、特性が理解されないまま叱責や失敗を繰り返し経験することで二次的に生じる問題。自己評価の低下、抑うつ、不登校などの内在化と、反抗や非行などの外在化がある。","a":"発達障害のある人が、特性そのものによる困難ではなく、特性が周囲に理解されないまま叱責や失敗、いじめなどを繰り返し経験することによって、二次的に生じる問題をいう。自己評価の低下、抑うつ、不安、不登校やひきこもりといった内在化の問題と、反抗、暴力、非行などの外在化の問題がある。早期に特性に気づき、環境を調整し、本人の強みを活かした成功体験を積み重ねられるよう支えることが、二次障害の予防につながる。","k":["特性","理解","自己評価","抑うつ","外在化","環境"],"p":"成人期になって初めて気づかれる発達特性と、うつ・不安などの二次的な問題という論点も押さえておく。"},{"id":"family-lc","t":"家族ライフサイクル","en":"family life cycle","f":"hattatsu","s":"家族を、結婚、子どもの誕生と養育、子どもの巣立ち、老年期と時間とともに発達するシステムとしてとらえる考え方。各段階の移行期に関係の組み直しが必要となり、ストレスが生じやすい。","a":"家族を、結婚による家族の成立、子どもの誕生と養育、子どもの思春期、子どもの巣立ち、老年期と、時間とともに発達していくシステムとしてとらえる考え方。カーター（Carter, B.）とマクゴールドリック（McGoldrick, M.）らは、各段階に家族が取り組む発達課題があり、段階の移行期には家族の関係の組み直しが必要となるため、ストレスや症状が生じやすいと考えた。個人の問題を、家族の発達の文脈の中で理解するための視点として、家族療法で用いられる。","k":["家族","段階","カーター/マクゴールドリック","発達課題","移行期","家族療法"],"p":"「なぜ今この時期に症状が出たのか」を、家族の移行期と結びつけて考える視点として事例問題に使える。"},{"id":"rad","t":"アタッチメントの障害","en":"attachment disorders","f":"hattatsu","s":"極端に不十分な養育を経験した子どもにみられる障害。苦痛時にも養育者に慰めを求めない反応性アタッチメント障害と、見知らぬ大人にためらいなく近づく脱抑制型対人交流障害がある。","a":"DSM-5では、極端に不十分な養育（ネグレクトや養育者の頻繁な交代など）を経験した子どもにみられる障害として、反応性アタッチメント障害と脱抑制型対人交流障害が示されている。前者は、苦痛なときにも養育者に慰めを求めず、感情の表出が乏しいなど、愛着行動が抑制された状態をいう。後者は、見知らぬ大人にもためらいなく近づき、ついて行こうとするなど、過度になれなれしい行動を特徴とする。安定した養育環境の確保と、養育者との関係の支援が重要である。","k":["不十分な養育/ネグレクト","反応性アタッチメント障害","脱抑制型対人交流障害","慰め","見知らぬ","養育環境"],"p":"自閉スペクトラム症との鑑別（養育歴の確認）が論点になる。社会的養護（児童養護施設・里親）の文脈とも結びつけられる。"},{"id":"classical","t":"古典的条件づけ","en":"classical conditioning","f":"kiso","s":"パヴロフが見いだした学習の過程。無条件刺激と中性刺激を対にして提示すると、中性刺激（条件刺激）だけで反応（条件反応）が生じるようになる。レスポンデント条件づけともいう。","a":"パヴロフ（Pavlov, I. P.）がイヌの唾液分泌の研究から見いだした学習の過程で、レスポンデント条件づけとも呼ばれる。もともと反応（無条件反応）を引き起こす無条件刺激（餌）と、中性刺激（メトロノームの音など）を対にして繰り返し提示すると、中性刺激だけで反応が生じるようになる。このとき中性刺激は条件刺激、生じる反応は条件反応となる。条件刺激だけを提示し続けると反応は弱まる（消去）。恐怖症の成り立ちの説明や、エクスポージャーなどの治療の基盤となった。","k":["パヴロフ/Pavlov","無条件刺激","条件刺激","条件反応","消去","恐怖症"],"p":"ワトソンの「アルバート坊やの実験」（恐怖の条件づけ）とその倫理的問題もあわせて押さえる。"},{"id":"operant","t":"オペラント条件づけ","en":"operant conditioning","f":"kiso","s":"スキナーが体系化した学習の原理で、自発的な行動がその直後の結果によって増減すること。行動を増やす結果を強化、減らす結果を罰といい、応用行動分析の基礎となる。","a":"スキナー（Skinner, B. F.）が体系化した学習の原理で、自発的な行動（オペラント）が、その直後に生じる結果によって増えたり減ったりする過程をいう。行動の後によいことが生じる、または嫌なことがなくなることで行動が増えることを強化、行動の後に嫌なことが生じる、またはよいことがなくなることで行動が減ることを罰という。行動に先立つ状況（先行事象）、行動、結果の関係を分析する応用行動分析として、教育や臨床、発達障害の支援に広く応用されている。","k":["スキナー/Skinner","自発","結果","強化","罰","応用行動分析"],"p":"「正の／負の」と「強化／罰」の4つの組み合わせを例で説明できるようにしておく（負の強化を罰と混同しない）。"},{"id":"learned-helplessness","t":"学習性無力感","en":"learned helplessness","f":"kiso","s":"セリグマンらが見いだした、統制できない不快な事態を繰り返し経験すると、回避可能な状況でも回避しようとしなくなる現象。うつ病の心理学的モデルの一つとなった。","a":"セリグマン（Seligman, M. E. P.）らが動物実験で見いだした現象で、自分の行動によっては不快な状況を避けられない（統制できない）経験を繰り返すと、その後、逃れることが可能な状況になっても、逃れようとしなくなることをいう。その後、人間については、失敗の原因を内的で、安定的で、全般的なものに帰属する傾向が無力感や抑うつにつながるという改訂理論が示され、うつ病の心理学的なモデルの一つとなった。","k":["セリグマン/Seligman","統制","逃れ","帰属","抑うつ","内的"],"p":"虐待やDVの被害者が「逃げない」ことの理解に用いられることがあるが、本人の責任に帰さない書き方を心がける。"},{"id":"modeling","t":"観察学習（モデリング）","en":"observational learning","f":"kiso","s":"バンデューラが示した、他者（モデル）の行動とその結果を観察するだけで新しい行動を学習すること。注意、保持、運動再生、動機づけの過程からなり、ボボ人形の実験が知られる。","a":"バンデューラ（Bandura, A.）が示した学習の形態で、自分が直接に経験したり強化を受けたりしなくても、他者（モデル）の行動とその結果を観察するだけで、新しい行動を学習することをいう。大人がビニール人形に攻撃的にふるまう映像を見た子どもが、同じような攻撃行動をとったボボ人形の実験が知られる。注意、保持、運動再生、動機づけの過程からなる。他者が報酬を受ける様子を見ることを代理強化という。社会的学習理論の中心的な概念である。","k":["バンデューラ/Bandura","観察","ボボ人形","代理強化","社会的学習理論","注意"],"p":"SST（社会生活スキルトレーニング）でのモデリングの活用など、臨床への応用例を一つ添える。"},{"id":"self-efficacy","t":"自己効力感","en":"self-efficacy","f":"kiso","s":"バンデューラが提唱した、ある結果を得るのに必要な行動を自分がうまく遂行できるという確信（効力期待）。その行動をすれば結果が得られるという結果期待とは区別される。","a":"バンデューラが提唱した概念で、ある結果を得るために必要な行動を、自分がうまく行うことができるという確信をいう。行動すればその結果が得られるという結果予期とは区別され、自己効力感（効力予期）が高いほど、人はその行動に取り組み、困難があっても粘り強く続けるとされる。自己効力感は、自分で達成した経験（遂行行動の達成）、他者の成功を見る代理経験、言語的説得、生理的・情動的な状態の4つの情報源によって高められる。","k":["バンデューラ/Bandura","確信","結果予期","遂行行動の達成/成功体験","代理経験","言語的説得"],"p":"「自己肯定感」「自尊感情」との違い（特定の行動についての見通し）を明確にする。"},{"id":"attribution","t":"原因帰属","en":"causal attribution","f":"social","s":"行動や出来事の原因を推論すること。ハイダーは内的帰属と外的帰属を区別した。他者の行動の原因を状況より内的特性に求めやすい傾向を基本的な帰属の誤りという。","a":"自分や他者の行動、出来事の原因を推論することをいい、ハイダー（Heider, F.）は、本人の能力や性格などの内的な要因に原因を求める場合と、状況などの外的な要因に求める場合を区別した。人は他者の行動の原因を考えるとき、状況の影響を軽視し、その人の内的な特性に原因を求めやすい傾向があり、これを基本的な帰属の誤りという。また、自分の成功は内的な要因に、失敗は外的な要因に帰属しやすい傾向（自己奉仕的バイアス）もある。","k":["原因","ハイダー/Heider","内的","外的","状況","自己奉仕的バイアス"],"p":"支援者がクライエントの行動を「性格のせい」と見なしやすい（基本的な帰属の誤り）ことへの自戒として論じることもできる。"},{"id":"dissonance","t":"認知的不協和","en":"cognitive dissonance","f":"social","s":"フェスティンガーが提唱した、互いに矛盾する認知を抱えたときに生じる不快な緊張状態。人はそれを低減するために、態度や行動を変えたり新たな認知を加えたりする。","a":"フェスティンガー（Festinger, L.）が1957年に提唱した理論で、人が自分の中に互いに矛盾する認知（考え、信念、行動についての知識など）を同時に抱えると、不快な緊張状態（不協和）が生じ、それを低減しようとして、認知や行動を変えたり、新たな認知を加えたりすることをいう。退屈な作業をした後に、わずかな報酬でその作業は面白かったと他者に伝えた人ほど、作業を面白いと評価するようになった実験が知られる。態度変容や自己正当化の理解に用いられる。","k":["フェスティンガー/Festinger","1957","矛盾","不快","低減","報酬"],"p":"動機づけ面接で、本人の価値と現在の行動との「ずれ」を広げる技法と関連づけることもできる。"},{"id":"working-memory","t":"ワーキングメモリ","en":"working memory","f":"kiso","s":"バドリーとヒッチが提唱した、情報を一時的に保持しながら処理するための記憶システム。中央実行系、音韻ループ、視空間スケッチパッド、エピソード・バッファからなる。","a":"バドリー（Baddeley, A. D.）とヒッチ（Hitch, G. J.）が1974年に提唱した、情報を一時的に保持しながら、同時にそれを操作・処理するための記憶のシステム。単に情報を貯蔵する短期記憶の概念を発展させたもので、注意を制御する中央実行系と、言語的な情報を保持する音韻ループ、視覚的・空間的な情報を保持する視空間スケッチパッド、さらに後に加えられたエピソード・バッファからなる。読み書きや計算、推論などの基盤となり、発達障害の理解にも用いられる。","k":["バドリー/Baddeley","1974","保持","中央実行系","音韻ループ","視空間スケッチパッド"],"p":"WAIS-IVのワーキングメモリー指標とつなげて、学習面の支援（指示を短く区切る等）に結びつけると臨床的。"},{"id":"memory-types","t":"長期記憶の分類","en":"types of long-term memory","f":"kiso","s":"長期記憶は、意識的に想起できる宣言的記憶（エピソード記憶と意味記憶）と、意識的想起を伴わない非宣言的記憶（手続き記憶、プライミングなど）に分けられる。","a":"長期記憶は、言葉やイメージとして意識的に想起できる宣言的記憶（顕在記憶）と、意識的な想起を伴わない非宣言的記憶（潜在記憶）に大きく分けられる。宣言的記憶はさらに、タルヴィング（Tulving, E.）によって、「いつ、どこで」という個人の経験に関するエピソード記憶と、一般的な知識である意味記憶に区別された。非宣言的記憶には、自転車の乗り方などの手続き記憶や、先行する刺激が後の処理に影響するプライミングなどが含まれる。","k":["宣言的記憶","非宣言的記憶","タルヴィング/Tulving","エピソード記憶","意味記憶","手続き記憶"],"p":"認知症ではエピソード記憶が早く障害され、手続き記憶は比較的保たれやすい、という臨床的な対応づけができると強い。"},{"id":"coping","t":"ストレス・コーピング","en":"stress coping","f":"kiso","s":"ラザルスとフォルクマンの理論で、ストレスフルな状況に対処するための認知的・行動的努力。一次的評価と二次的評価を経て行われ、問題焦点型と情動焦点型がある。","a":"ラザルス（Lazarus, R. S.）とフォルクマン（Folkman, S.）の心理学的ストレス理論では、ストレスは出来事そのものではなく、人と環境との相互作用の中で生じるとされる。出来事が自分にとって脅威かどうかを判断する一次的評価と、それに対処できるかを判断する二次的評価を経て、対処（コーピング）が行われる。問題そのものの解決をめざす問題焦点型コーピングと、それに伴う感情の調整をめざす情動焦点型コーピングがあり、状況に応じた使い分けが重要である。","k":["ラザルス/Lazarus","相互作用","一次的評価","二次的評価","問題焦点","情動焦点"],"p":"「問題焦点型がよい」と単純化しない（変えられない状況では情動焦点型が適応的）ことを書く。"},{"id":"emotion-theory","t":"情動の理論","en":"theories of emotion","f":"kiso","s":"情動の成り立ちを説明する理論。身体反応の知覚が情動になるとするジェームズ＝ランゲ説、視床を介して同時に生じるとするキャノン＝バード説、覚醒と認知的ラベルによるとする2要因説などがある。","a":"ジェームズ＝ランゲ説は、刺激によって身体の生理的な変化が生じ、その変化の知覚が情動の体験になると考えた（「泣くから悲しい」）。キャノン＝バード説はこれを批判し、刺激の情報が視床で処理され、大脳皮質での情動の体験と身体の反応が同時に生じるとした。シャクター（Schachter, S.）とシンガーの2要因説は、生理的な覚醒と、その覚醒の原因についての認知的な解釈（ラベルづけ）の両方によって情動が決まるとした。","k":["ジェームズ/ランゲ","身体","キャノン/バード","視床","シャクター/Schachter","2要因"],"p":"3説を「身体→情動」「同時」「覚醒＋認知」と一言で区別できるように。"},{"id":"sdt","t":"自己決定理論と内発的動機づけ","en":"self-determination theory","f":"kiso","s":"デシとライアンの理論で、自律性・有能感・関係性の3つの基本的心理欲求が満たされると、動機づけが内在化され健康に成長するとする。外的報酬が内発的動機づけを下げるアンダーマイニング効果も知られる。","a":"内発的動機づけとは、報酬や罰などの外からの働きかけではなく、活動そのものへの興味や楽しさによって行動が引き起こされることをいう。デシ（Deci, E. L.）は、内発的に取り組んでいる活動に外的な報酬を与えると、かえって内発的動機づけが低下するアンダーマイニング効果を示した。デシとライアンの自己決定理論は、自律性、有能感、関係性の3つの基本的な心理的欲求が満たされることで、動機づけが内在化され、人は健康に成長すると考える。","k":["内発的動機づけ","デシ/Deci","アンダーマイニング","自律性","有能感","関係性"],"p":"外発的動機づけも段階的に内在化しうる（取り入れ・同一化・統合）点まで書けると正確。"},{"id":"big5","t":"特性5因子論（ビッグファイブ）","en":"Big Five","f":"social","s":"パーソナリティを、神経症傾向、外向性、開放性、調和性、誠実性の5つの基本特性の程度で記述する特性論のモデル。語彙研究と質問紙研究の両方から支持されている。","a":"パーソナリティを少数の基本的な特性の組み合わせで記述する特性論のモデルで、多くの研究で共通して見いだされた5つの因子からなる。神経症傾向（情緒不安定性）、外向性、開放性（経験への開放性）、調和性（協調性）、誠実性（勤勉性）である。辞書から人格を表す言葉を集めて分析する語彙研究と、質問紙研究の両方から支持され、文化を越えた一貫性も示されている。性格を類型に分ける類型論に対し、程度の違いで連続的に記述する点に特徴がある。","k":["特性論","神経症傾向","外向性","開放性","調和性","誠実性"],"p":"ユングのタイプ論（類型論）との比較で問われうる。因子分析という研究法とも結びつけられる。"},{"id":"bystander","t":"傍観者効果","en":"bystander effect","f":"social","s":"緊急事態で居合わせる人が多いほど、個々人が援助行動をとりにくくなる現象。ラタネとダーリーが研究し、責任の分散、多元的無知、評価懸念によって説明される。","a":"緊急事態の場面で、その場に居合わせる人が多いほど、一人ひとりが援助行動をとりにくくなる現象をいう。ラタネ（Latané, B.）とダーリー（Darley, J. M.）が、ニューヨークで起きた殺人事件の報道をきっかけに実験的に研究した。その背景には、他の人が助けるだろうと考える責任の分散、他の人が動かないことから事態を深刻でないと判断する多元的無知、人前で失敗することへの懸念（評価懸念）がある。具体的な人を名指しして援助を求めることが有効とされる。","k":["援助","ラタネ/Latane","ダーリー","責任の分散","多元的無知","評価懸念"],"p":"いじめの「傍観者」の理解や、自殺予防のゲートキーパーの考え方につなげられる。"},{"id":"conformity","t":"同調と服従","en":"conformity / obedience","f":"social","s":"同調は集団の圧力によって個人が意見や行動を多数派に合わせることで、アッシュの実験が知られる。服従は権威者の命令に従うことで、ミルグラムの実験が知られる。","a":"同調とは、集団の圧力によって、個人が意見や行動を集団の多数派に合わせることをいう。アッシュ（Asch, S. E.）は、明らかに誤った答えを述べるサクラの多数派の中で、実験参加者の判断の誤りが増えることを示した。服従とは、権威者の命令に従うことをいい、ミルグラム（Milgram, S.）の実験では、多くの参加者が実験者の指示に従って、他者に強い電気ショックを与え続けた（と信じた）。人の行動が状況の力に大きく左右されることを示すとともに、研究倫理の議論も呼んだ。","k":["同調","アッシュ/Asch","多数派","服従","ミルグラム/Milgram","研究倫理"],"p":"研究倫理（欺瞞、参加者の苦痛、デブリーフィング）の論述の具体例としても使える。"},{"id":"social-support","t":"ソーシャル・サポート","en":"social support","f":"social","s":"周囲の人々から得られる有形・無形の支援。情緒的、道具的、情報的、評価的サポートなどに分けられ、健康への直接効果と、ストレスの悪影響を和らげる緩衝効果があるとされる。","a":"家族、友人、同僚、専門家など、人をとりまく周囲の人々から得られる有形・無形の支援をいう。気持ちを受け止める情緒的サポート、具体的な手助けや物の提供である道具的サポート、問題の解決に役立つ情報を与える情報的サポート、行動や考えを認める評価的サポートなどに分けられる。ストレスの有無にかかわらず健康によい影響を与える直接効果と、強いストレスにさらされたときにその悪影響を和らげる緩衝効果があるとされる。","k":["周囲","情緒的","道具的","情報的","直接効果","緩衝効果"],"p":"研究計画書で「援助要請」「孤独感」などを扱う場合の基礎概念。受け手が「サポートと感じるか」（知覚されたサポート）の重要性にもふれられるとよい。"},{"id":"metacognition","t":"メタ認知","en":"metacognition","f":"kiso","s":"自分の認知についての認知。フラベルが提唱し、自分や課題、方略についてのメタ認知的知識と、自分の認知をモニタリングしコントロールするメタ認知的活動からなる。","a":"フラベル（Flavell, J. H.）が提唱した概念で、自分の認知（知覚、記憶、思考など）を一段上から認知すること、すなわち「認知についての認知」をいう。自分や課題、方略についての知識であるメタ認知的知識と、自分の認知の状態をモニタリングし、必要に応じてコントロールするメタ認知的活動からなる。学習の場面では、理解の程度を自己点検し、方略を調整する力として重要である。臨床でも、思考を事実としてではなく思考として眺める力として、認知行動療法などで注目されている。","k":["フラベル/Flavell","認知についての認知","メタ認知的知識","モニタリング","コントロール","方略"],"p":"マインドフルネスやメンタライゼーションと関連づけて、「自分の心を眺める力」という共通の軸で論じることができる。"},{"id":"hpa","t":"ストレス反応とHPA軸","en":"stress response / HPA axis","f":"neuro","s":"ストレス時に、視床下部からCRH、下垂体からACTHが分泌され、副腎皮質からコルチゾールが分泌される経路（視床下部－下垂体－副腎皮質系）。セリエはストレス反応の経過を汎適応症候群として示した。","a":"ストレッサーにさらされると、視床下部から副腎皮質刺激ホルモン放出ホルモン（CRH）が分泌され、それが下垂体からの副腎皮質刺激ホルモン（ACTH）の分泌を促し、副腎皮質からコルチゾールが分泌される。この経路を視床下部－下垂体－副腎皮質系（HPA軸）という。また交感神経－副腎髄質系も働き、心拍数や血圧が上がる。セリエ（Selye, H.）は、ストレスへの非特異的な反応の経過を、警告反応期、抵抗期、疲憊期からなる汎適応症候群として示した。","k":["視床下部","下垂体","コルチゾール","交感神経","セリエ/Selye","汎適応症候群"],"p":"生物－心理－社会モデルの「生物」の側面として、慢性ストレスが心身に与える影響を説明する際に使える。"},{"id":"reliability","t":"信頼性","en":"reliability","f":"kenkyu","s":"測定が同じ対象に対して一貫した安定した結果を示す程度。再検査法、折半法、クロンバックのα係数（内的一貫性）、評定者間一致などで評価される。妥当性の必要条件である。","a":"測定が、同じ対象に対して一貫した安定した結果を示す程度をいう。同じ人に時間をおいて同じ検査を行い、得点の相関を調べる再検査法、検査項目を2つに分けて得点の相関を調べる折半法、項目間の一貫性を示すクロンバックのα係数などで評価される。評定者が複数いる場合には、評定者間の一致度も検討される。信頼性は妥当性の必要条件であり、信頼性の低い測定からは妥当な結論は得られないが、信頼性が高いからといって妥当性が保証されるわけではない。","k":["一貫","再検査法","折半法","α係数/クロンバック","評定者間","妥当性"],"p":"「信頼性は妥当性の必要条件であって十分条件ではない」は定番の締めの一文。的当ての比喩で説明してもよい。"},{"id":"validity","t":"妥当性","en":"validity","f":"kenkyu","s":"測定が、測ろうとしている概念を実際にどの程度正しくとらえているかの程度。内容的妥当性、基準関連妥当性（併存的・予測的）、構成概念妥当性（収束的・弁別的）などの観点から検討される。","a":"測定しようとしている概念を、その測定が実際にどの程度正しくとらえているかをいう。項目がその概念の内容を適切に代表しているかという内容的妥当性、外的な基準との関連による基準関連妥当性（併存的妥当性、予測的妥当性）、理論的に予測される他の変数との関係が示されるかという構成概念妥当性（関連すべき変数とは関連する収束的妥当性、関連すべきでない変数とは関連しない弁別的妥当性）がある。近年は、構成概念妥当性を中心とする統一的な見方が主流である。","k":["測定","内容的妥当性","基準関連妥当性","予測的/併存的","構成概念妥当性","収束的"],"p":"研究計画書で既存の尺度を使う場合、「信頼性・妥当性が確認された尺度を用いる」と書き、その根拠（原著論文）を示すことが求められる。"},{"id":"int-ext-validity","t":"内的妥当性と外的妥当性","en":"internal / external validity","f":"kenkyu","s":"内的妥当性は、観察された結果が独立変数の操作によるもので他の要因によらないといえる程度、外的妥当性は、結果を他の対象者や場面などへ一般化できる程度をいう。","a":"キャンベル（Campbell, D. T.）らが整理した研究の妥当性の概念。内的妥当性とは、研究で観察された結果が、本当に独立変数の操作によるものであり、他の要因によるものではないといえる程度をいう。履歴、成熟、テスト効果、統計的な平均への回帰、参加者の選択や脱落などがこれを脅かす。外的妥当性とは、研究の結果を、他の対象者、場面、時期などにどの程度一般化できるかをいう。厳密な統制は内的妥当性を高めるが、外的妥当性を損なうことがある。","k":["キャンベル/Campbell","独立変数","他の要因","平均への回帰","一般化","統制"],"p":"RCTと事例研究の長所・短所を、この2つの妥当性で整理すると論述の骨格になる。"},{"id":"rct","t":"ランダム化比較試験（RCT）","en":"randomized controlled trial","f":"kenkyu","s":"研究参加者を無作為に介入群と対照群に割り付けて結果を比較し、介入の効果を検証する研究デザイン。群間の偏りが確率的にならされるため、因果推論に適する。","a":"研究の参加者を無作為に介入群と対照群（待機群、通常治療群など）に割り付け、両群の結果を比較することで、介入の効果を検証する研究デザイン。無作為な割り付けにより、測定されていない要因も含めて群間の偏りが確率的にならされるため、因果関係の推論に適し、効果研究において最も質の高いデザインの一つとされる。一方で、厳密に選ばれた対象者や手続きのもとでの結果が、実際の臨床現場にそのまま当てはまるとは限らないという外的妥当性の問題がある。","k":["無作為/ランダム","割り付け","対照群","因果","偏り","外的妥当性"],"p":"心理療法では二重盲検が困難であること、効能（efficacy）と実地での効果（effectiveness）の区別も添えると深い。"},{"id":"meta-analysis","t":"メタ分析","en":"meta-analysis","f":"kenkyu","s":"同じテーマの複数の独立した研究結果を、効果量などの共通の指標に変換して統計的に統合し、全体としての効果の大きさや一貫性を検討する方法。出版バイアスに注意を要する。","a":"同じテーマについての複数の独立した研究の結果を、効果量などの共通の指標に変換して統計的に統合し、全体としての効果の大きさや一貫性を検討する方法。グラス（Glass, G. V.）が名づけ、スミスとグラスによる心理療法の効果のメタ分析が知られる。個々の研究の検定力の不足を補い、研究間の違いを生む要因も検討できる。一方で、有意な結果の研究ほど公表されやすいという出版バイアスや、質の異なる研究を混ぜてしまう問題に注意が必要である。","k":["複数","効果量","統合","グラス/Glass","心理療法","出版バイアス"],"p":"アイゼンクの「心理療法は効果がない」という批判（1952年）に対する応答として、メタ分析が果たした歴史的な役割を書ける。"},{"id":"effect-size","t":"効果量","en":"effect size","f":"kenkyu","s":"効果や差、関連の大きさを、標本の大きさに左右されない形で示す指標。2群の平均差を標準偏差で割ったコーエンのdなどがあり、0.2・0.5・0.8が小・中・大の目安とされる。","a":"効果や差、関連の大きさを、標本の大きさに左右されない形で示す指標。2群の平均値の差を標準偏差で割ったコーエンのd、相関係数r、分散分析での説明率η²などがある。コーエンは、dについて0.2を小、0.5を中、0.8を大の目安とした。p値は、標本が大きければ小さな差でも有意になるため、効果が実質的に意味のある大きさかを判断するには、効果量とその信頼区間を報告することが求められる。メタ分析や検定力分析の基礎ともなる。","k":["大きさ","標本","コーエン/Cohen","0.5","p値","信頼区間"],"p":"「有意＝効果が大きい」ではない、という誤解を正せるかが問われる。"},{"id":"nhst","t":"統計的仮説検定と2種類の誤り","en":"significance testing / Type I and II errors","f":"kenkyu","s":"帰無仮説が正しいと仮定したときに観測結果以上に極端な結果が得られる確率（p値）が有意水準を下回れば帰無仮説を棄却する手続き。誤って棄却するのが第1種の誤り、棄却しそこなうのが第2種の誤りである。","a":"統計的仮説検定では、差や関連がないという帰無仮説を立て、それが正しいと仮定したときに、得られたデータと同じかそれ以上に極端な結果が生じる確率（p値）を求め、それが有意水準（通常は5％）を下回れば帰無仮説を棄却する。帰無仮説が正しいのに誤って棄却する誤りを第1種の誤り（α）、帰無仮説が誤っているのに棄却しない誤りを第2種の誤り（β）という。p値は効果の大きさや、仮説が正しい確率を示すものではない点に注意が必要である。","k":["帰無仮説","p値","有意水準","第1種","第2種","棄却"],"p":"多重比較で第1種の誤りが増える問題（ボンフェローニ補正など）まで書けると一段上。"},{"id":"power","t":"検定力","en":"statistical power","f":"kenkyu","s":"帰無仮説が誤っているときにそれを正しく棄却できる確率（1−β）。効果量、標本の大きさ、有意水準によって決まり、一般に0.8以上が望ましいとされる。","a":"帰無仮説が誤っているときに、それを正しく棄却できる確率をいい、1から第2種の誤りの確率（β）を引いた値で表される。検定力は、効果量、標本の大きさ、有意水準によって決まり、一般に0.8以上が望ましいとされる。検定力の低い研究では、本当は効果があっても見逃しやすく、また有意になった結果は効果を過大に見積もっている可能性が高い。研究を計画する段階で、想定される効果量から必要な標本の大きさを求めておくこと（検定力分析）が求められる。","k":["棄却","第2種","効果量","標本","0.8","検定力分析"],"p":"研究計画書で「対象者○名」とする根拠として、検定力分析にふれられると評価が高い。"},{"id":"confounding","t":"交絡と擬似相関","en":"confounding / spurious correlation","f":"kenkyu","s":"原因と結果の両方に影響する第三の変数（交絡変数）のために、両者の関係が実際とは異なって見えること。因果関係がないのに見かけ上生じる相関を擬似相関という。","a":"交絡とは、注目している原因と結果の両方に影響する第三の変数（交絡変数）があるために、両者の関係が実際とは異なって見えることをいう。たとえば、アイスクリームの売上と水難事故の件数に相関があっても、両者は気温という第三の変数の影響を受けているにすぎず、因果関係はない。このような見かけ上の相関を擬似相関という。相関関係は因果関係を意味しないため、無作為化、統制、層別化や統計的な調整によって交絡を取り除く工夫が必要となる。","k":["第三の変数","交絡変数","擬似相関","因果","無作為化","統計的な調整"],"p":"「逆の因果」（結果が原因に影響している可能性）もあわせて書くと、相関研究の解釈の論述として完成度が上がる。"},{"id":"single-case","t":"単一事例実験デザイン","en":"single-case experimental design","f":"kenkyu","s":"一人または少数の対象者の行動を繰り返し測定し、ベースライン期と介入期の比較によって介入の効果を検証する研究デザイン。ABABデザインや多層ベースライン・デザインがある。","a":"一人または少数の対象者について、標的となる行動などを繰り返し測定し、介入の有無による変化を比べることで、介入の効果を検証する研究デザイン。介入前のベースライン期（A）と介入期（B）を設け、介入を除去して再びベースラインに戻すABAデザインやABABデザイン、複数の行動・場面・対象者で時期をずらして介入を始める多層ベースライン・デザインなどがある。個別の臨床実践と効果の検証を結びつける方法として、応用行動分析などで用いられる。","k":["繰り返し","ベースライン","ABA","多層ベースライン","個別","応用行動分析"],"p":"介入の除去が倫理的に問題となる場合に多層ベースラインが選ばれる、という理由づけまで書く。"},{"id":"case-study","t":"事例研究","en":"case study","f":"kenkyu","s":"一つまたは少数の事例の経過を詳しく記述・検討し、事例の理解を深め、臨床的な知見や仮説を導く研究法。個別性や過程をとらえられる一方、一般化には限界がある。","a":"一つまたは少数の事例について、その経過を詳しく記述し、検討することで、事例の理解を深め、臨床的な知見や仮説を導く研究法。心理臨床では、フロイトの症例研究以来、理論や技法の発展を支えてきた。個別性や文脈、治療関係の中での変化の過程を豊かにとらえられる一方、一般化には限界があり、記述が研究者の主観に偏る危険もある。そのため、考察の根拠を明示すること、他の事例や研究と照らし合わせること、プライバシーの保護に十分配慮することが求められる。","k":["少数","経過","フロイト","個別性","一般化","プライバシー"],"p":"「一般化」には統計的な一般化だけでなく、読み手が自分の臨床に照らして意味を見いだす「臨床的な一般化」もある、という論点が使える。"},{"id":"qualitative","t":"質的研究","en":"qualitative research","f":"kenkyu","s":"インタビューや観察などから得た言語的データを数量化せずに分析し、体験の意味や現象の過程を理解しようとする研究法の総称。グラウンデッド・セオリー・アプローチ、KJ法、IPAなどがある。","a":"インタビューや観察、記録などから得られる言語的なデータを、数量化せずに分析し、人々の体験やその意味、現象が生じる過程を理解しようとする研究法の総称。データにもとづいて理論を生成するグラウンデッド・セオリー・アプローチ（グレイザーとストラウス。修正版のM-GTAは木下康仁）、KJ法、複線径路等至性アプローチ（TEA）、解釈的現象学的分析（IPA）などがある。研究者自身の立場や影響を自覚する省察性（リフレクシヴィティ）と、分析手続きの透明性が重視される。","k":["インタビュー","意味","グラウンデッド・セオリー/GTA","KJ法","IPA/解釈的現象学的分析","リフレクシヴィティ/省察性"],"p":"研究計画書で質的研究を選ぶ場合、「なぜ量的でなく質的か」（未知の現象の探索、過程や意味の理解）を必ず説明する。"},{"id":"mixed","t":"混合研究法","en":"mixed methods research","f":"kenkyu","s":"一つの研究の中で量的研究と質的研究を組み合わせ、それぞれの長所を活かして問いに答える研究法。収斂デザイン、説明的順次デザイン、探索的順次デザインなどがある。","a":"同じ研究の中で量的研究と質的研究を組み合わせ、それぞれの長所を活かして、一つの問いにより深く答えようとする研究法。量的データと質的データを同時に集めて比べる収斂デザイン、量的研究の結果を質的研究で説明する説明的順次デザイン、質的研究で探索した結果をもとに尺度などを作って量的に検証する探索的順次デザインなどがある（クレスウェル）。両者をどの段階でどのように統合するかを、研究の目的に応じて明確にすることが求められる。","k":["量的","質的","収斂","説明的順次","探索的順次","統合"],"p":"修士の2年間で無理なく実施できる規模か、という実現可能性の観点も忘れずに。"},{"id":"factor-analysis","t":"因子分析","en":"factor analysis","f":"kenkyu","s":"多数の観測変数間の相関を、それらに共通して影響する少数の潜在変数（因子）によって説明する多変量解析。探索的因子分析と確認的因子分析があり、尺度構成に用いられる。","a":"多数の観測変数の間の相関関係を、それらに共通して影響する少数の潜在的な変数（因子）によって説明しようとする多変量解析の方法。心理尺度の作成で、項目がどのようなまとまりをもつかを調べるために用いられる。データから因子の構造を探る探索的因子分析と、仮説として設定した因子構造がデータに合うかを検証する確認的因子分析がある。探索的因子分析では、因子の数の決定や、解釈しやすくするための因子軸の回転（直交回転、斜交回転）が重要となる。","k":["相関","潜在","因子","探索的","確認的","回転"],"p":"主成分分析との違い（因子分析は潜在変数を仮定する）を問われることがある。"},{"id":"longitudinal","t":"横断研究と縦断研究","en":"cross-sectional / longitudinal study","f":"kenkyu","s":"横断研究は異なる年齢の人々を同時期に比較する方法でコホート効果が混入しうる。縦断研究は同じ人々を長期間追跡する方法で個人内の変化をとらえられるが、時間がかかり脱落が問題となる。","a":"発達的な変化を調べる研究法。横断研究は、異なる年齢の人々を同じ時期に調べて比較する方法で、短期間で多くのデータが得られるが、年齢による差に、生まれた時代の違いによる影響（コホート効果）が混じる。縦断研究は、同じ人々を長期間にわたって追跡して調べる方法で、個人内の変化や、早期の要因が後の状態に与える影響を検討できるが、時間と費用がかかり、参加者の脱落や、繰り返しの測定による練習効果が問題となる。両者を組み合わせた系列法もある。","k":["横断研究","縦断研究","コホート","追跡","脱落","系列法"],"p":"修士研究では短期縦断（数か月の2時点調査）なども現実的な選択肢になる。"},{"id":"action-research","t":"アクションリサーチ","en":"action research","f":"kenkyu","s":"レヴィンが提唱した、研究者が実践の場の当事者と協働し、問題の明確化、計画、実践、評価を循環的に繰り返して、問題の解決と知識の生成を同時にめざす研究法。","a":"レヴィン（Lewin, K.）が提唱した研究法で、研究者が実践の場の当事者と協働しながら、問題を明らかにし、改善のための計画を立てて実践し、その結果を評価して次の計画に活かすという循環を繰り返すことで、社会的な問題の解決と知識の生成を同時にめざす。研究者が対象から距離をとる従来の研究に対し、現場の変化そのものに関わる点に特徴がある。学校や地域、組織における、コミュニティ心理学的な実践の研究などに用いられる。","k":["レヴィン/Lewin","当事者","協働","計画","循環","実践"],"p":"「研究者の中立性」をどう考えるか、という論点も添えられると厚みが出る。"},{"id":"ethics-research","t":"研究倫理","en":"research ethics","f":"kenkyu","s":"研究参加者の人権と福祉を守るための原則と手続き。インフォームド・コンセント、参加の任意性、個人情報の保護、倫理審査委員会の承認などを含み、捏造・改ざん・盗用は研究不正として禁じられる。","a":"研究の参加者の人権と福祉を守るために、研究者が守るべき倫理的な原則と手続きをいう。研究の目的や方法、予想される負担やリスク、参加が自由意思によること、いつでも不利益なく中止できること、個人情報の保護などを説明したうえで同意を得るインフォームド・コンセントが基本となる。研究計画は、事前に倫理審査委員会の審査を受ける。データの捏造、改ざん、盗用は研究不正として厳しく禁じられる。臨床研究では、研究への協力の有無が支援に影響しないよう配慮する。","k":["人権","インフォームド・コンセント","自由意思","倫理審査委員会","捏造","盗用"],"p":"研究計画書・口述試験の頻出論点。とくに「傷つきやすい対象者（被害体験のある人、子ども、患者）」を対象とする場合の配慮を具体的に書けるようにする。"},{"id":"replication","t":"再現性の危機","en":"replication crisis","f":"kenkyu","s":"過去の心理学研究の多くが追試で再現されないことが明らかになった問題。出版バイアスやpハッキング、HARKingなどが背景とされ、事前登録やデータ公開などの対策が進められている。","a":"過去に発表された心理学の研究の多くが、追試によって同じ結果を再現できないことが明らかになった問題をいう。2015年に発表された大規模な追試のプロジェクトでは、元の研究と同じく有意な結果が得られたのは半数を大きく下回った。その背景として、有意な結果ほど公表されやすい出版バイアスや、有意になるまで分析を繰り返すpハッキング、結果を見てから仮説を立てるHARKingなどの問題が指摘された。対策として、研究の事前登録やデータの公開などのオープンサイエンスの取り組みが進められている。","k":["追試","2015","出版バイアス","pハッキング","HARKing","事前登録"],"p":"研究計画書で「仮説を事前に明示する」ことの意義を説明する際の根拠になる。"},{"id":"ceiling","t":"天井効果と床効果","en":"ceiling / floor effect","f":"kenkyu","s":"課題が易しすぎるなどの理由で得点が上限付近に集まり差を検出できなくなることが天井効果、難しすぎるなどの理由で下限付近に集まることが床効果である。","a":"天井効果とは、課題が易しすぎる、あるいは尺度の上限が低すぎるために、多くの参加者の得点が上限付近に集まり、それ以上の差や変化をとらえられなくなることをいう。床効果はその逆で、課題が難しすぎるなどの理由で、得点が下限付近に集まることをいう。いずれも得点の分布が偏り、群間の差や介入の効果を過小に評価したり、統計的な検定の前提を損なったりする。予備調査によって、課題の難易度や尺度の範囲を適切に設定することが求められる。","k":["易しすぎ","上限","床効果","下限","過小","予備調査"],"p":"臨床群と一般群で同じ尺度を使う場合などに起こりやすい、という具体例を添えるとよい。"},{"id":"anova","t":"分散分析と交互作用","en":"ANOVA / interaction","f":"kenkyu","s":"3つ以上の群の平均値の差や、複数の要因の効果を同時に検討する統計手法。各要因の単独の効果を主効果、ある要因の効果が他の要因の水準によって異なることを交互作用という。","a":"分散分析は、3つ以上の群の平均値の差や、複数の要因の効果を同時に検討する方法である。要因が2つ以上ある場合、それぞれの要因が単独で結果に与える影響を主効果、ある要因の効果が他の要因の水準によって異なることを交互作用という。たとえば、ある心理療法の効果が、症状の重い人では大きく、軽い人では小さい場合、治療と重症度の間に交互作用がある。交互作用が有意な場合には、主効果だけで解釈せず、単純主効果の検定などで詳しく検討する。","k":["3つ以上","平均","主効果","交互作用","水準","単純主効果"],"p":"t検定を繰り返すと第1種の誤りが増えるため分散分析を用いる、という理由づけも書けるように。"},{"id":"regression","t":"重回帰分析","en":"multiple regression analysis","f":"kenkyu","s":"一つの目的変数を複数の説明変数の一次式で予測・説明する分析。偏回帰係数で各変数の影響を、決定係数でモデルの説明力を示す。説明変数間の多重共線性に注意を要する。","a":"一つの目的変数（従属変数）を、複数の説明変数（独立変数）の一次式で予測・説明する分析の方法。各説明変数の影響の大きさは、他の説明変数の影響を取り除いたうえでの値である偏回帰係数（標準化したものは標準偏回帰係数）で示され、モデル全体の説明力は決定係数（R²）で示される。説明変数どうしの相関が強すぎると係数の推定が不安定になる多重共線性に注意が必要である。また、回帰分析の結果は、それだけでは因果関係を示すものではない。","k":["目的変数/従属変数","説明変数/独立変数","偏回帰係数","決定係数","多重共線性","因果"],"p":"媒介分析・調整分析（交互作用項）へと発展させる研究計画も多い。用語の違いを整理しておく。"},{"id":"kouninshinrishi","t":"公認心理師法","en":"Certified Public Psychologist Act","f":"rinri","s":"2015年に成立し2017年に施行された、心理職初の国家資格である公認心理師を定めた法律。4つの業務と、信用失墜行為の禁止、秘密保持義務、連携等（主治の医師の指示）などの義務を規定する。","a":"2015年に成立し、2017年に施行された、心理職として初めての国家資格である公認心理師について定めた法律。公認心理師の業務として、心理に関する支援を要する者の心理状態の観察とその結果の分析、その者への相談・助言・指導などの援助、その関係者への援助、心の健康に関する知識の普及のための教育と情報の提供の4つを定める。義務として、信用失墜行為の禁止、秘密保持義務、多職種との連携と、支援の対象者に主治の医師がいる場合にはその指示を受けること、資質向上の責務などを規定している。","k":["2015","2017","国家資格","秘密保持","連携","主治の医師"],"p":"名称独占資格であって業務独占ではない点、臨床心理士（民間資格）との関係もあわせて説明できるようにしておく。"},{"id":"confidentiality","t":"秘密保持とその例外","en":"confidentiality and its limits","f":"rinri","s":"職務上知り得たクライエントの秘密を守る義務。ただし自傷他害のおそれや虐待の通告義務など、生命や安全に関わる場合は例外となりうる。タラソフ判決は他者を保護する義務を示した。","a":"心理職は、職務上知り得たクライエントの秘密を守る義務を負い、これは信頼関係と心理支援の土台である。ただし、自傷他害のおそれがあるなど生命や安全に危険が迫っている場合、虐待が疑われ通告が義務とされる場合、法令にもとづく場合などは例外となりうる。アメリカのタラソフ判決（1976年）は、クライエントが特定の他者に危害を加える危険がある場合、治療者にはその人を保護する義務があるとした。例外がありうることは、あらかじめクライエントに説明しておくことが望ましい。","k":["秘密","信頼関係","自傷他害","虐待","タラソフ","説明"],"p":"「チーム内守秘（集団守秘義務）」の考え方と、本人の同意を得て関係者と情報共有する手続きを書けると事例問題に強い。"},{"id":"multiple-rel","t":"多重関係","en":"multiple relationships","f":"rinri","s":"心理職とクライエントとの間に、専門的関係に加えて友人・恋愛・金銭などの別の関係が存在すること。客観性を損ない搾取の危険を高めるため、原則として避けるべきとされる。","a":"心理職とクライエントとの間に、専門的な援助関係に加えて、友人、恋愛、金銭の取引、仕事上の関係など、別の関係が同時に、あるいは前後して存在することをいう。多重関係は、心理職の客観性を損ない、クライエントを利己的に利用したり搾取したりする危険を高めるため、原則として避けるべきとされる。とくに性的な関係は、いかなる場合も許されない。地域が限られている場合など避けがたい場合には、その影響を十分に検討し、スーパービジョンを受けることが求められる。","k":["クライエント","友人/恋愛","客観性","搾取","性的な関係","スーパービジョン"],"p":"贈り物を受け取るか、SNSでつながるか、など身近な境界の問題に置き換えて論じられるようにしておく。"},{"id":"informed-consent","t":"インフォームド・コンセント","en":"informed consent","f":"rinri","s":"支援の目的、方法、効果と限界、リスク、他の選択肢、秘密保持の範囲などについて十分な説明を受け、理解したうえで自由意思にもとづいて同意すること。自己決定の尊重を基盤とする。","a":"支援を受ける人が、支援の目的、方法、期間、料金、期待される効果と限界、ありうるリスク、他の選択肢、秘密保持とその例外などについて十分な説明を受け、理解したうえで、自由意思にもとづいて同意することをいう。自己決定権の尊重を基盤とする。心理支援では、初回だけでなく、方針の変更時などにも必要に応じて繰り返し行う。子どもや判断能力に制約のある人の場合は、保護者の同意に加え、本人にも理解できる形で説明し、本人の賛意（アセント）を得ることが大切である。","k":["説明","理解","自由意思","自己決定","繰り返し","アセント"],"p":"「書類に署名をもらうこと」ではなく「対話のプロセス」であることを強調する。"},{"id":"supervision","t":"スーパービジョン","en":"supervision","f":"rinri","s":"経験を積んだ心理職が、経験の浅い心理職の担当事例について継続的に指導や助言を行うこと。クライエントを守るとともに、スーパーバイジーの専門的成長を支える教育的機能をもつ。","a":"経験を積んだ心理職（スーパーバイザー）が、より経験の浅い心理職（スーパーバイジー）の担当する事例について、継続的に指導や助言を行うことをいう。クライエントの理解と支援の質を高めてクライエントを守るとともに、スーパーバイジーの専門的な成長を支える教育的な機能をもつ。事例の見立てや介入だけでなく、治療者の逆転移や感情的な反応も検討の対象となる。個人で行うほか、グループで行う形もある。治療者自身が心理療法を受ける教育分析とは区別される。","k":["スーパーバイザー","継続","事例","成長","逆転移","教育分析"],"p":"口述試験で「大学院で何を学びたいか」を問われたときにも、実習とスーパービジョンの意義は語れるようにしておく。"},{"id":"community","t":"コミュニティ心理学","en":"community psychology","f":"rinri","s":"1965年のスワンプスコット会議を契機に成立した心理学の領域。問題を人と環境の適合の観点からとらえ、予防、危機介入、コンサルテーション、エンパワメントなどにより地域で人々を支える。","a":"1965年にアメリカのボストン郊外で開かれたスワンプスコット会議を契機に成立した心理学の領域。問題の原因を個人の内面だけに求めるのではなく、人と環境の適合という観点から問題をとらえ、地域社会の中で人々の生活を支える仕組みづくりをめざす。キャプランの予防の考え方、危機介入、コンサルテーション、ソーシャル・サポートのネットワークづくり、エンパワメント、アウトリーチなどを重視し、専門家と地域住民との協働を大切にする。","k":["1965","スワンプスコット","環境","予防","コンサルテーション","エンパワメント"],"p":"「面接室の中の心理療法」との対比で、その意義と限界を論じさせる出題が考えられる。"},{"id":"prevention","t":"予防の3段階","en":"primary, secondary, tertiary prevention","f":"rinri","s":"キャプランが示した予防の枠組み。問題の発生を防ぐ一次予防、早期発見・早期対応による二次予防、障害の軽減と再発防止・社会復帰支援を行う三次予防からなる。","a":"精神科医のキャプラン（Caplan, G.）が、地域精神保健の考え方として示した予防の枠組み。一次予防は、心の問題の発生そのものを防ぐことで、心の健康教育やストレスへの対処の学習などがある。二次予防は、問題を早期に発見して早期に対応し、重症化や長期化を防ぐことで、スクリーニングや相談体制の整備などがある。三次予防は、すでに生じた問題による障害を最小限にし、再発を防いで社会復帰を支援することで、リハビリテーションなどがある。","k":["キャプラン/Caplan","一次予防","二次予防","三次予防","早期","再発"],"p":"学校・職場・地域など具体的な場面ごとに、3段階の取り組みの例を挙げられるようにしておく。"},{"id":"consultation","t":"コンサルテーション","en":"consultation","f":"rinri","s":"ある領域の専門家（コンサルタント）が、別の領域の専門家（コンサルティ）から担当事例や業務の課題について相談を受け、援助する過程。両者は対等な関係にあり、事例の責任はコンサルティが負う。","a":"ある領域の専門家（コンサルタント）が、別の領域の専門家（コンサルティ）から、その人が担当している事例や業務上の課題について相談を受け、より効果的に対応できるよう援助する過程をいう。たとえば、スクールカウンセラーが教師の相談に応じることがこれにあたる。両者は対等な専門家どうしの関係にあり、事例への責任はコンサルティが負う。キャプランは、事例を中心とするか、コンサルティを中心とするかなどにより4つの型に分類した。","k":["コンサルタント","コンサルティ","教師","対等","責任","キャプラン"],"p":"スーパービジョン（上下関係・同職種・責任をスーパーバイザーも負う）との違いを表で整理しておく。"},{"id":"empowerment","t":"エンパワメント","en":"empowerment","f":"rinri","s":"社会的に不利な立場にある人や集団が、自らの力に気づき、それを発揮して生活や環境を主体的にコントロールできるようになる過程、およびそれを支える援助。","a":"社会的に不利な立場に置かれた人々や集団が、自分の生活や環境に影響を与える力をもっていることに気づき、その力を発揮して、自らの人生のあり方を主体的にコントロールできるようになる過程、またそれを支える援助をいう。コミュニティ心理学では、ラパポート（Rappaport, J.）がその重要性を論じた。専門家が一方的に問題を解決するのではなく、当事者がもつ強みや資源に注目し、当事者と協働しながら、個人、組織、地域の各水準で力を高めていくことを重視する。","k":["不利","力","主体","ラパポート/Rappaport","強み","協働"],"p":"被害者支援、障害者支援、自助グループなど、具体的な場面と結びつけて書くと説得力が増す。"},{"id":"rinshoshinrishi","t":"臨床心理士","en":"clinical psychologist (JSCCP)","f":"rinri","s":"日本臨床心理士資格認定協会が1988年から認定する心理職の資格。指定大学院等の修了と資格審査を要し、5年ごとの更新制をもつ。臨床心理査定、臨床心理面接、臨床心理的地域援助、調査研究を業務とする。","a":"日本臨床心理士資格認定協会が1988年から認定している心理職の資格。指定大学院（第1種・第2種）または専門職大学院を修了し、資格審査に合格する必要があり、5年ごとの資格更新の制度をもつ。業務として、臨床心理査定（アセスメント）、臨床心理面接、臨床心理的地域援助、およびそれらに関する調査・研究の4つが挙げられている。国家資格である公認心理師の誕生後も、高度な専門性を担保する資格として、多くの領域で両資格が並んで求められている。","k":["日本臨床心理士資格認定協会","1988","指定大学院","更新","臨床心理査定","臨床心理的地域援助"],"p":"口述試験で「なぜ両方の資格を目指すのか」と問われたときに、それぞれの特徴（国家資格・連携／大学院教育・研究と更新制）を説明できるように。"},{"id":"sp-model","t":"科学者－実践者モデル","en":"scientist-practitioner model","f":"rinri","s":"1949年のボルダー会議で示された臨床心理学者の養成モデル。科学的研究と臨床実践の両方の訓練を受け、研究の知見を実践に活かし、実践から研究の問いを見いだす専門家をめざす。","a":"1949年にアメリカのボルダー会議で示された、臨床心理学の専門家を養成するためのモデル。臨床心理学者は、心理学の科学的な研究の訓練と、臨床実践の訓練の両方を受け、研究によって得られた知見を実践に活かすとともに、実践の中から研究の問いを見いだす存在であるべきだとする。エビデンスにもとづく実践の考え方にもつながっている。一方で、研究と実践の統合が実際には難しいという批判もあり、実践を重視する実践者－学者モデルなども提唱された。","k":["1949","ボルダー","研究","実践","統合","エビデンス"],"p":"大学院で研究と実習の両方を学ぶ意味（修士論文を書く意義）を語る口述試験の質問にも使える。"},{"id":"ebp","t":"エビデンス・ベイスト・プラクティス","en":"evidence-based practice","f":"rinri","s":"利用可能な最善の研究エビデンスを、臨床家の専門的判断およびクライエントの特性・文化・価値観と統合して支援の方針を決める実践（アメリカ心理学会、2006年）。","a":"心理支援において、①利用可能な最善の研究成果（エビデンス）を、②臨床家の専門的な技能や判断と統合し、③クライエントの特性、文化、価値観、希望を考慮して、支援の方針を決定することをいう（アメリカ心理学会、2006年）。エビデンスを機械的に当てはめるのではなく、目の前のクライエントにとって最善の支援を選ぶための考え方である。エビデンスの階層では、一般に、RCTのシステマティック・レビューやメタ分析が上位に置かれる。","k":["エビデンス","臨床家","統合","価値観/希望","アメリカ心理学会/APA","メタ分析"],"p":"「マニュアル的な治療」と誤解されやすい。3つの要素の「統合」であることを必ず書く。"},{"id":"suicide","t":"自殺の危機への対応","en":"suicide risk and response","f":"rinri","s":"自殺の危険因子（過去の自殺企図、精神疾患、孤立など）と保護因子を評価し、率直に尋ね、傾聴し、安全を確保して関係者と連携する対応。TALKの原則が知られる。","a":"自殺の危険因子には、過去の自殺企図、精神疾患、喪失体験、孤立、援助を求めにくいことなどがあり、保護因子には、周囲とのつながりや支援への信頼などがある。自殺をほのめかす人には、話題を避けず、自殺について率直に尋ねることが勧められ、尋ねることが自殺の危険を高めるわけではない。TALKの原則（Tell：心配していると伝える、Ask：死にたい気持ちについて尋ねる、Listen：傾聴する、Keep safe：安全を確保する）が知られる。一人で抱え込まず、関係者と連携することが重要である。","k":["危険因子","自殺企図","孤立","尋ね","TALK","連携"],"p":"秘密保持の例外とセットで出題されやすい。「本人との関係を保ちながら安全を確保する」両立のしかたを書く。"},{"id":"mhw-law","t":"精神保健福祉法","en":"Mental Health and Welfare Act","f":"rinri","s":"精神障害者の医療と保護、社会復帰と自立の促進を定めた法律。任意入院、医療保護入院、措置入院、緊急措置入院、応急入院などの入院形態と、人権への配慮を規定する。","a":"精神保健福祉法は、精神障害者の医療と保護、社会復帰の促進、自立と社会参加の促進のための援助などを定めた法律である。入院の形態として、本人の同意にもとづく任意入院、精神保健指定医の診察により医療と保護のために入院が必要だが本人の同意が得られない場合に家族等の同意で行う医療保護入院、自傷他害のおそれがある場合に都道府県知事の権限で行う措置入院、急を要する場合の緊急措置入院や応急入院がある。本人の人権への配慮が強く求められる。","k":["任意入院","精神保健指定医","医療保護入院","家族等","措置入院","自傷他害"],"p":"非自発的な入院が本人の自己決定とどう緊張関係にあるか、という倫理的な論点として出題されうる。"},{"id":"reasonable-acc","t":"合理的配慮","en":"reasonable accommodation","f":"rinri","s":"障害のある人が他の人と平等に権利を行使できるよう、個々の状況に応じて行う必要かつ適当な変更・調整のうち、過重な負担とならないもの。障害者差別解消法で民間事業者にも義務化された。","a":"障害のある人が、障害のない人と平等に権利を行使し、社会に参加できるよう、個々の状況に応じて行われる必要かつ適当な変更や調整のうち、行う側にとって過重な負担とならないものをいう。障害者権利条約で示され、日本では障害者差別解消法により、行政機関に加え、2024年4月からは民間の事業者にも提供が義務づけられた。障害を個人の問題ではなく、社会の障壁との相互作用で生じるものとみる社会モデルの考えにもとづき、本人との対話を通じて調整していく。","k":["平等","過重な負担","障害者権利条約","障害者差別解消法","2024","社会モデル"],"p":"心理職の役割（本人の特性の理解を助け、必要な配慮を一緒に言語化する）を書けると実践的。"},{"id":"four-care","t":"職場のメンタルヘルスの4つのケア","en":"four types of care at work","f":"rinri","s":"厚生労働省の指針が示す職場のメンタルヘルス対策の枠組み。セルフケア、ラインによるケア、事業場内産業保健スタッフ等によるケア、事業場外資源によるケアの4つからなる。","a":"厚生労働省の「労働者の心の健康の保持増進のための指針」が示す、職場におけるメンタルヘルス対策の枠組み。労働者自身がストレスに気づき対処するセルフケア、管理監督者が職場環境の改善や部下の相談への対応を行うラインによるケア、産業医や保健師、心理職などの産業保健スタッフ等によるケア、外部の医療機関や相談機関などを活用する事業場外資源によるケアの4つからなる。これらを継続的かつ計画的に行うことが求められ、心理職は職場復帰の支援などにも関わる。","k":["厚生労働省","セルフケア","ラインによるケア","産業保健スタッフ","事業場外資源","職場復帰"],"p":"休職・復職の事例問題で、本人・上司・産業医・主治医の連携を整理する枠組みとして使える。"},{"id":"ethics-7","t":"職業倫理の7原則","en":"seven principles of professional ethics","f":"rinri","s":"金沢吉展が整理した心理職の職業倫理の7原則。相手を傷つけない、専門的能力の範囲内で寄与する、利己的に利用しない、人として尊重する、秘密を守る、インフォームド・コンセント、公平と正義。","a":"金沢吉展が整理した、心理職の職業倫理の基本原則。①相手を傷つけない、傷つけるようなおそれのあることをしない、②十分な教育と訓練によって身につけた専門的な行動の範囲内で、相手の健康と福祉に寄与する、③相手を利己的に利用しない、④一人ひとりを人間として尊重する、⑤秘密を守る、⑥インフォームド・コンセントを得て、相手の自己決定権を尊重する、⑦すべての人々を公平に扱い、社会的な正義と公正・平等の精神を具現する、の7つからなる。","k":["金沢吉展","傷つけない","利己的","秘密","インフォームド・コンセント","公平"],"p":"倫理の事例問題では、どの原則とどの原則が衝突しているか（例：秘密保持と安全の確保）を示すと論理的な答案になる。"},{"id":"burnout","t":"バーンアウト","en":"burnout","f":"rinri","s":"長期間の過度の負担によって心身のエネルギーが枯渇した状態。マスラックは、情緒的消耗感、脱人格化、個人的達成感の低下の3側面からとらえた。対人援助職に多い。","a":"対人援助職などにみられる、長期にわたる過度の心理的な負担によって、心身のエネルギーが枯渇した状態をいい、燃え尽き症候群とも呼ばれる。マスラック（Maslach, C.）は、情緒的消耗感、相手を人として扱わなくなる脱人格化、仕事の成果が感じられなくなる個人的達成感の低下の3つの側面からとらえ、その測定尺度を作成した。熱意をもって仕事に取り組む人ほど陥りやすいとされる。個人のセルフケアだけでなく、職場の業務量や支え合いの体制など、組織としての対策が重要である。","k":["対人援助","マスラック/Maslach","情緒的消耗感","脱人格化","個人的達成感","組織"],"p":"代理受傷・共感疲労（トラウマの内容に由来）との違い（業務負担一般に由来）を書き分ける。"},{"id":"multicultural","t":"多文化と文化的コンピテンス","en":"multicultural competence","f":"rinri","s":"クライエントと支援者の文化的背景の違いを踏まえ、多様性に配慮した支援を行う能力。スーらは、自らの価値観や偏見への自覚、相手の文化についての知識、文化に適した技能を挙げた。","a":"心理支援が、クライエントと支援者それぞれの文化的な背景（民族、言語、宗教、ジェンダー、性的指向、障害、社会階層など）の影響を受けることを踏まえ、文化的な多様性に配慮した支援を行う能力をいう。スー（Sue, D. W.）らは、支援者自身の文化的な価値観や偏見への自覚、クライエントの文化についての知識、文化に適した介入の技能の3つを挙げた。支援者の文化の基準でクライエントを病理化しないことが重要であり、マイクロアグレッションへの感受性も求められる。","k":["文化","多様性","スー/Sue","自覚","知識","技能"],"p":"上智大学は国際性を重視する大学でもあり、外国にルーツをもつ人への支援などを口述試験で語れるようにしておくのも一案。"},{"id":"depth-cues","t":"奥行き知覚の手がかり","en":"depth cues","f":"neuro","s":"網膜像は2次元であるにもかかわらず3次元の奥行きを知覚するために用いられる情報。片目でも利用できる単眼性の手がかりと、両眼の情報による両眼性の手がかりがある。","a":"網膜に映る像は2次元であるにもかかわらず、私たちが奥行きや距離を知覚するために用いている情報をいう。片目でも利用できる単眼性の手がかりには、線遠近法、きめの勾配、相対的な大きさ、重なり（遮蔽）、陰影、大気遠近法などの絵画的手がかりと、自分が動いたときの見え方の違いである運動視差、水晶体の調節がある。両眼性の手がかりには、左右の網膜像のずれである両眼視差と、両眼の輻輳がある。両眼視差は立体視の基礎となる。","k":["2次元","単眼","線遠近法/きめの勾配","運動視差","両眼視差","輻輳"],"p":"単眼性（絵画的手がかり＋運動視差・調節）と両眼性（両眼視差・輻輳）に分けて、例を2〜3個ずつ挙げると簡潔にまとまる。"},{"id":"completion","t":"知覚的補完","en":"perceptual completion","f":"neuro","s":"刺激の一部が欠けていたり遮られていたりしても、欠けた部分を補って一つのまとまった形として知覚する働き。主観的輪郭のように見える補完（モーダル補完）と、遮蔽された部分を補う補完（アモーダル補完）がある。","a":"感覚情報の一部が欠けていたり、他の物に遮られていたりしても、欠けた部分を補って、まとまりのある形や物として知覚する働きをいう。カニッツァの三角形のように、物理的には輪郭がないところに輪郭が見える主観的輪郭は、補われた部分が実際に見えるモーダル補完の例である。一方、手前の物に隠された部分を、見えてはいないが連続しているものとして知覚するのがアモーダル補完である。網膜の盲点の部分が欠けて見えないことも、補完によって説明される。","k":["欠け","補","主観的輪郭/カニッツァ","モーダル補完","アモーダル補完","盲点"],"p":"「見えるように補う（モーダル）」と「見えないが存在すると知覚する（アモーダル）」の区別が書けると十分。"},{"id":"constancy","t":"知覚の恒常性","en":"perceptual constancy","f":"neuro","s":"網膜像の大きさや形、明るさ、色が観察条件によって変化しても、対象の大きさや形、明るさ、色を比較的一定のものとして知覚する傾向。","a":"対象を見る距離や角度、照明などの観察条件が変わって網膜像が変化しても、対象そのものの性質を比較的一定のものとして知覚する傾向をいう。遠ざかる人の網膜像は小さくなるが、人の背丈が縮んだようには見えない大きさの恒常性、斜めから見た円い皿を円いと知覚する形の恒常性、照明が変わっても白い紙を白いと知覚する明るさの恒常性や色の恒常性がある。網膜像だけでなく、距離や照明などの文脈の情報を手がかりとして対象を推定する知覚の働きを示している。","k":["網膜像","一定","大きさの恒常性","形の恒常性","明るさ/色の恒常性","文脈"],"p":"錯視（恒常性の働きが不適切に働く例）と関連づけて説明することもできる。"},{"id":"color-vision","t":"色覚の三色説と反対色説","en":"trichromatic and opponent-process theories","f":"neuro","s":"三色説は網膜の3種類の錐体の応答の組合せで色を知覚するとし、反対色説は赤－緑、黄－青、白－黒の対立する過程で色を知覚するとする。現在は両者を段階的に統合する段階説が支持されている。","a":"ヤング＝ヘルムホルツの三色説は、色の知覚を、異なる波長に感度をもつ3種類の受容器の応答の組み合わせで説明し、のちに網膜の3種類の錐体（短波長・中波長・長波長）として確認された。ヘリングの反対色説は、赤－緑、黄－青、白－黒という対立する過程で色を説明し、補色残像や「赤みがかった緑」が見えないことをよく説明する。現在は、網膜の錐体の段階では三色説、網膜の神経節細胞や外側膝状体の段階では反対色的な処理が行われるとする段階説が支持されている。","k":["三色説/ヤング","錐体","反対色説/ヘリング","補色残像","段階説","外側膝状体"],"p":"色の知覚は過去の公開問題でも論述として問われている。錐体→神経節細胞・外側膝状体→大脳皮質（V4など）という処理の流れも整理しておく。"},{"id":"aftereffect","t":"残効","en":"aftereffect","f":"neuro","s":"ある刺激を一定時間見続けた後、別の刺激を見たときに、先の刺激と反対方向の知覚が生じる現象。運動残効、色残効（補色残像）、傾き残効などがあり、特定の特徴に反応する神経の順応によって説明される。","a":"特定の刺激をしばらく見続けた（順応した）後に別の刺激を見ると、先の刺激とは反対の性質をもつ知覚が生じる現象をいう。滝の流れを見続けた後に静止した岩を見ると上に動いて見える運動残効（滝の錯視）、赤い図形を見続けた後に白い面を見ると緑の像が見える色の残効（補色残像）、傾いた縞模様への順応後に垂直の縞が逆に傾いて見える傾き残効などがある。特定の方向や色に選択的に反応する神経細胞の活動が順応によって低下し、反対の特徴に反応する細胞との均衡が崩れるためと考えられている。","k":["順応","反対","運動残効/滝の錯視","補色残像","傾き残効","神経細胞"],"p":"残効の存在は、特定の特徴に反応する神経機構（特徴検出器）や反対色過程の証拠として論じられる。"},{"id":"gestalt","t":"ゲシュタルトの群化の要因","en":"Gestalt principles of grouping","f":"neuro","s":"ゲシュタルト心理学が示した、視野の中の要素がまとまって知覚されるときの法則。近接、類同、閉合、よい連続、共通運命などの要因があり、全体として最も簡潔でよいまとまりに向かう傾向をプレグナンツの法則という。","a":"ウェルトハイマーらゲシュタルト心理学者は、知覚は要素の単なる寄せ集めではなく、全体としてのまとまり（ゲシュタルト）として成立すると考えた。視野の中の要素がまとまって見える要因として、近くにあるものどうしがまとまる近接の要因、似たものどうしがまとまる類同の要因、閉じた形をつくるものがまとまる閉合の要因、なめらかにつながるものがまとまるよい連続の要因、同じ方向に動くものがまとまる共通運命の要因などがある。これらは、最も簡潔で規則的なまとまりに向かうプレグナンツの法則としてまとめられる。","k":["ゲシュタルト","全体","近接","類同","閉合","プレグナンツ"],"p":"図と地の分化（ルビンの盃）とセットで問われることがある。"},{"id":"psychophysics","t":"精神物理学的測定法","en":"psychophysical methods","f":"neuro","s":"刺激の物理量と感覚の大きさとの関係を測定する方法。フェヒナーが体系化した極限法、恒常法、調整法などがあり、刺激閾や弁別閾、主観的等価点を求める。","a":"フェヒナーが体系化した、刺激の物理的な量と、それによって生じる感覚の大きさとの関係を測定する方法である。刺激を一定の段階で上昇または下降させて「感じる・感じない」の判断が変わる点を求める極限法、あらかじめ決めた複数の刺激をランダムな順序で多数回提示して反応率から閾値を推定する恒常法、実験参加者自身が刺激を調整して基準と等しくする調整法がある。極限法を応用した階段法（上下法）も広く用いられる。これらにより、刺激閾、弁別閾（丁度可知差異）、主観的等価点が求められる。","k":["フェヒナー","極限法","恒常法","調整法","閾","主観的等価点"],"p":"公開問題では聴覚の実験計画（どの物理量を操作し、どの測定法を使うか）として問われた。各方法の長所（恒常法は精度が高いが時間がかかる等）も押さえる。"},{"id":"weber-fechner","t":"ウェーバーの法則とフェヒナーの法則","en":"Weber's law / Fechner's law","f":"neuro","s":"ウェーバーの法則は、弁別閾（丁度可知差異）が基準となる刺激の強さに比例するという法則。フェヒナーの法則は、感覚の大きさが刺激の強さの対数に比例するという法則である。","a":"ウェーバーの法則は、ある刺激の強さの変化に気づくために必要な最小の変化量である弁別閾（丁度可知差異）が、基準となる刺激の強さに比例する（ΔI／I＝一定）という法則である。たとえば100gの重さに対して2gの差がわかるなら、200gでは4gの差が必要となる。フェヒナーはこれをもとに、感覚の大きさは刺激の強さの対数に比例するというフェヒナーの法則を導いた。その後スティーヴンスは、マグニチュード推定法による研究から、感覚の大きさは刺激の強さのべき乗に比例するというべき法則を提唱した。","k":["弁別閾/丁度可知差異","比例","対数","フェヒナー","スティーヴンス","べき"],"p":"ウェーバー比は感覚モダリティによって異なること、中程度の強さの範囲でよく成り立つことも添えられると正確。"},{"id":"signal-detection","t":"信号検出理論","en":"signal detection theory","f":"neuro","s":"雑音の中から信号を検出する判断を、感覚的な感度（d'）と、反応の基準（判断の偏り）とに分けてとらえる理論。ヒット、ミス、誤警報、正棄却の比率から両者を推定する。","a":"雑音の中から信号の有無を判断する場面を扱う理論で、検出の成績を、刺激を見分ける感覚的な感度と、「ある」と答えるかどうかの判断の基準（反応バイアス）とに分けてとらえる。信号があるときに「ある」と答えるヒット、「ない」と答えるミス、信号がないときに「ある」と答える誤警報、「ない」と答える正棄却の比率から、感度の指標d'と判断基準βを推定する。従来の閾値の考え方では区別できなかった、見落としを恐れて基準を下げる、といった判断の偏りを扱える点に意義があり、医療の診断などにも応用される。","k":["雑音","感度","判断の基準/反応バイアス","ヒット","誤警報","d'"],"p":"感度と特異度（スクリーニング検査の評価）との対応を意識しておくと、研究法の問題にも使える。"},{"id":"face-inversion","t":"顔の倒立効果","en":"face inversion effect","f":"neuro","s":"顔を上下逆さまにすると、他の物体に比べて認識の成績が著しく低下する現象。顔は部分の配置関係を全体として処理する布置的・全体的処理によって認識されており、倒立によってその処理が妨げられるためと考えられる。","a":"顔を上下逆さまにして提示すると、家などの他の物体を逆さまにした場合に比べて、認識や記憶の成績が著しく低下する現象をいい、イン（Yin, R. K.）が報告した。目と口だけを逆さまにした顔を倒立させると異常に気づきにくいサッチャー錯視もその例である。顔は、目や鼻などの部分を個別に処理する局所的な処理に加えて、部分どうしの配置関係（布置）を全体として処理する全体的・布置的な処理によって認識されており、倒立によってこの処理が妨げられると考えられている。","k":["逆さま/倒立","他の物体","サッチャー錯視","布置","全体的","局所"],"p":"公開問題でも問われた形式。「顔は特別な処理を受けるか」という議論（紡錘状回顔領域など）にふれると厚みが出る。"},{"id":"visual-search","t":"視覚探索と特徴統合理論","en":"visual search / feature integration theory","f":"neuro","s":"多数の妨害刺激の中から標的を探す課題。色など単一の特徴で区別できる特徴探索では標的がすぐに目立ち、複数の特徴の組合せで区別する結合探索では、妨害刺激の数とともに探索時間が増える。","a":"視覚探索とは、多数の妨害刺激の中から標的となる刺激を探す課題である。標的が色や傾きなど単一の特徴で区別できる特徴探索では、標的が自然に目立ち（ポップアウト）、探索時間は妨害刺激の数にほとんど影響されない。これに対し、色と形の組み合わせのように複数の特徴の結合で区別する結合探索では、妨害刺激の数とともに探索時間が直線的に増える。トリーズマンの特徴統合理論は、特徴は並列的に処理されるが、それらを一つの対象として結びつけるには焦点的注意による逐次的な処理が必要であると説明した。","k":["妨害刺激","特徴探索","ポップアウト","結合探索","トリーズマン/特徴統合理論","逐次"],"p":"並列処理と逐次処理、注意の役割を結論に置くとまとまる。"},{"id":"selective-attention","t":"選択的注意","en":"selective attention","f":"neuro","s":"多くの情報の中から特定の情報を選んで処理し、他を抑える注意の働き。騒がしい場所で特定の人の話を聞き取れるカクテルパーティ効果が例で、選択がどの段階で起こるかについて初期選択説と後期選択説がある。","a":"多くの情報が同時に入ってくる中から、特定の情報を選んで処理し、それ以外の情報を抑える注意の働きをいう。騒がしいパーティ会場でも話し相手の声を聞き取り、離れた場所で自分の名前が呼ばれると気づくカクテルパーティ効果がよく知られる。左右の耳に別々の音声を聞かせる両耳分離聴の研究から、ブロードベントは意味の処理以前に情報が選別されるフィルター説（初期選択説）を唱えたが、注意を向けていない情報の意味も処理されうることから、減衰説や後期選択説が提唱された。","k":["選","カクテルパーティ","両耳分離聴","ブロードベント/フィルター","初期選択","後期選択"],"p":"注意の容量（資源）の考え方や、臨床では不安による脅威刺激への注意バイアスとも関連づけられる。"},{"id":"action-potential","t":"静止膜電位と活動電位","en":"resting and action potentials","f":"neuro","s":"神経細胞は静止時に細胞内が外に対して約−70mVの静止膜電位にある。刺激により脱分極が閾値を超えると、ナトリウムイオンの流入によって一過性に電位が逆転する活動電位（全か無かの法則に従う）が生じる。","a":"神経細胞の膜の内側は、静止時に外側に対して約−70mVの負の電位にあり、これを静止膜電位という。主にカリウムイオンが漏洩チャネルを通って細胞外へ出やすいことと、ナトリウム－カリウムポンプの働きによって生じ、カリウムイオンの平衡電位に近い値となる。刺激により膜電位がプラス方向へ変化することを脱分極といい、これが閾値を超えると電位依存性ナトリウムチャネルが開いてナトリウムイオンが流入し、電位が一過性に逆転する活動電位が生じる。活動電位は全か無かの法則に従い、軸索を伝導する。","k":["−70/静止膜電位","カリウム","ナトリウム","平衡電位","脱分極","全か無か"],"p":"公開問題でも「脱分極」の語句説明や静止膜電位の機序が問われた。平衡電位（ネルンストの式）との関係まで説明できるようにしておく。"},{"id":"synapse","t":"シナプスと神経伝達物質","en":"synapse and neurotransmitters","f":"neuro","s":"神経細胞どうしの接合部をシナプスといい、化学シナプスでは、活動電位が軸索終末に達すると神経伝達物質が放出され、受け手の細胞の受容体に結合して興奮性または抑制性の電位変化を生じさせる。","a":"シナプスは、神経細胞と神経細胞、あるいは神経細胞と筋などとの接合部である。化学シナプスでは、活動電位が軸索終末に達するとシナプス小胞から神経伝達物質がシナプス間隙に放出され、受け手の細胞の受容体に結合して、興奮性シナプス後電位または抑制性シナプス後電位を生じさせる。主な神経伝達物質に、興奮性のグルタミン酸、抑制性のGABA、ドーパミン、セロトニン、ノルアドレナリン、アセチルコリンなどがある。放出された伝達物質は再取り込みなどで除去され、SSRIはセロトニンの再取り込みを阻害する薬である。","k":["接合部","神経伝達物質","受容体","興奮性","抑制性","再取り込み"],"p":"向精神薬の作用機序（SSRI、抗精神病薬のドーパミン受容体遮断など）と結びつけて説明できると臨床的。"},{"id":"glia","t":"グリア細胞","en":"glial cells","f":"neuro","s":"神経系において神経細胞以外の細胞の総称。アストロサイト、オリゴデンドロサイト、ミクログリアなどがあり、支持にとどまらず、シナプス伝達の調節や髄鞘形成、免疫などを通して脳の情報処理に積極的に関わる。","a":"神経系を構成する、神経細胞以外の細胞の総称である。かつては神経細胞を支える「糊」とみなされていたが、現在では脳の情報処理に積極的に関わることが明らかになっている。アストロサイトは、血液脳関門の形成、神経伝達物質の取り込みやイオン濃度の調節を行い、シナプスの働きを調節する。オリゴデンドロサイトは中枢神経系で軸索に髄鞘を形成し、跳躍伝導による速い伝導を可能にする（末梢ではシュワン細胞）。ミクログリアは免疫を担い、発達期のシナプスの刈り込みにも関与する。","k":["神経細胞以外","アストロサイト","オリゴデンドロサイト/髄鞘","ミクログリア","情報処理","シナプス"],"p":"公開問題では「支持細胞にとどまらない役割」を説明することが求められた。3種類の役割を一文ずつ言えるようにしておく。"},{"id":"amygdala","t":"扁桃体","en":"amygdala","f":"neuro","s":"側頭葉の内側にある神経核の集まりで、大脳辺縁系に含まれる。恐怖をはじめとする情動の処理や、刺激の情動的な意味の評価、恐怖条件づけ、情動的な記憶の強化に重要な役割を果たす。","a":"側頭葉の内側部にあるアーモンド形の神経核の集まりで、大脳辺縁系の一部である。外界の刺激が自分にとって危険かどうかといった情動的な意味を素早く評価し、恐怖反応を引き起こすうえで中心的な役割を果たす。音と電気ショックを対提示する恐怖条件づけの成立に不可欠であり、ルドゥーは、視床から扁桃体へ直接向かう速い経路と、大脳皮質を経由する遅い経路を示した。また、海馬と相互に作用して情動的な出来事の記憶を強める。PTSDや不安障害では扁桃体の過活動が指摘されている。","k":["側頭葉","大脳辺縁系","恐怖","恐怖条件づけ","海馬","PTSD/不安"],"p":"前頭前野による扁桃体の制御（情動調整）という観点を添えると、臨床（CBTやマインドフルネスの作用）とつなげられる。"},{"id":"hippocampus","t":"海馬","en":"hippocampus","f":"neuro","s":"側頭葉の内側にある大脳辺縁系の構造で、新しい出来事の記憶（宣言的記憶）の形成と固定、および空間の記憶に重要な役割を果たす。両側の損傷では前向健忘が生じる。","a":"側頭葉の内側にある、タツノオトシゴのような形の構造で、大脳辺縁系に含まれる。新しい出来事や知識の記憶（宣言的記憶）を形成し、大脳皮質に固定していく過程に重要な役割を果たす。てんかんの治療のために両側の海馬を含む部位を切除された患者H.M.は、手術以降の新しいことを覚えられない前向健忘を示したが、運動技能の学習（手続き記憶）は保たれていた。また場所細胞の発見に示されるように、空間の記憶にも関わる。ストレスホルモンの影響を受けやすく、アルツハイマー型認知症では早期から萎縮がみられる。","k":["側頭葉","宣言的記憶","固定","H.M.","前向健忘","空間"],"p":"記憶の分類（宣言的／非宣言的）と脳部位の対応を表にしておくと、基礎と臨床の両方の問題に使える。"},{"id":"prefrontal","t":"前頭前野と実行機能","en":"prefrontal cortex / executive function","f":"neuro","s":"前頭葉の前方部で、目標に向けて行動を計画し、不適切な反応を抑制し、状況に応じて柔軟に切り替え、情報を保持・操作する実行機能を担う。損傷により計画性の低下や脱抑制などが生じる。","a":"前頭葉の前方を占める領域で、ヒトで特に発達している。目標に向けて行動を計画し、順序立てて実行し、不適切な反応を抑制し、状況の変化に応じて考えや行動を柔軟に切り替え、必要な情報を一時的に保持して操作する、といった実行機能を担う。鉄の棒が頭部を貫通した事故の後、人格が変化したとされるフィニアス・ゲージの事例が知られる。実行機能はウィスコンシン・カード分類検査やストループ課題などで評価され、ADHDや統合失調症、前頭側頭型認知症などで障害がみられる。","k":["前頭葉","計画","抑制","切り替え/柔軟","実行機能","ウィスコンシン/ストループ"],"p":"情動の制御（扁桃体の抑制）や意思決定にも関わることを添えると広がりが出る。"},{"id":"brain-imaging","t":"非侵襲的脳機能計測法","en":"non-invasive brain imaging","f":"neuro","s":"身体を傷つけずに脳の活動を計測する方法の総称。血流の変化をとらえるfMRIやNIRS、神経の電気的・磁気的活動をとらえる脳波（EEG）やMEGなどがあり、空間分解能と時間分解能に違いがある。","a":"身体を傷つけることなく、脳の活動を外部から計測する方法の総称である。fMRI（機能的磁気共鳴画像法）は、神経活動に伴う血中の酸素化ヘモグロビンの変化（BOLD信号）をとらえ、空間分解能に優れるが、血流変化を介するため時間分解能は低い。NIRS（近赤外分光法）も血流の変化を測定し、装置が小さく子どもにも使いやすい。脳波（EEG）や事象関連電位、MEG（脳磁図）は神経の電気的・磁気的活動を直接とらえるためミリ秒単位の時間分解能に優れるが、発生源の特定は難しい。目的に応じて方法を選び、組み合わせることが重要である。","k":["傷つけ","fMRI","NIRS","脳波/EEG","空間分解能","時間分解能"],"p":"「どの方法が、何を、どのくらいの精度でとらえるか」を表で整理しておく。相関的な知見であり因果は直接示せない点（→光遺伝学との対比）も論点。"},{"id":"optogenetics","t":"光遺伝学","en":"optogenetics","f":"neuro","s":"光に反応するタンパク質の遺伝子を特定の神経細胞に導入し、光照射によってその神経細胞の活動をミリ秒単位で活性化または抑制する技法。特定の神経回路が行動に果たす因果的役割を検証できる。","a":"光に反応して開くイオンチャネルなどのタンパク質（チャネルロドプシンやハロロドプシンなど）の遺伝子を、遺伝学的な手法で特定の種類の神経細胞に導入し、光を当てることでその神経細胞の活動を活性化させたり抑制したりする技法である。2005年ごろにダイセロスらによって確立された。特定の細胞だけを、ミリ秒単位の時間精度で操作できる点に特徴がある。これにより、ある神経回路の活動が恐怖や報酬、記憶などの行動や情動にどのように因果的に関与しているかを、動物実験で直接検証できるようになった。","k":["光","遺伝子","チャネルロドプシン","特定","ミリ秒","因果"],"p":"公開問題では原理と生理心理学での意義が問われた。「観察（相関）から操作（因果）へ」という意義を結論に置く。"},{"id":"ans","t":"自律神経系","en":"autonomic nervous system","f":"neuro","s":"意思とは無関係に内臓や血管、腺などの働きを調節する神経系。活動時やストレス時に働く交感神経系と、休息時に働く副交感神経系からなり、多くの器官を拮抗的に二重支配している。","a":"意思とは無関係に、心臓、血管、消化管、汗腺などの働きを調節して体内の環境を一定に保つ神経系である。交感神経系は、闘争や逃走など活動やストレスの場面で優位となり、心拍数や血圧の上昇、瞳孔の散大、消化の抑制などを引き起こす。副交感神経系は休息や消化の場面で優位となり、心拍数の低下や消化の促進などをもたらす。多くの器官は両者によって拮抗的に二重支配されている。ストレスへの反応、心身症、リラクセーション法やバイオフィードバックの理解の基礎となる。","k":["意思","交感神経","副交感神経","拮抗","二重支配","ストレス"],"p":"キャノンの緊急反応、HPA軸とあわせて、ストレスの生理学として整理する。"},{"id":"neglect","t":"半側空間無視","en":"unilateral spatial neglect","f":"neuro","s":"脳の損傷により、損傷と反対側の空間にある刺激に気づかず、反応しない症状。右半球、特に頭頂葉の損傷による左側の無視が多く、線分二等分検査や抹消検査で評価される。","a":"脳の損傷により、損傷した大脳半球と反対側の空間にある刺激に気づかず、反応しなかったり、注意を向けられなかったりする症状をいう。視力や視野の障害では説明できない、注意や空間認知の障害である。右半球、特に頭頂葉の損傷による左側の無視が多くみられる。食事の皿の左側を残す、左側にある物にぶつかるといった形で日常生活に現れる。線分の中点に印をつける線分二等分検査や、紙面上の標的を消していく抹消検査で評価され、本人が障害に気づきにくいこともある。","k":["反対側","気づ","右半球","頭頂葉","線分二等分","抹消検査"],"p":"高次脳機能障害（失語・失認・失行）の一つとして、リハビリテーションの心理支援と結びつけて整理する。"},{"id":"aphasia","t":"失語","en":"aphasia","f":"neuro","s":"脳の損傷により、いったん獲得した言語の理解や表出が障害された状態。左前頭葉のブローカ野の損傷では非流暢な発話が、左側頭葉のウェルニッケ野の損傷では流暢だが意味の通じにくい発話と理解の障害がみられる。","a":"脳の損傷によって、いったん獲得された言語の機能（話す、聞いて理解する、読む、書く）が障害された状態をいう。多くは左半球の損傷による。左前頭葉のブローカ野の損傷によるブローカ失語では、発話が非流暢でたどたどしいが、理解は比較的保たれる。左側頭葉のウェルニッケ野の損傷によるウェルニッケ失語では、発話は流暢だが言い誤りが多く意味が通じにくく、言語の理解が強く障害される。両者を結ぶ弓状束の損傷では復唱の障害が目立つ伝導失語が生じる。","k":["獲得","左半球","ブローカ","非流暢","ウェルニッケ","理解"],"p":"構音障害（発声器官の運動の障害）との区別を一言添えると正確。"},{"id":"pitch-loudness","t":"音の高さと大きさの知覚","en":"perception of pitch and loudness","f":"neuro","s":"音の高さ（ピッチ）は主に空気の振動の周波数に、音の大きさ（ラウドネス）は主に音圧（振幅）に対応する。ただし両者は独立ではなく、同じ音圧でも周波数によって感じられる大きさが異なる（等ラウドネス曲線）。","a":"音は空気の圧力の振動であり、その物理的な性質と感覚とが対応している。音の高さの感覚（ピッチ）は主に振動の周波数（Hz）に、音の大きさの感覚（ラウドネス）は主に音圧（振幅、dBで表す）に対応する。ヒトが聞くことのできる周波数はおよそ20〜2万Hzである。ただし両者は独立ではなく、同じ音圧の純音でも、周波数によって感じられる大きさが異なり、2000〜5000Hz付近で最も感度が高い。等しい大きさに感じられる音圧を周波数ごとに結んだものを等ラウドネス曲線という。","k":["周波数","音圧/振幅","ピッチ","ラウドネス","20","等ラウドネス曲線"],"p":"公開問題の実験計画型の論述では「何を操作するか（周波数と音圧）」「どの心理物理学的測定法を使うか」が問われた。"},{"id":"mere-exposure","t":"単純接触効果","en":"mere exposure effect","f":"social","s":"ある対象に繰り返し接するだけで、その対象への好意が高まる現象。ザイアンスが示し、本人が接触を意識していない場合にも生じることが知られている。","a":"ある刺激や人物に繰り返し接するだけで、その対象への好意や評価が高まる現象をいい、ザイアンス（Zajonc, R. B.）が1968年に示した。意味のわからない文字や見知らぬ人の顔写真などでも、提示された回数が多いほど好ましく評価される。刺激が意識できないほど短時間しか提示されなかった場合にも生じることから、刺激の処理のしやすさ（知覚的流暢性）が好意と誤って帰属されることなどで説明される。ただし、最初に嫌悪感をもった対象では効果が生じにくく、接触が多すぎると飽きが生じることもある。","k":["繰り返し","好意","ザイアンス/Zajonc","意識","流暢性","嫌悪"],"p":"広告や対人魅力（近接性）と結びつけた具体例を添えると論述にも使える。"},{"id":"impression","t":"印象形成","en":"impression formation","f":"social","s":"他者についての断片的な情報を統合して、その人の全体的な印象を形成する過程。アッシュは「あたたかい－つめたい」のような中心特性や、最初に与えられた情報が重視される初頭効果を示した。","a":"他者の外見や行動、伝え聞いた特徴などの断片的な情報を統合して、その人物についてまとまった印象を形成する過程をいう。アッシュ（Asch, S. E.）は、性格特性のリストを提示する実験から、「あたたかい－つめたい」のように全体の印象を大きく左右する中心特性があること、同じ特性でも提示の順序によって印象が変わり、最初の情報が重視される初頭効果があることを示した。のちに、カテゴリーにもとづく処理と個人の特徴にもとづく処理を区別する連続体モデルなども提唱された。","k":["断片","統合","アッシュ/Asch","中心特性","初頭効果","カテゴリー"],"p":"初頭効果と新近効果、ハロー効果、ステレオタイプとの関連を整理しておく。"},{"id":"halo-leniency","t":"寛大効果とハロー効果","en":"leniency effect / halo effect","f":"social","s":"寛大効果は、他者を評価する際に、実際よりも好意的・寛大に評価してしまう傾向。ハロー効果は、ある目立つ特徴の印象が、他の無関係な特徴の評価にまで及ぶ傾向。いずれも評価の歪みである。","a":"いずれも他者を評価する際に生じる系統的な歪みである。寛大効果（寛大化傾向）は、評価者が相手を実際よりも好意的・寛大に評価してしまう傾向で、好意をもつ相手や、関係を損ねたくない相手に対して生じやすい。人事評価や教育評価で問題となり、評価が上位に偏る原因となる。ハロー効果（光背効果）は、ソーンダイクが名づけた、ある目立つ特徴（外見や学歴など）についての好ましい（または好ましくない）印象が、それと無関係な他の特徴の評価にまで及ぶ傾向である。評価基準の明確化や評価者訓練が対策となる。","k":["評価","好意的/寛大","人事評価/教育評価","ハロー効果/光背","ソーンダイク","評価基準"],"p":"中心化傾向、厳格化傾向、論理的誤差など、評定の誤り全体の中に位置づけて整理する。"},{"id":"persuasion","t":"説得的コミュニケーション","en":"persuasive communication","f":"social","s":"主に言語によって相手の態度や行動を特定の方向へ変えようとするコミュニケーション。送り手の信憑性、メッセージの内容、受け手の特性などが効果を左右し、精緻化見込みモデルは中心ルートと周辺ルートを区別した。","a":"主に言語的なメッセージによって、受け手の態度や行動を意図した方向へ変化させようとするコミュニケーションをいう。ホヴランドらのイェール大学の研究は、送り手の専門性や信頼性（信憑性）、メッセージの構成（一面提示と両面提示、恐怖喚起の程度）、受け手の特性などが効果に影響することを示した。ペティとカシオッポの精緻化見込みモデルは、受け手に動機と能力があるときにはメッセージの論拠を吟味する中心ルートで、ないときには送り手の魅力などの手がかりによる周辺ルートで態度が変わるとした。","k":["態度","信憑性/信頼性","ホヴランド","精緻化見込みモデル","中心ルート","周辺ルート"],"p":"心理教育や健康行動の促進（恐怖喚起コミュニケーション）など、臨床への応用を一例添えるとよい。"},{"id":"tpb","t":"態度と行動（計画的行動理論）","en":"attitude-behavior relation / theory of planned behavior","f":"social","s":"態度は必ずしも行動と一致しないことが示され、両者の関係を説明するモデルが提唱された。エイゼンの計画的行動理論は、行動への態度、主観的規範、知覚された行動統制感が行動意図を介して行動を予測するとする。","a":"人が対象に対してもつ態度は、必ずしもその人の行動と一致しない。ラピエールは、中国系の夫婦とともに多くのホテルやレストランを訪れてほとんど断られなかったが、後の質問紙では多くの店が「中国系の客は受け入れない」と回答したことを報告した。フィッシュバインとエイゼンの合理的行為理論は、行動への態度と主観的規範（周囲の期待）が行動意図を決め、意図が行動を決めるとした。エイゼンはさらに、行動をどの程度自分で制御できるかという知覚された行動統制感を加えた計画的行動理論を提唱した。","k":["一致","ラピエール","合理的行為","主観的規範","知覚された行動統制感","行動意図"],"p":"公開問題でも「態度と行動の不一致」が論述として問われた。態度と行動の測定の具体性をそろえる「対応の原理」にふれると深い。"},{"id":"pluralistic","t":"多元的無知","en":"pluralistic ignorance","f":"social","s":"集団の多くの成員が、ある規範や意見を内心では受け入れていないのに、他の成員は受け入れていると誤って思い込み、結果としてその規範が維持されてしまう状態。傍観者効果の一因ともなる。","a":"集団の多くの成員が、内心ではある規範や意見を支持していないにもかかわらず、他の成員はそれを支持していると誤って推測し、その結果、誰も異を唱えずに規範が維持されてしまう状態をいう。たとえば、多くの学生が大量飲酒に抵抗を感じていても、周囲は楽しんでいると思い込み、自分も同調してしまう。緊急事態で周りの人が落ち着いて見えることから「たいしたことはない」と判断し、誰も援助しなくなる傍観者効果の一因ともされる。正確な情報を共有することが解消の手がかりとなる。","k":["内心","他の成員","誤","規範","傍観者効果","情報"],"p":"いじめの傍観や、学級の雰囲気など学校臨床の例と結びつけると論述で使える。"},{"id":"stereotype","t":"ステレオタイプと偏見","en":"stereotypes and prejudice","f":"social","s":"ステレオタイプは、ある集団の成員がもつと信じられている特徴についての固定的・単純化されたイメージ（認知）であり、偏見はそれに伴う否定的な態度、差別はそれにもとづく行動である。","a":"ステレオタイプとは、ある社会的集団の成員が共通にもつと信じられている特徴についての、単純化された固定的なイメージ（認知）である。それに否定的な感情を伴う態度を偏見、それにもとづく不当な行動を差別という。ディヴァインは、ステレオタイプは偏見の弱い人でも自動的に活性化されるが、それを判断に適用するかは意識的に統制できるとした。また、認知資源が不足していると統制が働きにくく、ステレオタイプが判断に適用されやすくなる。ステレオタイプは情報処理の労力を節約する働きをもつとも考えられている。","k":["集団","固定的","偏見","差別","自動的","認知資源"],"p":"公開問題では「ステレオタイプ化と認知的処理資源」が論述で問われた。活性化と適用の2段階を区別して書くのが要点。"},{"id":"social-identity","t":"社会的アイデンティティ理論","en":"social identity theory","f":"social","s":"タジフェルとターナーが提唱した、人は自分が所属する集団の成員性から自己概念の一部（社会的アイデンティティ）を得ており、肯定的な自己評価を保つために内集団を外集団より好ましく評価するとする理論。","a":"タジフェル（Tajfel, H.）とターナーが提唱した理論で、人は自分が所属する集団の成員であることから、自己概念の一部である社会的アイデンティティを得ていると考える。そして、肯定的な社会的アイデンティティを保つために、内集団を外集団よりも好ましく評価する内集団びいきが生じるとする。くじ引きのような意味のない基準で分けただけの集団でも、内集団の成員に多くの報酬を分配することを示した最小条件集団パラダイムの実験が、その根拠となった。集団間の葛藤や差別の理解に用いられる。","k":["タジフェル/Tajfel","社会的アイデンティティ","内集団","外集団","内集団びいき","最小条件集団"],"p":"自己カテゴリー化理論への発展や、集団間葛藤の解消（接触仮説）とあわせて整理する。"},{"id":"group-polarization","t":"集団極性化と集団思考","en":"group polarization / groupthink","f":"social","s":"集団極性化は、集団で討議した後の意思決定が、個人の当初の傾向よりも極端な方向に偏る現象。集団思考は、凝集性の高い集団で合意を優先するあまり、批判的な検討が抑えられて誤った決定に至る現象をいう。","a":"集団極性化とは、集団で話し合った後の意見や決定が、成員の当初の平均的な傾向と同じ方向に、より極端になる現象をいう。当初はより危険な選択に偏るリスキー・シフトとして報告されたが、慎重な方向に偏るコーシャス・シフトも生じる。集団思考は、ジャニスが政策決定の失敗例の分析から示したもので、凝集性が高く、外部から孤立し、強い指導者がいる集団で、全員一致を保とうとするあまり、異論が抑えられ、代替案の検討が不十分になり、誤った決定に至る現象である。","k":["討議/話し合","極端","リスキー・シフト","ジャニス","凝集性","異論"],"p":"対策（悪魔の代弁者を置く、外部の意見を入れる）にふれると応用的な論述になる。"},{"id":"social-facilitation","t":"社会的促進と社会的手抜き","en":"social facilitation / social loafing","f":"social","s":"社会的促進は、他者がいることで課題の遂行が促進される現象（ただし難しい課題では抑制される）。社会的手抜きは、集団で共同作業をするとき、一人あたりの努力量が低下する現象である。","a":"社会的促進とは、他者がその場にいることで課題の遂行が向上する現象で、トリプレットの自転車競技の観察などに始まる。ザイアンスは、他者の存在が覚醒水準を高め、その場で最も起こりやすい反応（優勢反応）を強めるため、よく慣れた易しい課題では成績が向上し、難しい課題では低下（社会的抑制）すると説明した。社会的手抜きは、綱引きのように集団で共同作業をするとき、人数が増えるほど一人あたりの努力量が低下する現象で、個人の貢献がわからないことなどが原因とされる。","k":["他者","促進","ザイアンス/Zajonc","優勢反応","社会的手抜き","努力"],"p":"手抜きを防ぐ条件（個人の貢献の可視化、課題の重要性）も添えられるとよい。"},{"id":"person-situation","t":"人間－状況論争","en":"person-situation controversy","f":"social","s":"行動を規定するのは個人の内的な特性か、それとも状況かをめぐる論争。ミシェルが、特性による行動の予測力が低く、行動の状況を越えた一貫性が乏しいと批判したことに始まり、相互作用論へと発展した。","a":"人の行動を規定するのは、その人の内的で安定したパーソナリティ特性なのか、それとも置かれた状況なのかをめぐる論争である。ミシェル（Mischel, W.）は1968年に、特性を測る検査で実際の行動を予測できる程度は低く（相関係数で.30程度）、異なる状況を通じた行動の一貫性は乏しいと指摘し、特性論を批判した。その後の議論を通じて、行動は個人と状況の相互作用によって決まるとする相互作用論が主流となり、ミシェルらは「もし〜ならば〜する」という状況と行動の安定したパターンに個人の特徴が表れるとするモデルを提唱した。","k":["特性","状況","ミシェル/Mischel","一貫性","相互作用","もし"],"p":"個人の一貫性は「状況ごとのパターンの一貫性」として現れる、という結論まで書けると十分。"},{"id":"type-trait","t":"類型論と特性論","en":"typology and trait theory","f":"social","s":"類型論は、一定の原理にもとづいて典型的な性格の型を設定し、個人をいずれかの型に当てはめて理解する立場。特性論は、性格を複数の特性の組合せとしてとらえ、その程度の違いで個人差を記述する立場である。","a":"パーソナリティの記述の2つの立場である。類型論は、体格や心理的な原理にもとづいて典型的な性格の型を設定し、個人をいずれかの型に分類して理解する立場で、クレッチマーの体格と気質の類型や、ユングの内向・外向のタイプ論などがある。全体像を直観的に把握しやすいが、中間の人をとらえにくく、型に当てはめすぎる危険がある。特性論は、性格を複数の特性の組み合わせとしてとらえ、その程度の違いで個人差を量的に記述する立場で、オールポート、キャッテル、アイゼンク、ビッグファイブなどがある。","k":["型","クレッチマー","タイプ論/ユング","特性","量的","ビッグファイブ"],"p":"両者の長所と短所を対にして書き、アイゼンクのように両者を統合した立場があることにもふれるとよい。"},{"id":"honor","t":"名誉の文化","en":"culture of honor","f":"social","s":"侮辱などによって自分や家族の名誉が傷つけられたとき、暴力を含む強い報復で応じることが規範として是認される文化。ニスベットとコーエンはアメリカ南部の暴力の多さをこの文化で説明した。","a":"自分や家族の名誉が侮辱などによって脅かされたとき、暴力を含む強い報復によって応じることが社会的に是認され、期待される文化をいう。ニスベットとコーエンは、アメリカ南部で口論にもとづく殺人が多いことを、家畜を主な財産とする牧畜経済にその起源をもつと説明した。盗まれやすい財産を守り、法の執行が十分でない環境では、侮辱を許さない「強い」評判をもつことが身を守る手段として適応的だったと考えられる。侮辱を受けた際に南部出身者のコルチゾールなどが上昇することを示した実験もある。","k":["名誉","侮辱","報復/暴力","ニスベット/コーエン","牧畜","適応"],"p":"公開問題では「その文化内で暴力が適応的な行動として成立していること」の理解が求められた。文化と環境の適応という視点で書く。"},{"id":"altruism","t":"利他行動と互恵性","en":"altruism and reciprocity","f":"social","s":"利他行動は、自分に損失があっても他者の利益になる行動。進化的には、血縁選択、直接の見返りによる互恵的利他主義、評判を介して第三者から返される間接互恵性によって、その成立が説明される。","a":"自分の損失を伴いながら他者の利益になる行動を利他行動という。進化の観点からは、一見不利なこの行動がなぜ広がったかが問題となり、遺伝子を共有する血縁者を助ける血縁選択（ハミルトン）、助けた相手から後で助け返される直接互恵性（トリヴァースの互恵的利他主義）が示された。さらに、人を助けると「よい人」という評判が高まり、その評判を見た第三者から助けられるという間接互恵性（アレクサンダー、ノヴァクとシグムンド）によって、見返りが直接返ってこない相手への利他行動も進化しうることが示された。","k":["損失","血縁選択","直接互恵性/互恵的利他主義","間接互恵性","評判","第三者"],"p":"公開問題では「利他行動が間接互恵性の成立によって進化しうること」が求められた。「情けは人のためならず」で説明する答案も多い。"},{"id":"self-construal","t":"文化的自己観","en":"cultural self-construal","f":"social","s":"マーカスと北山が提唱した、文化によって共有される自己についての考え方。欧米で優勢な、自己を他者から切り離された独自の存在とみる相互独立的自己観と、東アジアで優勢な、他者との関係の中で自己をとらえる相互協調的自己観がある。","a":"マーカス（Markus, H. R.）と北山忍が提唱した、ある文化の中で歴史的に形成され共有されている、自己とは何かについての考え方である。欧米の文化で優勢な相互独立的自己観では、自己は他者や状況から切り離された、独自の属性をもつ存在とみなされ、自分らしさを表現し独自性を主張することが重視される。東アジアの文化で優勢な相互協調的自己観では、自己は他者との関係の中に位置づけられ、周囲との調和や期待に応えることが重視される。感情、動機づけ、認知の文化差を説明する枠組みとなった。","k":["マーカス/北山","文化","相互独立的","相互協調的","他者との関係","調和"],"p":"心理療法の文化差（自己主張を目標とすることの適否など）を論じる際の根拠にもなる。"},{"id":"choice-pref","t":"選択による選好の変化","en":"choice-induced preference change","f":"social","s":"同程度に好ましい選択肢の一方を選ぶと、選んだものをより好ましく、選ばなかったものをより好ましくなく評価するようになる現象。ブレームが自由選択パラダイムで示し、認知的不協和の低減によって説明された。","a":"同じくらい好ましい2つの選択肢の一方を選んだ後に、選んだものをより好ましく、選ばなかったものをより好ましくなく評価するようになる現象をいう。ブレーム（Brehm, J. W.）が1956年に、評定、選択、再評定からなる自由選択パラダイムで示し、選ばなかった選択肢の長所や選んだ選択肢の短所という不協和な認知を低減しようとする働き（認知的不協和理論）によって説明された。選好は選択の原因であるだけでなく、選択の結果としても変化することを示す。のちに、この手続きには統計的な問題がありうるという方法論的な批判も出された。","k":["選","好ましく","ブレーム/Brehm","自由選択パラダイム","認知的不協和","方法論"],"p":"「好きだから選ぶ」だけでなく「選んだから好きになる」という逆方向の因果を示した点が要点。"},{"id":"social-comparison","t":"社会的比較","en":"social comparison","f":"social","s":"フェスティンガーが提唱した、人は客観的な基準がないとき、自分の意見や能力を他者と比較して評価するという考え。自分より優れた他者との上方比較と、劣った他者との下方比較がある。","a":"フェスティンガー（Festinger, L.）が1954年に提唱した理論で、人は自分の意見や能力を正しく評価したいという動機をもち、客観的な基準がないときには他者と比較することで評価すると考える。比較の相手には、自分と類似した他者が選ばれやすい。自分より優れた他者と比べる上方比較は、向上の動機を高める一方で自己評価を下げることがあり、自分より劣った他者と比べる下方比較は、脅威にさらされたときなどに自尊感情を守る働きをもつ。SNSの利用と抑うつとの関連の研究にも用いられる。","k":["フェスティンガー/Festinger","評価","他者と比較","類似","上方比較","下方比較"],"p":"学生相談の事例（「周りはちゃんとやっているのに」）の理解にも使える。"},{"id":"self-disclosure","t":"自己開示と自己呈示","en":"self-disclosure / self-presentation","f":"social","s":"自己開示は、自分自身についての情報を言葉によって他者にありのままに伝えること。自己呈示は、他者に特定の印象を与えるように、自分についての情報を選択して示すことをいう。","a":"自己開示とは、自分自身についての情報（考え、感情、経験など）を、言葉によって特定の他者にありのままに伝えることをいい、ジュラードが研究を進めた。自己開示は相手からの自己開示を引き出す返報性をもち、関係が深まるにつれて開示の幅と深さが増していく。心理的な健康とも関連する。これに対して自己呈示は、他者から望ましい印象をもたれるように、自分についての情報を選択的に示すことをいい、取り入り、自己宣伝、示範などの方略がある。失敗に備えて自ら不利な条件をつくるセルフ・ハンディキャッピングもその一種とされる。","k":["ありのまま","ジュラード","返報性","自己呈示","印象","セルフ・ハンディキャッピング"],"p":"心理療法における治療者の自己開示（是非と条件）を論じる際の基礎知識にもなる。"},{"id":"priming","t":"プライミング効果","en":"priming effect","f":"kiso","s":"先行して提示された刺激（プライム）の処理が、後続の刺激（ターゲット）の処理を無意識のうちに促進または抑制する現象。同じ刺激の反復による直接プライミングと、意味的に関連する刺激による間接プライミングがある。","a":"先行して提示された刺激（プライム）の処理が、後に提示される刺激（ターゲット）の処理に、本人の意識を伴わずに影響する現象をいう。同じ刺激を繰り返すと処理が速く正確になる直接（反復）プライミングと、「医者」の後に「看護師」の語彙判断が速くなるような、意味的に関連した刺激による間接（意味的）プライミングがある。後者は、意味記憶の中で概念が網の目のように結びつき、一つの概念の活性化が関連する概念に広がるとする活性化拡散モデルで説明される。反応時間や正答率の変化によって測定される。","k":["プライム","無意識/意識を伴わず","直接","間接/意味的","活性化拡散","反応時間"],"p":"実験で実証する方法（語彙判断課題、プライムとターゲットの関連の有無で反応時間を比較）まで説明できるようにしておく。"},{"id":"serial-position","t":"系列位置効果","en":"serial position effect","f":"kiso","s":"項目のリストを記憶して自由再生するとき、リストの最初の項目（初頭効果）と最後の項目（新近効果）の再生率が高く、中ほどの項目の再生率が低くなる現象。","a":"単語などのリストを一つずつ提示して覚えてもらい、順序を問わずに思い出してもらう（自由再生）と、リストの最初のほうの項目と最後のほうの項目の再生率が高く、中ほどの項目の再生率が低いU字型の曲線が得られる。最初のほうが高い初頭効果は、リハーサルの回数が多く長期記憶に転送されやすいため、最後のほうが高い新近効果は、短期記憶にまだ残っているためと説明される。再生までに妨害課題を挟むと新近効果だけが消えることは、短期記憶と長期記憶を区別する二重貯蔵モデルの根拠とされた。","k":["自由再生","初頭効果","新近効果","リハーサル","短期記憶","二重貯蔵"],"p":"二重貯蔵モデル（アトキンソンとシフリン）の証拠として位置づけると論述で使いやすい。"},{"id":"levels","t":"処理水準","en":"levels of processing","f":"kiso","s":"クレイクとロックハートが提唱した、記憶の保持は情報が処理される深さによって決まるという考え方。形態的・音韻的な浅い処理よりも、意味的な深い処理を受けた情報のほうがよく記憶される。","a":"クレイク（Craik, F. I. M.）とロックハートが1972年に提唱した考え方で、情報が記憶に残るかどうかは、短期記憶や長期記憶といった貯蔵庫の違いよりも、その情報がどのような深さで処理されたかによって決まるとする。文字の形に注目する形態的な処理や、音に注目する音韻的な処理は浅い処理であり、意味を考える意味的な処理は深い処理である。単語について「大文字か」「韻を踏むか」「文に当てはまるか」を判断させる実験で、意味的な判断をした単語ほど後の再認成績がよかった。","k":["クレイク/Craik","深さ","形態的","音韻的","意味的","再認"],"p":"自己に関連づけると記憶が促進される自己準拠効果も、処理水準の観点から説明される。"},{"id":"schema","t":"スキーマ","en":"schema","f":"kiso","s":"過去の経験から形成された、ある事柄についての構造化された知識の枠組み。新しい情報の知覚や理解、記憶を方向づけ、欠けた情報を補う一方、記憶の歪みも生じさせる。","a":"過去の経験をもとに形成された、ある対象や出来事についての構造化された知識の枠組みをいう。バートレットは、なじみのない文化の民話を繰り返し再生させると、話が自分の文化のスキーマに合うように省略され変形されていくことを示した。スキーマは、新しい情報をすばやく理解し、欠けた情報を補い、注意や記憶を方向づける働きをもつが、スキーマに合わない情報が見落とされたり、記憶が歪められたりする原因ともなる。出来事の典型的な順序についてのスキーマをスクリプトという。ベックの認知療法の「スキーマ」もこの考えに通じる。","k":["知識","枠組み","バートレット","歪","スクリプト","ベック"],"p":"基礎（認知心理学）と臨床（認知療法のスキーマ）をつなぐ概念として論じられる。"},{"id":"heuristics","t":"ヒューリスティック","en":"heuristics","f":"kiso","s":"必ず正解に至るとは限らないが、少ない労力ですばやく判断や意思決定を行うための簡便な方略。トヴェルスキーとカーネマンは、利用可能性、代表性、係留と調整のヒューリスティックとそれに伴うバイアスを示した。","a":"限られた時間や情報の中で、すばやく判断や意思決定を行うための簡便な方略をいい、手順を踏めば必ず正解に至るアルゴリズムと対比される。トヴェルスキーとカーネマンは、思い出しやすい事例ほど頻度が高いと判断する利用可能性ヒューリスティック、典型例に似ているほどそのカテゴリーに属すると判断する代表性ヒューリスティック（基準率の無視が生じる）、最初に示された数値に判断が引きずられる係留と調整のヒューリスティックを示した。多くの場合は有効だが、系統的な判断の誤り（バイアス）を生む。","k":["簡便","アルゴリズム","トヴェルスキー/カーネマン","利用可能性","代表性","バイアス"],"p":"臨床家の判断も同じバイアスを受ける（例：最近経験した事例に引きずられる）ことを、アセスメントの留意点として論じられる。"},{"id":"dual-process","t":"二重過程理論","en":"dual-process theory","f":"kiso","s":"人の思考や判断には、速く自動的で直観的な過程（システム1）と、遅く意識的で熟慮的な過程（システム2）の2種類があるとする理論。","a":"人の思考や判断、意思決定には、性質の異なる2つの過程があるとする考え方の総称である。一つは、速く、自動的で、努力を要さず、直観的に働く過程（システム1）であり、もう一つは、遅く、意識的で、努力を要し、論理的に熟慮する過程（システム2）である。カーネマンは、多くの判断はシステム1によって行われ、ヒューリスティックによるバイアスもそこから生じると論じた。説得の精緻化見込みモデルや、ステレオタイプの自動的な活性化と意識的な統制の区別なども、同じ発想にもとづいている。","k":["2","自動的","直観","熟慮","システム1","カーネマン"],"p":"社会心理学（ELM、ステレオタイプ）や臨床（自動思考と熟慮による検討）と横断的に結びつけられる概念。"},{"id":"autobiographical","t":"自伝的記憶","en":"autobiographical memory","f":"kiso","s":"自分の人生で経験した出来事についての記憶。自己の連続性やアイデンティティを支え、高齢者では青年期から成人前期の出来事が多く想起されるレミニセンス・バンプがみられる。","a":"自分自身の人生の中で経験した出来事についての記憶であり、エピソード記憶のうち、自己にとって意味をもつものをさす。過去から現在へと続く自己の連続性やアイデンティティを支え、他者との関係を築き、将来の行動の指針となる働きをもつ。乳幼児期の出来事をほとんど思い出せない幼児期健忘や、高齢者が人生を振り返ると10代から30歳前後の出来事を多く想起するレミニセンス・バンプが知られる。うつ病では具体的な出来事を想起しにくい概括化がみられ、回想法やナラティヴの理解の基礎ともなる。","k":["人生","エピソード記憶","アイデンティティ/連続性","幼児期健忘","レミニセンス・バンプ","うつ病"],"p":"臨床（回想法、うつ病の概括的記憶、トラウマ記憶）との接点を一つ挙げると論述の材料になる。"},{"id":"reinforcement-schedule","t":"強化スケジュール","en":"schedules of reinforcement","f":"kiso","s":"オペラント条件づけで、どのような規則で強化を与えるかの計画。毎回強化する連続強化と、一部だけ強化する部分強化（定率・変率・定間隔・変間隔）があり、部分強化された行動は消去されにくい。","a":"オペラント条件づけにおいて、どのような規則にもとづいて行動に強化を与えるかを定めたものをいう。反応のたびに強化する連続強化は行動の獲得を速めるが、強化をやめると消去されやすい。一部の反応だけを強化する部分強化には、一定回数ごとの定率、平均回数のまわりでランダムな変率、一定時間後の最初の反応に与える定間隔、時間がランダムな変間隔のスケジュールがある。部分強化で学習された行動は、連続強化の場合よりも消去されにくい（部分強化効果）。変率スケジュールはギャンブルへの依存の理解にも用いられる。","k":["オペラント","連続強化","部分強化","変率","消去","ギャンブル"],"p":"臨床では、問題行動に時々注目を与えることが行動を維持してしまう例（間欠強化）として説明できる。"},{"id":"generalization","t":"般化と弁別","en":"generalization and discrimination","f":"kiso","s":"般化は、条件づけられた刺激と似た刺激にも同じ反応が生じること。弁別は、似ていても強化される刺激とされない刺激を区別し、異なる反応をするようになることをいう。","a":"般化とは、ある刺激に対して条件づけが成立すると、それと類似した刺激に対しても同じ反応が生じることをいう。類似度が高いほど反応は強く、類似度に応じて反応が弱まる勾配（般化勾配）がみられる。ワトソンのアルバート坊やの実験では、白ネズミへの恐怖が白いウサギや毛皮にまで広がった。弁別とは、類似した刺激のうち、一方は強化され他方は強化されないといった経験を通じて、それらを区別して異なる反応をするようになることをいう。恐怖症の広がりや、治療で獲得した行動を日常場面に般化させることの理解に重要である。","k":["類似","同じ反応","般化勾配","アルバート","弁別","恐怖"],"p":"治療効果の「般化」（面接室で学んだことを生活場面へ）の意味でも使われることを添えると臨床的。"},{"id":"maslow","t":"欲求階層説","en":"hierarchy of needs","f":"kiso","s":"マズローが提唱した、人間の欲求は生理的欲求、安全の欲求、所属と愛の欲求、承認の欲求、自己実現の欲求の階層をなし、下位の欲求がある程度満たされると上位の欲求が現れるとする説。","a":"マズロー（Maslow, A. H.）が提唱した動機づけの理論で、人間の欲求は、生理的欲求、安全の欲求、所属と愛の欲求、承認（自尊）の欲求、自己実現の欲求の5段階からなる階層をなし、下位の欲求がある程度満たされると、より上位の欲求が優勢になるとした。下位の4つは欠乏を満たそうとする欠乏欲求、自己実現は成長欲求とされる。人間性心理学の基盤となったが、階層の順序を支持する実証的な証拠は乏しく、欲求は同時に働きうること、個人主義的な文化を前提としていることなどの批判がある。","k":["マズロー/Maslow","生理的欲求","自己実現","欠乏欲求","人間性心理学","批判"],"p":"公開問題では「概要の説明と批判的検討」が問われた。実証研究と文化の観点から限界を2点以上挙げられるようにしておく。"},{"id":"joint-attention","t":"共同注意","en":"joint attention","f":"hattatsu","s":"他者と同じ対象に注意を向け、その対象を共有していることを互いに理解している状態。生後9〜12か月ごろから視線追従や指さしとして現れ、自己・他者・対象の三項関係を基盤に言語やコミュニケーションの発達を支える。","a":"他者と同じ対象に注意を向け、しかもその対象に一緒に注意を向けていることを互いに理解している状態をいう。生後9〜12か月ごろになると、乳児は大人の視線の先を追ったり（視線追従）、指さしで興味のある物を示して大人と見たいものを共有しようとしたりする。それまでの「自分と人」「自分と物」という二項関係から、「自分・他者・物」の三項関係が成立したことを示し、言語の獲得や心の理論の発達の基盤とされる。自閉スペクトラム症の子どもでは、共同注意の発達の遅れが早期の特徴の一つとされる。","k":["同じ対象","9","視線","指さし","三項関係","自閉スペクトラム症"],"p":"発達相談の事例（言葉の遅れ）で、アセスメントの観点として挙げられると強い。"},{"id":"social-referencing","t":"社会的参照","en":"social referencing","f":"hattatsu","s":"乳児が、どう行動すべきかわからないあいまいな状況で、養育者などの表情や声の調子を手がかりにして自分の行動を決めること。生後1年ごろからみられる。","a":"乳児が、初めて出会う物や人など、どのように振る舞えばよいかわからないあいまいな状況で、養育者などの信頼できる他者の表情や声の調子を手がかりにして、自分の行動を調整することをいう。生後1年前後からみられる。浅い段差に見えるガラス板（視覚的断崖）の前で、母親が笑顔を見せると乳児は渡り、恐怖の表情を見せると渡らないことを示した実験が知られる。他者の感情を読み取り、それを状況の理解に用いる能力の表れであり、共同注意とともに対人的なコミュニケーションの発達の基盤となる。","k":["あいまい","養育者","表情","1年","視覚的断崖","共同注意"],"p":"愛着（安全基地）と社会的参照の関係を説明できると、発達の論述に厚みが出る。"},{"id":"empty-nest","t":"空の巣症候群","en":"empty nest syndrome","f":"hattatsu","s":"子どもが独立して家を離れた後に、親（とくに子育てを中心に生きてきた母親）が経験する喪失感や抑うつ、無気力などの状態。正式な診断名ではなく、中年期のアイデンティティの再構築の課題と関連する。","a":"子どもが進学や就職、結婚などで独立し家を離れた後に、親が経験する喪失感、寂しさ、抑うつ、無気力などの状態をいう。とくに子育てを生活の中心とし、親としての役割に自分の存在意義を見いだしてきた人に生じやすいとされる。正式な診断名ではない。中年期は、親役割の縮小、夫婦関係の見直し、自身の老いや親の介護などが重なる時期であり、空の巣症候群は、中年期のアイデンティティの再構築という発達課題と関連している。一方で、子どもの独立を解放感をもって迎える親も多い。","k":["独立","喪失感","抑うつ","親としての役割/親役割","中年期","アイデンティティ"],"p":"家族ライフサイクル（子どもの巣立ちの段階）や中年期の危機と結びつけて説明するとよい。"},{"id":"industry","t":"勤勉性 対 劣等感","en":"industry versus inferiority","f":"hattatsu","s":"エリクソンの心理社会的発達理論における学童期の心理社会的危機。学校や仲間との活動の中で、努力して物事をやり遂げる勤勉性を身につけるか、うまくいかない経験から劣等感を抱くかが課題となり、有能感の獲得につながる。","a":"エリクソンの心理社会的発達理論の第4段階で、おおむね学童期（6〜12歳ごろ）にあたる心理社会的危機である。子どもは学校での学習や仲間との活動の中で、社会で役立つ知識や技能を身につけ、努力して物事をやり遂げることに喜びを感じる勤勉性を育てる。一方、失敗や周囲との比較が重なると、自分は何をしてもうまくできないという劣等感を抱く。この危機を肯定的に乗り越えることで、有能感（適格性）という人間的な強さが獲得される。学習のつまずきや発達障害の二次障害の理解にも関連する。","k":["エリクソン","学童期","勤勉性","劣等感","有能感/適格","仲間"],"p":"前後の段階（自主性対罪悪感、同一性対同一性拡散）とのつながりを押さえておく。"},{"id":"object-permanence","t":"対象の永続性","en":"object permanence","f":"hattatsu","s":"物が見えなくなっても存在し続けていることの理解。ピアジェは感覚運動期の後半（8〜12か月ごろ）に獲得されるとしたが、期待違反法による研究ではより早い時期から理解の兆しが示されている。","a":"物が視界から消えたり隠されたりしても、存在し続けていることの理解をいう。ピアジェは、生後間もない乳児は布で隠されたおもちゃを探そうとしないが、感覚運動期の後半（8〜12か月ごろ）になると隠された物を探すようになることから、この時期に対象の永続性が獲得されるとした。ただし、Aの場所に隠した物を目の前でBに移しても再びAを探すA-not-Bエラーがしばらく残る。一方、ベイヤールジョンらは、乳児が起こりえない事象をより長く注視する期待違反法を用いて、より早い時期から理解の兆しがあることを示した。","k":["存在し続け","ピアジェ","感覚運動期","A-not-B","期待違反法","8"],"p":"研究法（注視時間を指標とする期待違反法）の違いによって結論が変わる例として論じることもできる。"},{"id":"conservation","t":"保存","en":"conservation","f":"hattatsu","s":"物の見かけの形や配置が変わっても、その数や量、重さなどは変わらないことの理解。ピアジェは具体的操作期に獲得されるとし、前操作期の子どもは中心化や可逆性の欠如のために保存課題に失敗するとした。","a":"物の見かけの形や配置が変化しても、加えたり取り去ったりしない限り、その数、液量、重さ、体積などは変わらないことの理解をいう。同じ量の水を細長いコップに移すと、前操作期の子どもは「水が増えた」と答える。ピアジェは、これは水面の高さなど目立つ一つの次元だけに注目する中心化と、元に戻せば同じになるという可逆性の理解の欠如によるとし、具体的操作期（7歳ごろ）になると保存が獲得されるとした。数、量、重さ、体積の順に、保存の獲得の時期にはずれがみられる。","k":["見かけ","数","ピアジェ","前操作期","中心化","可逆性"],"p":"課題の問い方によって成績が変わるという批判的研究（質問の繰り返しの影響など）も知っておくと応用が利く。"},{"id":"critical-period","t":"臨界期と敏感期","en":"critical period / sensitive period","f":"hattatsu","s":"臨界期は、ある経験が発達に決定的な影響をもつ限られた時期で、その時期を過ぎると同じ経験の効果が得られにくい。より緩やかに、経験の影響を受けやすい時期を敏感期という。","a":"発達の中で、ある経験がその後の発達に決定的な影響を与える限られた時期を臨界期という。ローレンツは、孵化直後のハイイロガンのひなが最初に見た動く対象を追従するようになる刻印づけ（刷り込み）が、ごく短い時期にしか成立しないことを示した。人間の発達では、その時期を過ぎると学習が不可能になるほど厳密な期間は少なく、経験の影響を特に受けやすい時期として敏感期という語が用いられることが多い。言語や視覚の発達、愛着の形成などで論じられ、早期の環境の重要性と、後の回復可能性の両面から議論される。","k":["限られた時期","決定的","ローレンツ","刻印づけ/刷り込み","敏感期","言語"],"p":"「早期の経験がすべてを決める」と書かず、可塑性や回復可能性にもふれるのが臨床的に適切。"},{"id":"sst-aging","t":"社会情動的選択性理論","en":"socioemotional selectivity theory","f":"hattatsu","s":"カーステンセンが提唱した、人生の残り時間が限られていると認識されると、知識の獲得よりも情緒的に満たされる目標が重視され、親しい少数の人との関係が選択されるようになるとする理論。","a":"カーステンセン（Carstensen, L. L.）が提唱した、加齢に伴う社会的関係や動機づけの変化を説明する理論である。人は、将来の時間が長く残されていると感じるときには、新しい知識や経験の獲得を重視するが、残された時間が限られていると認識すると、情緒的に満たされることを重視し、親しく意味のある少数の人との関係を選んで維持するようになる。高齢者の社会的ネットワークの縮小は、喪失だけでなく、このような能動的な選択の結果でもあると考える。高齢者が肯定的な情報に注意を向けやすいポジティビティ効果とも関連する。","k":["カーステンセン/Carstensen","残り時間/残された時間","情緒","親しく","選択","ポジティビティ効果"],"p":"バルテスのSOC理論とあわせて、老年期の適応を肯定的にとらえる理論として整理する。"},{"id":"central-tendency","t":"代表値","en":"measure of central tendency","f":"kenkyu","s":"データの分布の中心的な位置を一つの値で表す指標。平均値、中央値、最頻値があり、尺度の水準や分布の形（外れ値やゆがみ）に応じて使い分ける。","a":"データの分布の中心がどこにあるかを一つの値で要約する指標である。すべての値の合計をデータ数で割った平均値、値を大きさの順に並べたときの中央の値である中央値、最も多く出現する値である最頻値がある。平均値はすべての値の情報を用いるが、極端な外れ値の影響を受けやすい。年収のように分布が大きくゆがんでいる場合は、中央値のほうが中心をよく表す。また、名義尺度では最頻値、順序尺度では中央値が用いられるなど、尺度の水準によって使える代表値が異なる。散布度とあわせて報告する。","k":["中心","平均値","中央値","最頻値","外れ値","尺度"],"p":"「どの代表値を、なぜ使うか」を一言で説明できることが求められる。"},{"id":"dispersion","t":"散布度","en":"measure of dispersion","f":"kenkyu","s":"データのばらつきの大きさを表す指標。範囲、四分位範囲、分散、標準偏差などがある。標準偏差は分散の正の平方根で、元のデータと同じ単位でばらつきを表す。","a":"データが代表値のまわりにどの程度ばらついているかを表す指標である。最大値と最小値の差である範囲、中央の50％のデータの範囲を示す四分位範囲、各値と平均値との差（偏差）を2乗して平均した分散、分散の正の平方根である標準偏差などがある。標準偏差は元のデータと同じ単位で表されるため解釈しやすい。平均値が同じでも散布度が大きく異なる集団はありうるため、代表値と散布度はあわせて報告する必要がある。正規分布では、平均値±1標準偏差の範囲におよそ68％のデータが含まれる。","k":["ばらつ","範囲","分散","標準偏差","同じ単位","68"],"p":"標準偏差（個々のデータのばらつき）と標準誤差（推定値のばらつき）の違いは頻出の論点。"},{"id":"standard-error","t":"標準誤差","en":"standard error","f":"kenkyu","s":"標本から求めた統計量（平均値など）が、標本ごとにどの程度ばらつくかを示す指標で、その統計量の標本分布の標準偏差にあたる。平均値の標準誤差は標準偏差を標本の大きさの平方根で割って求める。","a":"母集団から標本を何度も取り出して平均値などの統計量を計算すると、その値は標本ごとにばらつく。そのばらつき、すなわち統計量の標本分布の標準偏差を標準誤差という。平均値の標準誤差は、標本の標準偏差を標本の大きさの平方根で割って求められ、標本が大きいほど小さくなる。標準誤差は、推定の精度を表し、信頼区間の算出や統計的検定に用いられる。個々のデータのばらつきを表す標準偏差とは異なる概念であり、論文などでは両者を区別して報告する必要がある。","k":["標本","ばらつ","標本分布","平方根","信頼区間","標準偏差"],"p":"公開問題で語句として問われた。「標準偏差との違い」を一文入れるのが合格答案の条件と考えておく。"},{"id":"ci","t":"信頼区間","en":"confidence interval","f":"kenkyu","s":"母集団の値（母数）が含まれると推定される範囲を、一定の信頼度で示したもの。95％信頼区間は、同じ手続きで区間を何度も求めたときに、その95％が真の値を含むことを意味する。","a":"標本から母集団の平均値などの値（母数）を推定するとき、一つの値で示す点推定に対し、真の値が含まれると考えられる範囲を示すのが区間推定であり、その範囲を信頼区間という。95％信頼区間は、同じ手続きで標本抽出と区間の計算を繰り返したとき、そのうち95％の区間が真の値を含むという意味であり、「この区間に真の値がある確率が95％」という意味ではない点に注意が必要である。区間の幅は標準誤差に依存し、標本が大きいほど狭くなる。効果量とその信頼区間の報告が推奨されている。","k":["母数","範囲","95","区間推定","標準誤差","効果量"],"p":"p値だけでなく効果量と信頼区間を報告するという、近年の統計の報告の流れと結びつけて書く。"},{"id":"repeated","t":"反復測定デザイン","en":"repeated-measures design","f":"kenkyu","s":"同じ実験参加者に、すべての条件を繰り返し実施して測定する研究デザイン（参加者内計画）。個人差の影響を統制でき少人数で検定力を確保できるが、順序効果やキャリーオーバー効果への対処が必要となる。","a":"同じ実験参加者を、すべての実験条件のもとで繰り返し測定する研究デザインであり、参加者内計画（被験者内計画）ともいう。条件ごとに別の参加者を割り当てる参加者間計画に比べ、個人差による変動を統制できるため、少ない参加者で高い検定力が得られる。介入の前後や経過を追う測定にも用いられる。一方、練習や疲労による順序効果や、前の条件の影響が後の条件に持ち越されるキャリーオーバー効果が生じうるため、条件の順序を参加者間で入れ替えるカウンターバランスなどの工夫が必要となる。分析には反復測定の分散分析などを用いる。","k":["同じ","参加者内","個人差","検定力","順序効果/キャリーオーバー","カウンターバランス"],"p":"参加者間計画との長所・短所の比較として問われたときに対応できるようにしておく。"},{"id":"carryover","t":"キャリーオーバー効果","en":"carryover effect","f":"kenkyu","s":"先行する条件や質問の影響が、後の条件や質問への反応に持ち越される現象。実験では前の処理の効果が残ること、質問紙では前の質問への回答が後の質問の回答を方向づけることをいう。","a":"先に経験した条件や質問の影響が、後の測定に持ち越されて結果を歪める現象をいう。反復測定の実験では、前の条件で用いた薬物の効果や、学習した方略が後の条件の成績に影響する場合がこれにあたる。質問紙調査では、たとえば「最近の政治の不祥事」について尋ねた直後に「政治への信頼」を尋ねると、信頼の評定が低くなるように、前の質問が後の質問に回答する際の文脈となって回答を方向づける。条件の順序のカウンターバランス、条件間に十分な間隔をおくこと、質問の配置の工夫などによって対処する。","k":["先","持ち越","反復測定","質問紙","文脈","カウンターバランス"],"p":"具体例を3つ挙げられるようにしておく（実験の順序、質問紙の項目順、教育評価の印象の持ち越しなど）。"},{"id":"double-barreled","t":"ダブルバーレル質問","en":"double-barreled question","f":"kenkyu","s":"一つの質問の中に2つ以上の論点が含まれているため、回答者がどちらに答えればよいかわからず、回答の意味が解釈できなくなる質問。質問紙作成（ワーディング）で避けるべき誤りの一つ。","a":"一つの質問文の中に2つ以上の論点が含まれている質問をいう。たとえば「あなたは学校の先生や友人に満足していますか」という質問では、先生には満足しているが友人には満足していない人は回答に困り、得られた回答が何を意味するのか解釈できなくなる。質問紙の言葉づかい（ワーディング）で避けるべき誤りの一つであり、論点ごとに質問を分ける必要がある。ほかに、特定の回答に導く誘導的な質問、二重否定、あいまいな語や専門用語の使用、社会的望ましさの影響を受けやすい表現なども注意点となる。","k":["2つ以上","論点","解釈","ワーディング","誘導","二重否定"],"p":"ワーディングの留意点を「具体例つき」で複数挙げられるように準備しておく。"},{"id":"sens-spec","t":"感度と特異度","en":"sensitivity and specificity","f":"kenkyu","s":"検査の判別の性能を表す指標。感度は、実際にその状態にある人を検査で陽性と正しく判定する割合、特異度は、その状態にない人を陰性と正しく判定する割合である。","a":"スクリーニング検査などの判別の精度を表す指標である。感度は、実際にその疾患や状態にある人のうち、検査で陽性と判定される人の割合であり、見落としの少なさを表す。特異度は、その状態にない人のうち、検査で陰性と判定される人の割合であり、誤って陽性とする少なさを表す。カットオフ値を下げれば感度は上がるが特異度は下がるという関係にあり、両者の関係はROC曲線で示される。また、陽性と判定された人が本当にその状態にある割合（陽性的中率）は、集団の有病率によって大きく変わる。","k":["陽性","陰性","見落とし","カットオフ","ROC","有病率"],"p":"認知症やうつ病のスクリーニング検査の結果を解釈する際の留意点として、臨床の論述にも使える。"},{"id":"dif","t":"差異項目機能","en":"differential item functioning","f":"kenkyu","s":"測定しようとする能力や特性が同じ水準であるにもかかわらず、性別や文化などの集団によって、ある項目への正答率や反応の確率が異なること。テストの公平性を損なう項目の検出に用いられる。","a":"テストや尺度のある項目について、測定しようとしている能力や特性の水準が同じ受検者どうしであっても、性別、民族、言語、文化などの所属集団によって、正答率や特定の反応の確率が異なることをいう。単に集団間で平均点が異なることとは区別される。たとえば、特定の文化に固有の知識を前提とする項目は、能力が同じでもその文化に属さない受検者に不利に働く。DIFを示す項目はテストの公平性や妥当性を損なうため、マンテル・ヘンツェル法や項目反応理論にもとづく方法で検出し、修正や削除を検討する。","k":["水準が同じ/同じ水準","集団","正答率","公平性","項目反応理論","マンテル"],"p":"心理検査の翻訳・文化適応（日本版の作成）の論点とも結びつけられる。"},{"id":"mtmm","t":"多特性多方法行列","en":"multitrait-multimethod matrix","f":"kenkyu","s":"キャンベルとフィスクが提唱した、複数の特性を複数の方法で測定し、その相関を一覧にした行列。同じ特性を異なる方法で測った相関が高いこと（収束的妥当性）と、異なる特性間の相関が低いこと（弁別的妥当性）を検討する。","a":"キャンベル（Campbell, D. T.）とフィスクが1959年に提唱した、構成概念妥当性を検討するための方法である。複数の特性（例：不安と抑うつ）を、複数の方法（例：自己評定と他者評定）で測定し、すべての組み合わせの相関を一つの行列に整理する。同じ特性を異なる方法で測った相関が高ければ収束的妥当性が、異なる特性間の相関が低ければ弁別的妥当性が支持される。また、同じ方法で測ったというだけで異なる特性間の相関が高くなる場合、測定方法そのものによる変動（方法の分散）の影響が示唆される。","k":["キャンベル/Campbell","複数の特性","複数の方法","収束的妥当性","弁別的妥当性","方法"],"p":"妥当性の分類（収束的・弁別的）とセットで説明する。"},{"id":"item-analysis","t":"項目分析","en":"item analysis","f":"kenkyu","s":"テストを構成する各項目の性能を検討する分析。項目の難易度（正答率）、上位群と下位群の正答率の差などによる識別力（G-P分析、項目－全体相関）、誤答選択肢の働きなどを確認し、不適切な項目を修正・削除する。","a":"テストや尺度を構成する個々の項目が、測定の目的に照らして適切に働いているかを検討する分析である。学力テストでは、各項目の正答率（通過率）から難易度を確認し、正答率が極端に高すぎる、あるいは低すぎる項目を見直す。次に、テスト全体の得点の上位群と下位群で正答率を比較するG-P分析や、項目得点と全体得点との相関（項目－全体相関）によって、能力の高い人と低い人を区別できるかという識別力を確認する。さらに、多肢選択式では誤答の選択肢が機能しているかも検討し、不適切な項目を修正・削除する。","k":["項目","正答率","難易度","G-P分析","識別力","項目－全体相関/項目-全体相関"],"p":"公開問題で論述として問われた。「難易度・識別力・選択肢・信頼性への影響（α係数）」の4点を具体的に書けると十分。"},{"id":"irt","t":"項目反応理論","en":"item response theory","f":"kenkyu","s":"受検者の潜在的な能力と、各項目の困難度や識別力などの特性とから、その項目に正答する確率を数理モデルで表すテスト理論。受検者集団に依存しない項目の特性の推定や、適応型テストを可能にする。","a":"受検者がある項目に正答する確率を、受検者の潜在的な能力（特性）と、項目の困難度、識別力、当て推量などの項目の特性との関数として数理モデルで表すテスト理論である。能力と正答確率の関係は項目特性曲線で示される。素点にもとづく古典的テスト理論では、項目の難易度が受検者集団に依存するのに対し、項目反応理論では、項目の特性と受検者の能力を同じ尺度上で推定できる。これにより、異なるテストの得点の比較（等化）や、受検者の回答に応じて次の項目を選ぶ適応型テストが可能になる。","k":["正答する確率","潜在","困難度","識別力","項目特性曲線","適応型テスト"],"p":"古典的テスト理論との違いを一文で言えるようにしておく。"},{"id":"nrt-crt","t":"集団準拠評価と目標準拠評価","en":"norm-referenced and criterion-referenced assessment","f":"kenkyu","s":"集団準拠評価（相対評価）は、ある個人の成績を所属集団の中での相対的な位置によって評価する方法。目標準拠評価（絶対評価）は、あらかじめ定めた目標や基準にどの程度到達したかによって評価する方法である。","a":"集団準拠評価（ノルム準拠評価、相対評価）は、個人の成績を、所属する集団や標準化された集団の中での相対的な位置によって評価する方法であり、偏差値や順位、パーセンタイルで表される。入学試験のように選抜が目的の場合に適するが、全員が努力して成績が向上しても評価が上がらないことがある。目標準拠評価（クライテリオン準拠評価、絶対評価）は、あらかじめ定めた学習目標や基準にどの程度到達したかによって評価する方法であり、何ができて何ができないかが明らかになるため、指導の改善に役立つ。","k":["相対的な位置/相対評価","偏差値","選抜","目標","到達","指導"],"p":"公開問題では2回にわたって問われた形式（テストの違い／評価の違い）。具体例（模試の偏差値と、漢字テストの合格基準など）を対比させて書く。"},{"id":"correlation","t":"相関係数","en":"correlation coefficient","f":"kenkyu","s":"2つの変数の間の直線的な関係の強さと方向を、−1から＋1の値で表す指標。ピアソンの積率相関係数が代表的であり、相関があっても因果関係があるとは限らない。","a":"2つの量的な変数の間の直線的な関係の強さと方向を表す指標であり、一般にピアソンの積率相関係数を用いる。値は−1から＋1の範囲をとり、正の値は一方が大きいほど他方も大きい関係、負の値は一方が大きいほど他方が小さい関係を示し、0に近いほど直線的な関係が弱い。曲線的な関係はとらえられず、外れ値や測定範囲の制限（選抜された集団）の影響を受ける。順序尺度のデータにはスピアマンの順位相関係数を用いる。相関があっても、因果関係があるとは限らない点に注意が必要である。","k":["直線的","−1/-1","ピアソン","外れ値","スピアマン","因果"],"p":"散布図を描いて確認することの重要性、交絡（擬似相関）とあわせて整理する。"},{"id":"scale-level","t":"尺度水準","en":"levels of measurement","f":"kenkyu","s":"スティーヴンスが示した測定値の性質による分類。分類のみを表す名義尺度、順序を表す順序尺度、等間隔の目盛りをもつ間隔尺度、絶対的な原点をもつ比率尺度があり、使える統計的手法が異なる。","a":"スティーヴンス（Stevens, S. S.）が示した、測定によって得られる数値がもつ性質にもとづく分類である。性別や血液型のように区別のためだけに数値を割り当てる名義尺度、順位のように大小の順序のみを表す順序尺度、温度（摂氏）のように目盛りの間隔が等しいが絶対的な原点をもたない間隔尺度、身長や反応時間のように絶対的な原点をもち比率に意味がある比率尺度がある。水準が上がるほど適用できる統計的手法が増える。心理尺度の得点は厳密には順序尺度だが、間隔尺度とみなして分析されることが多い。","k":["スティーヴンス/Stevens","名義尺度","順序尺度","間隔尺度","比率尺度","統計"],"p":"リッカート法の得点を間隔尺度として扱うことの是非まで論じられると研究法の理解が深いことを示せる。"},{"id":"standard-score","t":"標準得点と偏差値","en":"standard score / T-score","f":"kenkyu","s":"個々の得点を、集団の平均値からの差を標準偏差を単位として表した値。平均0・標準偏差1のz得点を変換し、平均50・標準偏差10としたものが偏差値、平均100・標準偏差15としたものが偏差IQである。","a":"異なるテストや尺度の得点を比較できるように、個人の得点が集団の平均値からどれだけ離れているかを、標準偏差を単位として表した得点である。得点から平均値を引き、標準偏差で割ったものをz得点（平均0、標準偏差1）という。z得点を10倍して50を加えたものが偏差値（T得点、平均50、標準偏差10）であり、15倍して100を加えたものがウェクスラー式知能検査などの偏差IQである。分布が正規分布に近ければ、標準得点から集団の中でのおおよその位置（パーセンタイル）がわかる。","k":["平均値","標準偏差","z得点","偏差値","偏差IQ","正規分布"],"p":"比率IQと偏差IQの違い、偏差値60が上位約16％にあたることなど、具体的な数値で説明できると強い。"},{"id":"sampling","t":"標本抽出","en":"sampling","f":"kenkyu","s":"研究の対象とする母集団から、実際に調査する標本を選び出すこと。母集団の全員が等しい確率で選ばれる無作為抽出によって代表性が確保されるが、心理学研究では便宜的な標本が多く、一般化に限界がある。","a":"研究の関心の対象となる母集団の全体を調べることは難しいため、その一部である標本を選び出して調べ、母集団について推測する。母集団のすべての成員が等しい確率で選ばれる無作為抽出（単純無作為抽出、層化抽出、多段抽出など）は、標本の代表性を確保し、統計的推測の前提となる。しかし心理学の研究では、大学生など協力を得やすい人を対象とする便宜的抽出が多く、結果の一般化には限界がある。なお、標本を条件に振り分ける無作為割り付け（内的妥当性に関わる）とは区別される。","k":["母集団","標本","無作為抽出","代表性","便宜的","無作為割り付け"],"p":"「無作為抽出（外的妥当性）」と「無作為割り付け（内的妥当性）」の区別は頻出の論点。"},{"id":"omnipotence","t":"万能感","en":"omnipotence","f":"seishin","s":"自分の願望や思考がそのまま現実を動かし、世界を思いどおりにできるという感覚。乳児期の正常な体験とされる一方、成人では現実の限界や無力感を否認する防衛として現れることがある。","a":"自分の願望や思考がそのまま現実を左右し、世界を思いどおりにできるという感覚をいう。フロイトは、願望と現実が区別されていない幼児や原始的な思考の特徴として「思考の万能」を論じた。ウィニコットは、乳児の欲求にほどよく応える母親のもとで乳児が自分が世界を創り出したかのような錯覚（万能感）を体験し、それが徐々に脱錯覚されることで現実を受け入れていくとした。成人では、無力感や依存を否認する躁的防衛や自己愛的な防衛として現れ、治療では現実の限界を受け入れる過程が課題となる。","k":["願望","思いどおり","思考の万能","ウィニコット","脱錯覚","防衛"],"p":"正常な発達の一段階としての万能感と、病理的な防衛としての万能感の両面を書くのが要点。"},{"id":"reality-testing","t":"現実検討","en":"reality testing","f":"seishin","s":"自分の内的な体験（思考・空想・感情）と外的な現実とを区別し、現実を客観的に判断する自我の機能。精神病水準では障害され、神経症水準や境界水準では基本的に保たれるとされる。","a":"自分の内面で生じている思考や空想、感情と、外界の現実とを区別し、現実を客観的に認識して判断する自我の機能をいう。フロイトの現実原則に由来する。現実検討が障害されると、幻覚や妄想のように内的な体験が現実と混同される。カーンバーグはパーソナリティ構造を神経症水準・境界水準・精神病水準に分け、現実検討は精神病水準で障害され、他の水準では基本的に保たれるとした。アセスメントでは面接での応答やロールシャッハ・テストの形態水準などから評価し、心理療法の方法や深さを選ぶ判断材料となる。","k":["内的","区別","自我","カーンバーグ","精神病水準","ロールシャッハ/形態水準"],"p":"公開問題では「心理療法における現実検討能力のアセスメントの意義」が問われた。表現的な心理療法と支持的な心理療法の選択に関わることを書く。"},{"id":"enactment","t":"エナクトメント","en":"enactment","f":"seishin","s":"治療関係の中で、クライエントと治療者双方の無意識的な葛藤や関係のパターンが、言葉ではなく相互的な行動として実演されること。治療者もそこに巻き込まれており、事後にそれを理解することが治療的に用いられる。","a":"精神分析的心理療法の中で、クライエントと治療者の双方の無意識的な葛藤や内的な対象関係が、言葉による表現の代わりに、相互的なやりとりや行動として実演されることをいう。ジェイコブズらが論じた。治療者は気づかないうちにその役割に引き込まれており、たとえば普段は守っている面接時間を延長してしまうといった形で現れる。投影同一化が主にクライエントの心的な機制として記述されるのに対し、エナクトメントは二者の相互作用として生じる出来事を強調する。事後にその意味を吟味し理解することが、治療の重要な手がかりとなる。","k":["無意識","双方","行動","実演","投影同一化","相互作用"],"p":"博士後期の公開問題では投影同一化との異同が問われた。「心の中の機制か、二者の出来事か」という軸で比較すると書きやすい。"},{"id":"psychic-reality","t":"心的現実","en":"psychic reality","f":"seishin","s":"外的・物質的な現実とは別に、個人の心の中で現実として体験され、その人の感情や行動を規定している無意識の願望や空想の世界。フロイトは神経症の理解において、物質的現実と同等の重みをもつとした。","a":"外的な出来事や物質的な現実とは区別される、個人の心の中で現実として体験され、その人の感情や行動を実際に規定している、無意識の願望や空想の世界をいう。フロイトは当初、神経症の原因を幼児期の実際の性的被害に求めたが、のちに患者の語る出来事には空想が含まれていると考えるようになり、空想も心にとっては現実と同等の効果をもつとして心的現実の概念を提示した。心理療法では、語られた内容の事実関係を判定するよりも、それがクライエントにとってどのような意味をもつのかを理解することが重視される。ただし、実際の被害を空想とみなす誤りには注意を要する。","k":["物質的","心の中","空想","フロイト","意味","被害"],"p":"トラウマ臨床との関係（実際の被害を否認してはならない）にふれると、現代的でバランスのよい答案になる。"},{"id":"impasse","t":"治療の行き詰まり","en":"therapeutic impasse","f":"seishin","s":"心理療法の過程が進展しなくなり、治療者とクライエントがともに膠着状態に陥ること。抵抗や陰性治療反応、転移と逆転移の共謀、治療契約の問題などから生じ、その意味を理解することが打開の手がかりとなる。","a":"心理療法の過程が進展しなくなり、治療者とクライエントがともに膠着した状態から抜け出せなくなることをいう。症状が改善しない、面接が同じ話の繰り返しになる、改善の兆しが見えると悪化する陰性治療反応などとして現れる。背景には、クライエントの抵抗、治療者の逆転移とクライエントの転移が噛み合って無意識の共謀が生じていること、治療目標や治療構造についての合意の不十分さなどがある。打開には、スーパービジョンなどを通じて治療者自身の逆転移を吟味し、行き詰まりそのものの意味を理解して取り上げることが求められる。","k":["進展","膠着","陰性治療反応","逆転移","共謀","スーパービジョン"],"p":"博士後期の公開問題で問われた形式。「発生要因」と「打開への道」を対応させて書く。"},{"id":"anna-o","t":"アンナ・O","en":"Anna O.","f":"seishin","s":"ブロイアーが治療したヒステリーの女性患者の仮名。多様な身体症状や意識状態の交代を示し、症状の由来となった出来事を語ることで症状が消えた体験から、カタルシス法と「談話療法」が生まれ、精神分析の源流となった。","a":"ブロイアー（Breuer, J.）が1880年から治療した若い女性の仮名で、本名はベルタ・パッペンハイムである。父親の看病の途中から、四肢の麻痺、視覚の障害、神経性の咳、言語の混乱、母国語のドイツ語を話せず英語で話すことなどの多様な症状と、2つの意識状態の交代を示した。症状が初めて現れた場面を想起し、感情とともに語ると症状が消えることがわかり、本人はこれを「談話療法（talking cure）」と呼んだ。この症例はブロイアーとフロイトの『ヒステリー研究』（1895年）に収められ、カタルシス法、ひいては精神分析の出発点となった。","k":["ブロイアー/Breuer","ヒステリー","語","談話療法/talking cure","ヒステリー研究","カタルシス"],"p":"事例の見立て（素因・誘発因子・永続因子・保護因子）を練習する素材としても使える。転換症状と解離症状の両面をもつ症例である。"},{"id":"supportive","t":"支持的心理療法","en":"supportive psychotherapy","f":"rinsho","s":"クライエントの適応的な防衛や自我の機能を支え強めることで、症状の軽減や現実への適応を図る心理療法。洞察や人格の変化をめざす表現的（精神分析的）心理療法と対比され、両者は連続体をなすとされる。","a":"クライエントの自我の機能や適応的な防衛を支え、強めることで、不安や症状を軽減し、現実の生活への適応を図る心理療法である。傾聴と共感を基盤に、保証、励まし、助言、心理教育、問題解決の援助などを用い、退行を促さないよう対面で、現在の問題に焦点を当てる。これに対し精神分析的（表現的）心理療法は、転移や防衛を解釈して無意識の葛藤を意識化し、洞察と人格の変化をめざす。両者は対立するものではなく連続体をなし、クライエントの自我の強さや現実検討、目標に応じて組み合わせて用いられる。","k":["自我","適応","保証/励まし","精神分析的","洞察","連続体"],"p":"公開問題では両者の違いを「簡潔に」説明することが求められた。目標・技法・治療関係・適応の4点で対比すると整理しやすい。"},{"id":"double-bind","t":"二重拘束","en":"double bind","f":"rinsho","s":"ベイトソンらが提唱した、互いに矛盾するメッセージが異なる水準で同時に伝えられ、その場から逃れることも矛盾を指摘することもできない状況。逆にこの構造を治療的に用い、どう反応しても変化が生じるようにする介入を治療的二重拘束という。","a":"ベイトソン（Bateson, G.）らが1956年に提唱した、コミュニケーションにおける矛盾した状況をいう。たとえば言葉では「おいで」と言いながら、態度では拒否を示すように、異なる水準のメッセージが互いに矛盾し、しかも受け手はその場から逃れることも、矛盾を指摘することもできない状況である。当初は統合失調症の成因として提唱されたが、その仮説自体は支持されていない。家族療法では、この構造を逆に治療的に用い、症状をあえて続けるよう指示する（症状処方）など、クライエントがどう反応しても変化が生じるようにする介入を治療的二重拘束という。","k":["ベイトソン/Bateson","矛盾","逃れ","統合失調症","症状処方","治療的二重拘束"],"p":"公開問題では「治療的二重拘束」が語句として問われた。MRIやミラノ派の逆説的介入とあわせて整理する。"},{"id":"bowen-triangle","t":"三角関係化","en":"triangulation","f":"rinsho","s":"ボーエンの家族システム理論の概念。二者関係の緊張や不安が高まったとき、第三者を巻き込むことでその緊張を和らげ、関係を安定させようとする動き。子どもが夫婦の葛藤に巻き込まれる場合などにみられる。","a":"ボーエン（Bowen, M.）の家族システム理論の中心的な概念である。二者関係は不安や緊張が高まると不安定になりやすく、そのとき第三者を引き込むことで緊張を分散させ、関係を安定させようとする。この三者の関係（三角形）が家族の情緒的システムの基本単位とされる。たとえば夫婦の葛藤が直接扱われず、子どもの問題に夫婦の関心が向くことで夫婦関係が保たれる場合、子どもは三角関係に巻き込まれ、症状を示すことがある。治療では、治療者が中立を保ちながら家族の自己分化を促し、三角関係から脱すること（脱三角関係化）を支える。","k":["ボーエン/Bowen","二者関係","第三者","緊張","子ども","自己分化"],"p":"公開問題では家族療法の理論として問われた。ジェノグラム（多世代の家族図）とともに説明できると十分。"},{"id":"aa","t":"アルコホーリクス・アノニマス","en":"Alcoholics Anonymous","f":"rinsho","s":"1935年にアメリカで始まった、飲酒をやめたいと願う人々が互いの経験を分かち合い、支え合う自助グループ。12のステップと匿名性を特徴とし、他の依存症の自助グループの原型となった。","a":"1935年にアメリカで、アルコール依存の問題を抱えた2人の出会いから始まった、飲酒をやめたいと願う人々の自助グループである。専門家ではなく当事者どうしが、ミーティングで自らの経験を語り、聴き合い、支え合う。自分がアルコールに対して無力であることを認めることから始まる12のステップと、本名を明かさない匿名性を特徴とし、先輩のメンバーが新しいメンバーを支えるスポンサーの仕組みもある。薬物やギャンブルなどの自助グループの原型となり、日本では断酒会も広く活動している。専門的な治療と補い合う資源とされる。","k":["1935","自助グループ","当事者","12のステップ","匿名","断酒会"],"p":"自助グループの意義（普遍性、希望、役割の獲得＝ヘルパー・セラピー原則）とあわせて論じられる。"},{"id":"cbt-i","t":"不眠症の認知行動療法","en":"cognitive behavioral therapy for insomnia","f":"rinsho","s":"慢性不眠症に対する第一選択の心理療法。睡眠衛生の指導、寝床は眠るためだけに使う刺激制御法、床上時間を実際の睡眠時間に近づけて睡眠効率を高める睡眠制限法、睡眠についての考え方の修正などを組み合わせる。","a":"慢性的な不眠症に対して、薬物療法と並ぶ、あるいはそれ以上に推奨される心理療法である。カフェインや寝る前の画面の使用などを見直す睡眠衛生の指導、眠くなってから寝床に入り、眠れなければ寝床を離れて、寝床と眠りの結びつきを回復させる刺激制御法、寝床にいる時間を実際に眠れている時間に近づけて睡眠効率（実際の睡眠時間÷床上時間）を高め、効率が上がれば徐々に床上時間を延ばす睡眠制限法、「8時間眠らなければならない」といった考えを見直す認知再構成、リラクセーションなどを組み合わせる。","k":["不眠","睡眠衛生","刺激制御","睡眠制限","睡眠効率","認知再構成"],"p":"公開問題では「睡眠衛生」と「睡眠効率」の語を用いた説明が求められた。睡眠効率の計算式と目標値（85〜90％程度）まで書けると具体的。"},{"id":"ba","t":"行動活性化","en":"behavioral activation","f":"rinsho","s":"うつ病に対する行動療法的アプローチ。活動の記録と計画を通じて、楽しさや達成感をもたらす活動を増やし、回避や引きこもりの悪循環を断つことで、気分の改善をめざす。","a":"うつ病に対する行動療法的なアプローチで、認知行動療法の重要な構成要素でもある。うつ状態では、活動が減ることで楽しさや達成感を得る機会が失われ、さらに気分が落ち込み、つらさを避けるために引きこもるという悪循環が生じると考える。治療では、日々の活動と気分を記録して両者の関係に気づき、楽しさや達成感をもたらす活動を少しずつ計画して実行する。また、回避している行動の機能を分析し、価値に沿った代わりの行動を選ぶ。行動活性化の単独の効果が認知療法全体に劣らないことを示した研究もある。","k":["うつ病","楽しさ","達成感","悪循環","回避","記録"],"p":"うつ病の認知行動療法（ケース・フォーミュレーション、認知的技法、行動的技法）の論述では、行動的技法の中心として書ける。"},{"id":"erp","t":"曝露反応妨害法","en":"exposure and response prevention","f":"rinsho","s":"強迫症に対する認知行動療法の中心的技法。不安を引き起こす刺激に段階的に向き合い（曝露）、強迫行為や打ち消しをしないで不安が自然に低下していく体験をする（反応妨害）ことで、強迫観念と強迫行為の悪循環を断つ。","a":"強迫症に対する認知行動療法の中心的な技法である。強迫行為は一時的に不安を下げるため、それが強化されて強迫観念と強迫行為の悪循環が維持されると考える。治療では、不安を引き起こす状況を弱いものから強いものへ並べた階層表を作り、たとえば汚いと感じる物に触れるといった状況に段階的に向き合う（曝露）。そのうえで、手洗いや確認などの強迫行為や頭の中の打ち消しをしないでとどまる（反応妨害）。不安は行為をしなくても自然に下がることを体験し、予測が現実にならないことを学習していく。","k":["強迫症","曝露","反応妨害","強迫行為","悪循環","階層表"],"p":"公開問題では強迫症の認知行動療法について「強迫観念」「強迫行為」の語を用いて説明することが求められ、曝露反応妨害法が要点とされた。"},{"id":"relaxation-response","t":"リラクセーション反応","en":"relaxation response","f":"rinsho","s":"ベンソンが提唱した、ストレス時の闘争・逃走反応とは逆に、心拍数、血圧、呼吸数、酸素消費量などが低下する生理的な状態。特定の語の反復と受動的な態度によって誘導でき、漸進的筋弛緩法や自律訓練法なども同じ反応をもたらす。","a":"ベンソン（Benson, H.）が1970年代に提唱した概念で、ストレスに直面したときの闘争・逃走反応とは逆に、副交感神経系が優位となり、心拍数、血圧、呼吸数、代謝（酸素消費量）が低下する、心身のくつろいだ状態をいう。静かな環境で楽な姿勢をとり、特定の語や音を心の中で繰り返し、浮かんでくる雑念にとらわれず受け流す受動的な態度をとることで誘導できるとした。ジェイコブソンの漸進的筋弛緩法やシュルツの自律訓練法も、同様の反応をもたらす方法として知られる。ストレス関連の症状や不安の軽減に用いられる。","k":["ベンソン/Benson","闘争・逃走/闘争","副交感神経","受動的","漸進的筋弛緩法","自律訓練法"],"p":"系統的脱感作法（リラクセーションを拮抗反応として用いる）との関係も押さえておく。"},{"id":"world-technique","t":"世界技法","en":"world technique","f":"rinsho","s":"ローエンフェルトが考案した、砂の入った箱とミニチュアを用いて子どもが自分の「世界」を自由に表現する技法。言語表現の未熟な子どもの内面の表現を重視し、のちにカルフの箱庭療法の基礎となった。","a":"イギリスの小児科医ローエンフェルト（Lowenfeld, M.）が1929年ごろに考案した技法で、砂の入った箱と、人や動物、建物などの多くのミニチュアを用いて、子どもが自分の「世界」を自由に作る。言葉で十分に表現できない子どもが、砂箱という世界の中で自由に遊び、内面を表現できるようにすることを目的とした。のちにカルフ（Kalff, D. M.）がユング心理学の立場から、治療者との関係の中で無意識のイメージが表現され統合されていく過程を重視する箱庭療法へと発展させた。ビューラーはこれを標準化して検査（世界テスト）とした。","k":["ローエンフェルト/Lowenfeld","砂","ミニチュア","子ども","カルフ/Kalff","箱庭療法"],"p":"公開問題では世界技法と箱庭療法の対比が問われ、学問的背景（精神分析／分析心理学）、目的、使い方（表現・診断／治療）、対象などで対比することが求められた。"},{"id":"forensic-interview","t":"司法面接","en":"forensic interview","f":"trauma","s":"虐待や犯罪の被害を受けた疑いのある子どもなどから、できるだけ正確な情報を、精神的な負担を最小限にしながら聴き取るための面接法。誘導を避けて自由報告を中心とし、録画して繰り返しの聴取を防ぐ。","a":"虐待や犯罪の被害を受けた疑いのある子どもや障害のある人などから、事実についてのできるだけ正確な情報を、精神的な負担を最小限にしながら聴き取るための面接法である。子どもの記憶は暗示や誘導的な質問の影響を受けやすく、繰り返し事情を聴かれることは二次被害にもなる。そのため、ラポールの形成とルールの説明を行い、「何があったか話して」といった開かれた質問で自由に話してもらうことを中心とし、誘導的な質問を避け、面接を録画する。日本では児童相談所・警察・検察による協同面接も行われている。","k":["子ども","正確","負担","誘導","開かれた質問","録画"],"p":"治療的な面接（感情の表出を支える）とは目的が異なることを区別して書く。"},{"id":"gbv","t":"ジェンダーに基づく暴力","en":"gender-based violence","f":"trauma","s":"社会的な性別（ジェンダー）を理由として、あるいは特定の性別に不均衡な影響を及ぼす形で行われる暴力。性暴力、配偶者などからの暴力、性的ハラスメントなどを含み、ジェンダーの不平等という社会構造を背景とする。","a":"社会的・文化的な性別（ジェンダー）を理由として、あるいは特定の性別の人々に不均衡な影響を及ぼす形で行われる、身体的、性的、心理的、経済的な暴力や強制をいう。配偶者や交際相手からの暴力（DV）、性暴力、性的ハラスメント、ストーカー行為、人身取引などが含まれる。被害者の多くは女性であるが、男性や性的マイノリティも被害を受ける。個人の問題としてではなく、ジェンダーの不平等という社会構造を背景とした人権侵害としてとらえる視点が重要であり、支援ではトラウマへのケアとともに、安全の確保と社会資源への接続が求められる。","k":["ジェンダー","不均衡","DV","性暴力","社会構造","人権"],"p":"心理社会的問題を「個人から社会までの多層的な観点（生態学的モデル）」で説明する論述にも使える。"},{"id":"pce","t":"小児期の保護的・肯定的体験","en":"positive childhood experiences","f":"trauma","s":"子ども時代に経験した、家族に気持ちを話せた、困ったときに支えてもらえた、家族以外の大人に関心をもってもらえたなどの肯定的な関係の体験。逆境的小児期体験の影響を緩和し、成人期の心の健康と関連することが示されている。","a":"子ども時代に経験した、安心できる肯定的な関係の体験をいう。家族に自分の気持ちを話せた、困ったときに家族が支えてくれた、学校や地域に居場所や所属感があった、友人に支えられた、家族以外の大人が自分に関心を寄せてくれた、家庭で安全だと感じられた、といった体験が含まれる。ベセル（Bethell, C.）らの研究では、こうした体験が多いほど、逆境的小児期体験の有無にかかわらず、成人期の抑うつが少なく、良好な人間関係をもつことが示された。逆境の影響を緩和する保護的な要因として、予防や支援の手がかりとなる。","k":["肯定的","家族","大人","ベセル/Bethell","逆境的小児期体験","保護的"],"p":"公開問題ではACEsの影響と、それを緩和する体験の両方が問われた。神経発達（ストレス反応系）の観点もあわせて書く。"},{"id":"grief-counseling","t":"悲嘆カウンセリングと悲嘆セラピー","en":"grief counseling and grief therapy","f":"trauma","s":"ウォーデンの区別で、悲嘆カウンセリングは通常の悲嘆の過程にある人が喪の課題を進めるのを支える援助、悲嘆セラピーは遷延した、あるいは複雑化した悲嘆に対する専門的な治療をいう。","a":"ウォーデン（Worden, J. W.）による区別である。悲嘆カウンセリングは、死別後の通常の（複雑化していない）悲嘆の過程にある人が、喪失の現実を受け入れる、悲嘆の苦痛を経験する、故人のいない環境に適応する、故人との永続的なつながりを見いだしつつ新たな人生を歩む、という喪の課題を進められるよう支える援助である。悲嘆セラピーは、悲嘆が長期化したり、強い自責や回避を伴って複雑化したりしている場合に行われる、より専門的な治療であり、遷延性悲嘆症に焦点を当てた心理療法などがある。","k":["ウォーデン/Worden","通常","喪の課題","複雑化","専門的","遷延性悲嘆症"],"p":"悲嘆を病理化しすぎないこと（多くの人には特別な介入は不要）も添えると適切。"},{"id":"somatization","t":"身体化","en":"somatization","f":"iryo","s":"心理的な苦痛やストレスが、身体の症状として体験され表現されること。身体症状に医学的な説明がつかない場合も多く、本人は身体の問題として医療を求める傾向がある。","a":"心理的な苦痛や葛藤、ストレスが、頭痛、腹痛、疲労感などの身体の症状として体験され、表現されることをいう。リポウスキーは、身体の症状として苦痛を体験し訴え、それを身体の病気によるものと考えて医療を求める傾向と定義した。身体化は誰にでも起こりうる現象であり、感情を言葉で表現することが文化的に好まれない場合や、感情に気づきにくい場合（アレキシサイミア）に生じやすい。DSM-5の身体症状症のように、症状への過度なとらわれが生活に支障をきたす場合もある。支援では、症状を「気のせい」と否定せず、身体の訴えを受け止めることが大切である。","k":["心理的","身体の症状","リポウスキー","医療","アレキシサイミア","身体症状症"],"p":"心身症（身体疾患そのもの）との違いを区別して書く。"},{"id":"differential-dx","t":"鑑別診断","en":"differential diagnosis","f":"iryo","s":"よく似た症状を示す複数の疾患や状態を比較し、どれに該当するかを見極めること。たとえば境界性パーソナリティ障害では、双極性障害、複雑性PTSD、ADHDなどとの鑑別が問題となる。","a":"ある症状や状態を示す人について、よく似た症状を示す複数の疾患や状態の可能性を比較検討し、どれに該当するのか、あるいは併存しているのかを見極めることをいう。正確な鑑別は、適切な治療や支援を選ぶための前提となる。たとえば境界性パーソナリティ障害では、気分の変動が双極性障害と、感情調節や対人関係の困難が複雑性PTSDと、衝動性がADHDと似ているため、症状の持続期間や経過、生育歴、トラウマの有無などを丁寧に確認する必要がある。身体疾患や薬物の影響の除外も欠かせない。心理職は、心理検査や詳細な生活歴の情報によって医師の鑑別を助ける。","k":["似た症状","比較","双極性障害","複雑性PTSD","ADHD","身体疾患"],"p":"公開問題では境界性パーソナリティ障害の鑑別診断が問われた。「何と、何を手がかりに見分けるか」を表にしておく。"},{"id":"chc","t":"CHC理論","en":"Cattell-Horn-Carroll theory","f":"assess","s":"キャッテルとホーンの流動性知能・結晶性知能の理論と、キャロルの三層理論を統合した知能の理論。一般知能g、流動性推理や結晶性知能などの広範能力、多数の限定的能力の3層からなり、知能検査の解釈の枠組みとなる。","a":"キャッテルとホーンの流動性知能・結晶性知能（Gf-Gc）理論と、キャロルが多数の研究を因子分析で再分析して提唱した三層理論を統合した知能の理論である。最上位の第3層に一般知能g、中間の第2層に流動性推理（Gf）、結晶性知能（Gc）、短期記憶、視覚処理、聴覚処理、長期記憶と検索、処理速度などの広範能力、最下位の第1層に多数の限定的な能力を位置づける。現在の知能検査の多くはこの理論を参照して作られており、検査結果を領域ごとの能力の強みと弱みとして解釈する枠組みとなっている。","k":["キャッテル/ホーン","キャロル","三層","一般知能/g","流動性","結晶性"],"p":"流動性知能（新しい問題解決、加齢で低下しやすい）と結晶性知能（経験による知識、高齢まで維持）の違いもあわせて書けるようにする。"},{"id":"ratio-iq","t":"比率IQと偏差IQ","en":"ratio IQ and deviation IQ","f":"assess","s":"比率IQは精神年齢を生活年齢で割って100をかけた値で、ビネー式検査で用いられた。偏差IQは同年齢集団の平均を100、標準偏差を15などとして個人の相対的な位置を示す値で、ウェクスラーが導入した。","a":"比率IQは、知能検査で測定した精神年齢を生活年齢（実年齢）で割り、100をかけて求める知能指数であり、シュテルンが提唱し、スタンフォード・ビネー検査で広く用いられた。精神年齢が実年齢と等しければ100となる。しかし知能の伸びは青年期以降緩やかになるため、成人では比率IQが意味をなさなくなる。偏差IQは、同じ年齢集団の得点分布の中での個人の相対的な位置を、平均100、標準偏差15（または16）の尺度で表したもので、ウェクスラーが導入した。現在の多くの知能検査では偏差IQが用いられている。","k":["精神年齢","生活年齢","100","成人","偏差IQ","ウェクスラー"],"p":"公開問題で比率IQが語句として問われた。成人に適用できない理由まで書けると十分。"},{"id":"mssm","t":"MSSM（交互ぐるぐる描き物語統合法）","en":"Mutual Scribble Story Making","f":"assess","s":"山中康裕が考案した描画法。画用紙を複数の枠に区切り、治療者とクライエントが交互にぐるぐる描きをして相手の線から見えるものを描き、最後にクライエントがすべての絵を使って物語を作る。","a":"山中康裕が1984年に発表した描画を用いた心理療法の技法である。ナウムバーグのスクリブル法と、ウィニコットのスクイグル法をもとに発展させたものである。画用紙を6〜8程度のこまに区切り、治療者とクライエントが交互に、一方がぐるぐる描き（なぐり描き）をし、もう一方がその線から見えてくるものを描き加えて彩色する。最後に、クライエントがすべてのこまの絵を用いて一つの物語を作る。投影と物語の統合を通して、治療者とクライエントの交流を深め、遊びの空間とゆとりを取り戻すことがめざされる。","k":["山中康裕","ナウムバーグ/スクリブル","スクイグル/ウィニコット","交互","物語","交流"],"p":"公開問題では語句として問われた。スクイグル法との違い（最後に物語を作る）を一言入れると正確。"},{"id":"squiggle","t":"スクイグル法","en":"squiggle game","f":"assess","s":"ウィニコットが子どもとの面接で用いた描画の技法。治療者となぐり描きの線を描いて子どもに何かに見立てて仕上げてもらい、次は役割を交代するというやりとりを繰り返し、子どもとの交流と理解を深める。","a":"ウィニコットが子どもとの治療的なコンサルテーションで用いた描画の技法である。治療者が紙に自由な線（なぐり描き）を描き、子どもがそれを何かに見立てて絵に仕上げる。次に子どもが線を描き、治療者が仕上げるというように、役割を交代しながら繰り返す。遊びのような相互的なやりとりの中で、子どもの関心や感情が自然に表現され、治療者と子どもの間に交流が生まれる。日本には中井久夫によって紹介され、山中康裕のMSSMの基礎となった。","k":["ウィニコット","子ども","なぐり描き","交代","相互","中井久夫"],"p":"ウィニコットの「遊ぶこと」「移行領域」の考えとつなげると深い答案になる。"},{"id":"four-p","t":"4Pモデル","en":"4P model of case formulation","f":"assess","s":"事例の見立てを、発症以前からの脆弱性である素因、発症のきっかけとなった誘発因子、改善を妨げ状態を維持する永続因子、悪化に抵抗し回復を支える保護因子の4つの観点から整理する枠組み。","a":"ケース・フォーミュレーションの枠組みの一つである。素因（predisposing）は、遺伝的要因や生育環境など、発症以前からの脆弱性である。誘発因子（precipitating）は、喪失や過重な負担など、発症の直接のきっかけとなった出来事である。永続因子（perpetuating）は、回避や周囲の対応、症状による二次的な不安など、状態の改善を妨げ維持する要因である。保護因子（protective）は、本人の強みや支援者の存在など、悪化に抵抗し回復を支える要因である。生物・心理・社会の各側面と組み合わせて用いられる。","k":["素因","誘発因子","永続因子","保護因子","強み","生物"],"p":"公開問題では、事例をもとに4つの因子の意味と具体的な仮説を論じる問題が出された。各因子の定義を一文で言えるようにしておく。"},{"id":"neuropsych-test","t":"神経心理学的検査","en":"neuropsychological tests","f":"assess","s":"記憶、注意、言語、視空間認知、実行機能などの認知機能を測定し、脳の損傷や機能障害との関連を評価する検査の総称。認知症のスクリーニングや鑑別、ケアの方針づくりなどに用いられる。","a":"記憶、注意、言語、実行機能などの認知機能を評価し、脳の損傷や機能障害との関連を明らかにする検査の総称である。認知症の評価では、スクリーニングとしてHDS-RやMMSE、軽度の障害の検出にMoCA-J、記憶の詳しい評価にウェクスラー記憶検査、実行機能の評価にウィスコンシン・カード分類検査やTMTなどが用いられる。目的は、スクリーニング、鑑別診断の補助、障害された機能と保たれている機能の把握によるケアや支援の方針づくり、経過の評価などである。結果の解釈では、教育歴、視聴覚の障害、抑うつ、疲労や意欲などの影響を考慮する必要がある。","k":["認知機能","脳","認知症","MMSE/HDS-R","教育歴","抑うつ"],"p":"公開問題では、目的・方法・解釈の留意点が問われた。「保たれている機能（強み）を把握し、ケアに活かす」という視点を必ず入れる。"},{"id":"eap","t":"従業員支援プログラム（EAP）","en":"employee assistance program","f":"rinri","s":"企業などの組織が、従業員の仕事上や個人的な問題（メンタルヘルス、家族、依存など）に対し、相談やカウンセリングなどの支援を提供する仕組み。組織への助言も含み、社内型と外部の専門機関に委託する社外型がある。","a":"企業などの組織が、従業員の業績や健康に影響を及ぼしうる仕事上・個人的な問題（メンタルヘルス、家族、職場の人間関係、アルコールなどの依存の問題など）に対して、相談やカウンセリング、医療機関などへの紹介といった支援を提供する仕組みである。アメリカで、職場のアルコール問題への対策から発展した。従業員本人への支援に加えて、管理監督者や人事部門へのコンサルテーション、復職支援、惨事後の支援なども含む。組織内に専門家を置く社内型と、外部の専門機関に委託する社外型があり、秘密保持が利用の前提となる。","k":["従業員","組織","相談/カウンセリング","アルコール","コンサルテーション","秘密保持"],"p":"職場のメンタルヘルスの4つのケア（事業場外資源によるケア）との関係で位置づける。"},{"id":"collaboration","t":"コラボレーション（協働）","en":"collaboration","f":"rinri","s":"異なる専門性をもつ者どうしが、共通の目標に向けて対等な立場で協力し、責任を分かち合いながら支援を行うこと。指導関係にあるスーパービジョンや、助言にとどまるコンサルテーションとは区別される。","a":"異なる専門性や立場をもつ者どうしが、共通の目標に向けて対等な立場で協力し、計画から実行、評価までの責任を分かち合いながら支援を行うことをいう。医療、教育、福祉などの多職種連携の中核となる考え方である。上下関係のもとで同じ職種の者が指導を受けるスーパービジョンや、コンサルティが事例の責任を負い、コンサルタントは助言にとどまるコンサルテーションとは、関係のあり方と責任の所在において異なる。コラボレーションを進めるには、互いの専門性と限界を理解し、情報共有と秘密保持の範囲を合意しておくことが重要である。","k":["異なる専門性","対等","責任","多職種連携","スーパービジョン","コンサルテーション"],"p":"公開問題では、スーパービジョン・コンサルテーション・コラボレーションの違いを明確にする論述が出た。「関係（上下か対等か）」と「責任の所在」を軸に表にしておく。"},{"id":"suicide-pip","t":"自殺のプリベンション・インターベンション・ポストベンション","en":"suicide prevention, intervention, postvention","f":"rinri","s":"自殺対策の3つの段階。プリベンションは自殺が起こる前の教育や環境づくりなどの予防、インターベンションは自殺の危険が高まった人への危機介入、ポストベンションは自殺が起きた後の遺された人々への心理的支援と連鎖の防止である。","a":"シュナイドマンらによって整理された、自殺対策の3つの段階である。プリベンション（事前予防）は、自殺が起こる前に、心の健康教育、ゲートキーパーの養成、相談窓口の周知、危険な手段へのアクセスの制限などによって自殺の発生を防ぐことである。インターベンション（危機介入）は、自殺の危険が高まっている人に対して、危険度を評価し、安全を確保し、医療などの支援につなげることである。ポストベンション（事後対応）は、自殺が起きた後に、遺族や友人、同僚、学校の児童生徒などの心理的な影響を最小限にし、自殺の連鎖を防ぐための支援である。","k":["シュナイドマン","プリベンション","ゲートキーパー","インターベンション","ポストベンション","連鎖"],"p":"公開問題では3つの内容をそれぞれ具体的に述べることが求められた。学校や職場の場面に置き換えた具体例を一つずつ準備する。"},{"id":"stigma","t":"スティグマ","en":"stigma","f":"rinri","s":"特定の属性をもつ人に対して社会が付与する否定的なレッテルや偏見と、それにもとづく差別。精神疾患や認知症では、周囲からの偏見に加えて、本人が偏見を内面化するセルフ・スティグマが受診や援助要請を妨げる。","a":"ゴフマン（Goffman, E.）が論じた、特定の属性をもつ人に対して社会が付与する否定的なレッテルと、それにもとづく偏見や差別をいう。精神疾患や認知症、障害などに対するスティグマは、就労や社会参加の機会を奪うだけでなく、本人が社会の偏見を自分自身に向けて内面化するセルフ・スティグマを生み、受診や援助要請をためらわせる。スティグマの軽減には、正しい知識を伝える教育、当事者と直接接する機会をつくる接触（最も効果が大きいとされる）、権利擁護の活動などが有効とされる。心理職は、アセスメントや心理支援、教育・啓発、研究を通じて貢献できる。","k":["ゴフマン/Goffman","レッテル","偏見","セルフ・スティグマ","援助要請","接触"],"p":"公開問題では、認知症のスティグマの軽減に心理職がどう貢献できるかが問われた。心理職の業務（アセスメント・支援・教育啓発・研究）に沿って書くと構成しやすい。"}]);
